window.PROJECTS_DATA = {"generated_from":"backend/projects-data/iids-projects.csv","source_updated":"2026-08-20","count":126,"fields":["objectid","title","gist","description","abstract","significance","project_type","lead","affiliation","partners","funder","award_number","date","end_year","status","subject","program","infrastructure","deliverables","confidence","evidence_note","source_url","project_url","funder_agency","research_area","parent_project"],"items":[{"objectid":"nih_zhang_holistic_approach_interactive","title":"A holistic approach to interactive medical diagnosis via large language model","gist":"Developing an interactive AI system for melanoma diagnosis using large language models and dermoscopy images to aid clinicians and train medical students.","description":"This project develops an AI-assisted diagnosis system for dermoscopy image-based melanoma by combining high recognition accuracy with the interactive capabilities of large language models. The research addresses critical barriers to broader application, including privacy, legality, transparency, and interpretability concerns that currently hinder existing diagnostic tools. By generating textual case descriptions from medical images and creating specialized models, the work establishes a novel framework for interactive diagnostics. The initiative also pioneers the integration of AI-driven virtual patients into medical education to enhance the training of future professionals.","abstract":"Melanoma is the primary cause of most skin cancer-related fatalities. Timely detection and appropriate \ntreatment considerably boost the survival chances of melanoma patients. Dermoscopy image-based \nmelanoma diagnosis, noted for its precision and ease, is eagerly anticipated. However, despite AI-based \ndiagnostic systems achieving accuracy levels comparable to human dermatologists, their broader \napplication is hindered by concerns regarding privacy, legality, transparency, and interpretability. \nAddressing these issues to enhance the intelligence and reliability of smart diagnostic systems, \nparticularly in offering interactive features, is imperative. \nThe advent of large language models (LLMs), pre-trained on extensive textual data, presents potential \nsolutions to these challenges. This research aims to establish an AI-assisted diagnosis system for \ndermoscopy image-based melanoma, combining high recognition accuracy with the interactive \ncapabilities of LLMs. Such a system could aid dermatologists in diagnosis and act as virtual patients for \nmedical training, creating a novel framework for interactive AI-assisted diagnostics using LLMs and \nmarking a pioneering step in applying LLMs to dermoscopy image-based melanoma diagnosis. \nAim 1 focuses on developing an AI-driven pipeline to automatically generate textual case descriptions \nfrom medical images. Aim 2 involves creating LLMs specialized in melanoma dermoscopy diagnosis. Aim \n3 aims to develop and validate AI-driven diagnostic assistants and virtual patients in medical educational \nsettings. This research could significantly impact computer-aided skin cancer diagnosis by bridging the \ngap between medical image analysis and LLMs. Furthermore, it will pioneer integrating AI-driven virtual \npatients into medical education, enhancing the training of future medical professionals.","project_type":"Grant","lead":"Boyu Zhang","affiliation":"RCI IMCI","partners":"National Institutes of Health","funder":"Center for Modeling Complex Interactions","award_number":"P20GM104420","date":"2024","end_year":"2025","status":"Active","subject":["melanoma","dermoscopy","large language models","computer-aided diagnosis","medical image analysis","virtual patients","medical education"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/11013692","funder_agency":"National Institutes of Health","research_area":"Health & disease"},{"objectid":"usda_karl_acquisition_drone_mounted","title":"Acquisition of a drone-mounted aerial Lidar system to support agricultural and natural-resources research.","gist":"University of Idaho purchases a drone-mounted YellowScan Mapper+ Lidar system to enable on-demand, high-resolution elevation and canopy data for agricultural and natural resource research.","description":"The University of Idaho acquires a drone-mounted YellowScan Mapper+ Lidar system to generate high-resolution elevation and canopy height data for sustainable agriculture and natural resource management. This technology penetrates plant canopies to measure ground elevation, supporting research in precision agriculture, forestry, rangeland ecology, and hydrology. Housing the system in the UI Drone Lab eliminates costly external data contracts, providing faculty across the Colleges of Agricultural and Life Sciences, Natural Resources, and Engineering with flexible, on-demand access for teaching and high-impact studies.","abstract":"High-resolution remotely-sensed elevation measurements are critical inputs to addressing many pressing questions in sustainable agriculture and natural resource management. Light detection and ranging (Lidar) is an active sensor technology that measures distance with laser pulses, and because it can penetrate plant canopies, is commonly used to measure ground elevation and plant canopy height. Over the past decade, Lidar sensors have become smaller and lighter, enabling deployment via unmanned aerial systems (UAS, i.e., drones) for capturing on-demand, high-resolution elevation and height data. The University of Idaho (UI) is requesting an airborne Lidar system mounted to UAS to enhance institutional capabilities of UI researchers and research training. Specifically, we propose to purchase a YellowScan Mapper+ Lidar sensor mounted to a Freefly Systems AltaX UAS. The Lidar system will be used to further UI's research and teaching in precision agriculture, precision forestry, rangeland ecology and management, and hydrology. This Lidar system will be housed in and maintained by the UI Drone Lab, implemented in a selected set of ongoing or new projects, and available to faculty in the UI College of Agricultural and Life Sciences, College of Natural Resources, and College of Engineering for research and teaching. A UAS Lidar system will increase the UI's ability to compete for large, cross-disciplinary extramural grants and conduct high-impact research in sustainable agriculture and natural resource management. The UI does not own an aerial Lidar system, and must contract aerial Lidar data acquisitions, which is costly, inhibits flexibility and discourages projects needing frequent data acquisition.","project_type":"Grant","lead":"Jason Karl","affiliation":"CNR Forest, Rangeland & Fire Sci","funder":"National Institute of Food and Agriculture/USDA","award_number":"2023-70410-41214","date":"2023","status":"Active","subject":["lidar","unmanned aerial systems","precision agriculture","canopy height","digital elevation models","remote sensing","rangeland ecology"],"confidence":"High","source_url":"https://web.archive.org/web/20250502095834/https://portal.nifa.usda.gov/web/crisprojectpages/1031484-acquisition-of-a-uas-mounted-aerial-lidar-system-to-support-agricultural-and-natural-resources-research.html","project_url":"https://uidronelab.org","funder_agency":"USDA","research_area":"Agriculture"},{"objectid":"ai4ui","title":"AI4UI","description":"A coordination nexus for the University of Idaho’s institutional AI work, operated by the Institute for Interdisciplinary Data Sciences (IIDS).","project_type":"Program","status":"Active","subject":["artificial intelligence"],"confidence":"High","source_url":"ai4ui.html","research_area":"Data science & computing"},{"objectid":"nih_udekwu_altering_microbiome_composition","title":"Altering microbiome composition through rationally designed antimicrobial regimen","gist":"The IMCI Pilot Grant Program supports seed research at the University of Idaho that integrates modeling and empirical data to solve human health challenges.","description":"Part of the IMCI Pilot Grant Program at the University of Idaho, which fosters research combining modeling with empirical data to address complex human health problems. These seed grants provide modest funding for new research ideas, projects, or collaborations, with the expectation that funded principal investigators will submit subsequent proposals to the NIH or other agencies.","project_type":"Grant","lead":"Klas Udekwu","affiliation":"RCI IMCI","funder":"National Institutes of Health","date":"2023","status":"Active","subject":["microbiome","antimicrobial","regimen","human health","modeling","composition"],"confidence":"High","source_url":"https://imci.uidaho.edu/research-projects/pilot-projects/","project_url":"https://imci.uidaho.edu/research-projects/pilot-projects/","funder_agency":"National Institutes of Health","research_area":"Health & disease"},{"objectid":"wdfw_karl_assessing_utility_drones","title":"Assessing the utility of drones for pheasant and turkey surveys","gist":"Researchers test drone accuracy for detecting pheasants and turkeys across ten Eastern Washington counties to improve wildlife monitoring protocols.","description":"University of Idaho Drone Lab researchers collaborate with Washington Department of Fish and Wildlife staff to evaluate the effectiveness of drones for monitoring pheasant and turkey populations. Flights occur across ten counties in the department's Eastern region to determine which drone models accurately detect birds under varying habitat and flight conditions. The pilot project generates specific recommendations for biologists on integrating drone technology into long-term survey protocols to enhance monitoring efforts for these game birds.","abstract":"OLYMPIA – Washington Department of Fish and Wildlife (WDFW) staff and University of Idaho Drone Lab researchers will fly drones over known turkey and pheasant locations over the next few months to test whether drones are a useful tool for monitoring these birds.\n\nFlights will take place in the department’s Eastern region (Region 1) encompassing Asotin, Columbia, Ferry, Garfield, Lincoln, Pend Oreille, Spokane, Stevens, Walla Walla, and Whitman counties.\n\nThe purpose of this pilot research project is to test which drones can accurately detect birds in various habitats and flight conditions. Researchers will also recommend the most appropriate ways biologists can use drones to survey turkeys and pheasants over time to improve monitoring efforts.\n\nFlights will take place from March through August 2023 in compliance with all federal and state regulations. Flight timing will depend on the presence of birds and suitable flight conditions.","project_type":"Contract","lead":"Jason Karl","affiliation":"CNR Forest, Rangeland & Fire Sci","funder":"Washington Department of Fish & Wildlife","date":"2023","status":"Active","subject":["drones","wildlife monitoring","pheasant","wild turkey","remote sensing","habitat survey","eastern washington"],"confidence":"Medium","source_url":"https://wdfw.wa.gov/newsroom/news-release/researchers-conduct-drone-flights-turkey-and-pheasant-monitoring","funder_agency":"State agency","research_area":"Ecology & wildlife"},{"objectid":"ai4ui_audit-dashboard","title":"Audit Dashboard","description":"Full-stack dashboard for tracking internal audit observations, corrective action items, and responsible-party assignments. Ingests audit report PDFs via OCR + LLM extraction (MindRouter dots.OCR + Qwen3), with human review before persistence.","significance":"Closes the audit follow-through loop. Reduces risk of observations lingering past target dates. Gives leadership a living compliance-posture view.","status":"Paused","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_bid-waiver-document-review","title":"Bid Waiver Document Review","description":"A Vandalizer module that verifies three-quote compliance on purchases and reviews bid-waiver justifications against procurement rules, giving purchasing approvers and auditors a transparent rationale trail for sourcing decisions.","significance":"Faster waiver approvals with a transparent, auditable rationale — lawful sourcing with less manual document review.","status":"Exploring","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_bls-cupa-code-prediction","title":"BLS Code Prediction","description":"A Vandalizer module that suggests Bureau of Labor Statistics occupation codes from a job description, replacing manual code identification in HR's classification workflow. Originally scoped to cover CUPA codes as well; narrowed to BLS for the first delivery.","significance":"Replaces manual code lookup — an estimated 0.5 FTE of HR classification effort returned, with more consistent coding across positions.","status":"Exploring","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nsf_etienne_boosting_algorithmic_efficiency","title":"Boosting Algorithmic Efficiency: Numerical Relativity in Dynamical, Curvilinear Coordinates","gist":"BlackHoles@Home uses volunteer desktop computers to generate massive gravitational wave catalogs via optimized numerical relativity simulations of binary black holes and neutron stars.","description":"This project develops algorithmic improvements to numerical relativity simulations, enabling binary black hole modeling on consumer-grade desktop computers through the BlackHoles@Home citizen-science initiative. By fitting complex Einstein equation solutions into just a few gigabytes of RAM, the work overcomes the throughput limitations of traditional supercomputer clusters that have historically restricted gravitational wave catalogs to approximately 3,000 events. The resulting high-volume catalog generation supports detailed parameter estimation for current and future gravitational wave detectors while incorporating advanced physics for binary neutron star simulations. Public engagement efforts include educational convocations in underserved high schools and a global newsletter to recruit volunteer computing resources.","abstract":"This award supports research in relativity and relativistic astrophysics and it addresses the priority areas of NSF's \"Windows on the Universe\" Big Idea. Einstein’s theory of general relativity (GR) provides science's current best understanding of gravity. It predicts the existence of bizarre objects like black holes and neutron stars, and ripples in spacetime called gravitational waves. These predictions motivated the construction of NSF's Laser Interferometer Gravitational-wave Observatory (LIGO), which has detected several gravitational wave signals from colliding black holes and neutron stars over the past years. For their efforts in making these detections possible, the leaders of LIGO were awarded the 2017 Nobel Prize in Physics. Much of gravitational wave (GW) science depends on GW observations being compared with millions of theoretical predictions, which must be built upon GW catalogs extracted from numerical relativity (NR) simulations. NR simulations solve the GR equations in full on the computer, and to date each of these NR simulations has required a small computing cluster, which has limited throughput to only about 3,000 GWs in 15 years. Given the vast number of possible scenarios for even the simplest and most commonly observed GW source, binary black holes (BBHs), such a small GW collection threatens potential science gains from future GW observations. BlackHoles@Home is a proposed citizen-science project leveraging new techniques to fit NR BBH simulations on a consumer-grade desktop computer, enabling new GW catalog generation with unprecedented throughput using volunteer computers. Such throughput will enable far more detailed analyses of observed GWs from current and future GW detectors, maximizing the science gained from hard-fought observations. To educate the public and advertise this volunteer computing project both locally and globally, convocations will be given in underserved high schools, and updates will be posted to a widely disseminated BlackHoles@Home email newsletter.\n\nImprovements to the algorithmic and mathematical underpinnings of NR codes have recently culminated in a coming-of-age for the field, moving it beyond proof-of-principle calculations and into the realm of predictive astrophysics. Over the past six years, NR-based theoretical predictions of gravitational waves (GWs) were central to uncovering the binary parameters in LIGO and Virgo's recent GW discoveries. Looking ahead, GW catalogs generated by NR simulations of compact binaries will need to grow greatly to ensure that parameter estimation accuracy can keep up with increased sensitivity of GW interferometers. BlackHoles@Home is a proposed BOINC project that aims to fit binary black hole (BBH) simulations on the consumer-grade desktop computer. In doing so the general public can be enlisted to help generate the large GW catalogs that form the foundation for a great deal of GW science. Traditionally, these BBH simulations have been performed on supercomputers. BlackHoles@Home implements new approaches for robustly solving Einstein's equations of general relativity in highly efficient coordinate systems, so that these simulations will fit on consumer-grade desktop computers in only a few gigabytes of RAM. BlackHoles@Home's core infrastructure provides a firm foundation for compact binary simulations beyond BBHs. To this end, the dynamical-spacetime GRMHD code IllinoisGRMHD will be incorporated into this infrastructure to enable state-of-the-art binary neutron star simulations on supercomputers. These simulations will leverage both recent advances in solving the GRMHD equations in spherical-like coordinate systems, as well as recent improvements to IllinoisGRMHD that add both advanced nuclear equation of state support and basic neutrino physics. Monte-Carlo-based photon and neutrino feedback will also be incorporated to enable state-of-the-art realism in these binary neutron star simulations.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Zachariah Etienne","affiliation":"COS Physics","funder":"National Science Foundation","award_number":"2508377","date":"2025","end_year":"2025","status":"Active","subject":["numerical relativity","gravitational waves","binary black holes","binary neutron stars","general relativity","citizen science","volunteer computing"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2508377","project_url":"http://blackholesathome.net/","funder_agency":"National Science Foundation","research_area":"Physics & astronomy"},{"objectid":"nasa_etienne_bringing_gravitational_wave","title":"Bringing gravitational-wave astronomy into the Space Age: Next-generation waveform modeling of black-hole binary coalescences for LISA data analysis","gist":"Developing accurate waveform models for LISA to analyze black-hole binary coalescences using the backward one-body method.","description":"This project develops next-generation waveform models for the Laser Interferometer Space Antenna (LISA), a planned space-based gravitational wave observatory scheduled for launch in 2035. Led by Sean McWilliams at West Virginia University with support from NASA, the research focuses on accurately modeling the inspirals and mergers of both stellar-mass and supermassive black-hole binaries. By improving upon the existing 'backward one-body method' and enhancing current inspiral models, the team aims to create highly accurate templates necessary to extract scientific insights from LISA's superior signal-to-noise ratio. These advancements will enable detailed studies of black hole spins, eccentricities, and formation histories that remain inaccessible to ground-based detectors like LIGO.","abstract":"A theoretical astrophysicist at West Virginia University will play a key role in the development of a first-of-its-kind planned space probe to detect and accurately measure gravitational waves — ripples in the fabric of space and time.\n\nSean McWilliams, associate professor of physics and astronomy in the WVU Eberly College of Arts and Sciences, was part of a team in 2015 that first detected those invisible ripples, which confirmed Albert Einstein’s general theory of relativity. Now, with $750,000 in support from NASA’s Established Program to Stimulate Competitive Research, McWilliams will lead efforts to develop models to help facilitate observations from the planned space probe.\n\nCalled the Laser Interferometer Space Antenna, or LISA, the probe will be the first dedicated space-based gravitational wave observatory that will measure binaries over a wide range of masses.\n\nGravitational waves, first predicted by Einstein in 1916, can be caused by cataclysmic events such as colliding black holes and neutron stars, massive stars exploding at the end of their lifetimes and even remnants of radiation created by the Big Bang.\n\nMcWilliams’s team will study the inspirals of stellar-mass binaries that will eventually merge as well as massive binaries at the centers of merging galaxies. LISA will further scientists’ perception of the universe and better equip them to study phenomena invisible in normal light.\n\n“LISA signals will be much louder relative to the detector noise than LIGO’s were, so the models have to be much more accurate to make sure the models don’t limit the science we can do,” said McWilliams, who also leads the WVU Center for Gravitational Waves and Cosmology. “This project will attempt to make the necessary dramatic improvements in modeling accuracy that will be required.”\n\nLIGO, which stands for Laser Interferometer Gravitational-Wave Observatory, is a large-scale observatory, based in Washington and Louisiana, designed to detect gravitational waves. It was used by the team that included McWilliams in the 2015 discovery.\n\n“For supermassive black-hole binaries, their spin and eccentricity distributions are sensitive to their environments just prior to entering the LISA band,” McWilliams said. “In addition, LISA can observe stellar-mass binaries earlier than ground-based detectors, and the measurement of their spins and eccentricities can provide insights into their formation and evolutionary history that cannot be obtained otherwise.”\n\nLISA is slated to launch in 2035.\n\nResearchers will also build upon a model developed by McWilliams called the “backward one-body method.” McWilliams calculated an exact mathematical formula for the signal produced by two merging black holes, making it easier for scientists to analyze gravitational waves.\n\nBefore the backward one-body method, researchers relied on a mathematical transformation to calculate the exact waveform from a black hole merger. That could become an arduous task, leading to multiple numerical simulations.\n\nMcWilliams used general relativity to calculate how a tiny test mass spirals into and perturbs the final black hole, allowing for more accurate reporting.\n\n“We will first improve the efficiency of the best models for inspirals that are currently available, and we will replace the merger signals with BOB (backward one-body),” McWilliams said. “From there, we will be able to rapidly assess new ideas for improving accuracy throughout the waveform. Ultimately, we plan to have a model that builds on all known physics throughout the signal and then add tunability to the model.”\n\nMcWilliams’ team includes Zach Etienne, adjunct associate professor.","project_type":"Subaward","lead":"Zachariah Etienne","affiliation":"COS Physics","partners":"National Aeronautic Space Ad.","funder":"West Virginia University","award_number":"80NSSC24M0106","date":"2024","status":"Active","subject":["gravitational waves","black hole binaries","waveform modeling","lisa","general relativity","inspirals","supermassive black holes"],"confidence":"Medium","source_url":"https://wvutoday.wvu.edu/stories/2024/06/04/wvu-astrophysicist-to-put-own-spin-on-first-of-its-kind-gravitational-wave-detector-with-nasa-support","funder_agency":"University partner","research_area":"Physics & astronomy"},{"objectid":"nih_wichman_center_modeling_complex","title":"Center for Modeling Complex Interactions","gist":"Integrates mathematical, computational, and machine learning models into interdisciplinary biomedical research to improve rigor and foster collaboration.","description":"The Center for Modeling Complex Interactions supports team-based, interdisciplinary biomedical research by integrating diverse modeling approaches, ranging from mathematical and computational methods to machine learning. This initiative improves rigor and reproducibility across all research stages while fostering a culture where modelers and empiricists collaborate to uncover connections between complex problems. Phase II expands this foundation by adding faculty, introducing new modeling initiatives in machine learning and geospatial analysis, and establishing a sustainable funding model under the Institute for Modeling Collaboration & Innovation.","abstract":"Biomedical problems are innately complex, and their solutions require input from many fields. Many centers\nfocus on a single disease or organ system. By contrast, the Center for Modeling Complex Interactions focuses\non an approach that can address many biomedical problems: team-based, interdisciplinary research centered\naround modeling. Our goal is to support and facilitate biomedical discovery by integrating modeling into\ninterdisciplinary research. Modeling improves research at all stages—hypothesis formulation, experimental\ndesign, analysis, and interpretation. It provides a unifying language by which exchange of ideas can highlight\ncommonalities and uncover unforeseen connections between problems. Formalization of ideas into this\nunifying language also improves rigor and reproducibility. We define modeling broadly to include everything\nfrom deterministic and stochastic mathematical approaches, to physical and computational models of three-\ndimensional objects, to agent-based and machine learning approaches where exact solutions are not possible.\nWe seek to support modelers by increasing their numbers, and by giving them opportunities to play on\ninterdisciplinary teams. We seek to support empiricists by giving them access to relevant modeling expertise,\nand by creating a community and a culture to facilitate interdisciplinary research. In Phase I, the Center for\nModeling Complex Interactions created the intellectual, cultural, and physical environment to promote team-\nbased, interdisciplinary research. In Phase II, we will build on that foundation by maintaining a strong\ninterdisciplinary culture to foster collaboration among people who might otherwise never connect, and by\nadding additional faculty to expand our modeling expertise. We have four Aims: 1) Support faculty to carry out\nmodel-based, interdisciplinary biomedical research and increase their competitiveness for external funding.\nResearch in the Center is carried out in the context of Working Groups—zero-barrier, interdisciplinary, goal-\nfocused teams that meet regularly to get work done. Supported research includes three Research Projects,\nPilot Projects, Modeling Access Grants, and ad hoc teams. Our comprehensive plan for proposal preparation\nimproves grantsmanship, and our staff assists with submission and grant management. 2) Increase University\nof Idaho’s faculty participation in biomedical research. We will add six new faculty as a commitment to this\nPhase II COBRE and attract broader participation from across the University. 3) Extend the reach of the\nModeling Core into new areas of modeling to capitalize on emerging opportunities. The Modeling Core\naccelerates interdisciplinary research by placing Core Fellows at the hub of the research community. We have\nadded new Core Initiatives in machine learning and geospatial modeling to stimulate research in these areas\nwith high potential for future growth. 4) Establish a path to long-term sustainability under the umbrella of the\nInstitute for Modeling Collaboration & Innovation. The major hurdle for sustainability is to maintain a robust\nModeling Core. We have developed a business plan that calls for us to diversify our funding sources to include\ninstitutional, state, and private support to supplement federal grants.","project_type":"Grant","lead":"Holly Wichman","affiliation":"RCI IMCI","funder":"National Institutes of Health","award_number":"P30GM159567","date":"2025","end_year":"2030","status":"Active","subject":["mathematical modeling","computational biology","machine learning","agent-based modeling","biomedical research","interdisciplinary research","stochastic modeling"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/10909059","project_url":"https://imci.uidaho.edu/","funder_agency":"National Institutes of Health","research_area":"Health & disease"},{"objectid":"usda_murdoch_characterizing_major_histocompati","title":"Characterizing the Major Histocompatibility Complexes of US Based Domestic Goats","gist":"Characterizing MHC genes and alleles in US domestic goat breeds to advance small ruminant vaccine development.","description":"This project characterizes the major histocompatibility complexes (MHCs) of alternate goat breeds within the United States to support vaccine development in small ruminant species. Researchers will collect blood samples from registered goats through a cooperator with producer connections, isolating peripheral mononuclear cells or shipping whole blood for analysis. The study employs long-read methodology to sequence genomic regions responsible for MHCs and converts RNA from isolated cells into cDNA to identify actively expressed MHC genes and alleles.","abstract":"Objective:\nCooperator is looking for research to promote vaccine development in small ruminant species.\n\nApproach:\nResearchers will characterize the major histocompatibility complexes (MHCs) of alternate goat breeds represented within the United States. A cooperator with goat producer connections will be established so that blood can be collected from registered goats. Sampled blood will either be shipped back as whole blood or have peripheral mononuclear cells (PMCs) isolated. Whole blood will undergo long-read methodology to sequence genomic regions responsible for MHCs. Ribonucleic acid (RNA) will be isolated and converted into cDNA from isolated PMCs to characterize which MHC genes/alleles are being actively expressed.","project_type":"Subaward","lead":"Brenda Murdoch","affiliation":"CALS Animal, Vet & Food Sciences","partners":"USDA-Animal and Plant Health Inspection Service","funder":"USDA Agricultural Research Service (USDA-ARS)","date":"2024","status":"Active","subject":["goat","major histocompatibility complex","genomics","vaccine development","small ruminants","gene expression","long-read sequencing"],"confidence":"Medium","source_url":"https://www.ars.usda.gov/research/project/?accnNo=444577","funder_agency":"USDA","research_area":"Genomics & molecular biology"},{"objectid":"nsf_tranmer_characterizing_physical_drivers","title":"Characterizing the physical drivers of vegetation-forced bar evolution in gravel-bed streams","gist":"Develops a mechanistic model for coarse-sediment mobility and gravel bar evolution in rivers based on vegetation density thresholds.","description":"This project investigates how riparian vegetation patches alter flow hydraulics and sediment transport in gravel-bed rivers, driving erosion and deposition that shape gravel bars. By combining fieldwork with large-scale flume experiments using vegetation simulants, the research develops a mechanistic driver for coarse-sediment mobility applicable to both vegetated and unvegetated channels. The study identifies vegetation density thresholds that initiate grain-size changes and bar evolution, aiming to produce predictive relations for equilibrium bar dimensions. These findings support water agencies in selecting planting densities for river restoration and assist flood managers in predicting bar dimensions to assess public safety risks.","abstract":"Riparian vegetation patches rapidly colonize exposed bars in gravel-bed rivers, impacting the nearby flow hydraulics and subsequent erosional-depositional processes during flood events. This vegetation-forced erosion and deposition on gravel bars is important as it alters the size and composition of the bed sediments that affects aquatic and riparian habitat quality, drives changes in subsurface hydraulics and associated water quality, as well as impacts flow conveyance and community flood risk. This project seeks to understand how the hydraulics and sediment transport capacity change through vegetation patches to explain the spatial patterns of observed bed sediments and resultant shape of gravel bars. The magnitude of changes is expected to depend on the vegetation density within a patch. Results can help guide water agencies in deciding what vegetation planting densities are necessary during river restoration activities to achieve the desired evolutionary outcomes. Additionally, results are expected to help flood managers predict gravel bar dimensions from existing vegetation densities and determine if vegetation thinning or removal is necessary for public safety.\n\nPredicting vegetated bar evolution is difficult because the local hydraulics and sediment mobility (initiation of sediment motion) are spatially variable through a vegetation patch. Currently, no single parameter is available to predict coarse-sediment mobility in both open and vegetated channels. Here, a combination of fieldwork and large-scale flume experiments with vegetation simulants will be used to develop a mechanistic driver of coarse-sediment mobility that is applicable in both vegetated and unvegetated conditions. In the planned experiments, vegetation density will be varied to identify a density threshold that initiates grain-size changes, spatial sorting, and bar evolution in gravel-bed rivers. Further, a predictive relation between vegetation density and equilibrium bar dimensions will be developed.\n\nThis project is jointly funded by Geomorphology and Land-use Dynamics (GLD) and by the Established Program to Stimulate Competitive Research (EPSCoR).\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Andrew Tranmer","affiliation":"COE Ctr for Ecohydraulics Research","funder":"National Science Foundation","award_number":"2245496","date":"2023","end_year":"2027","status":"Active","subject":["gravel-bed rivers","riparian vegetation","bar evolution","sediment transport","flow hydraulics","coarse sediment","flood risk"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2245496","funder_agency":"National Science Foundation","research_area":"Water resources"},{"objectid":"nih_stenkamp_regulatory_control_differential","title":"Cis-regulatory control of differential expression of tandemly replicated cone opsin genes","gist":"The Stenkamp Lab investigates vertebrate photoreceptor determination, regeneration, and evolution using zebrafish models and multi-institutional collaborations.","description":"Part of the Stenkamp Lab's research program, which uses zebrafish and other models to probe mechanisms regulating photoreceptor production, spatial patterns, and spectral sensitivities. The work encompasses transcriptomics, developmental signaling manipulation, retinal regeneration studies, vascular-neural interactions, and evolutionary adaptations in visually challenging environments. Collaborative efforts also include predicting cone visual pigment sensitivity and analyzing rod-mediated color vision in deep-sea fish.","project_type":"Grant","lead":"Deborah Stenkamp","affiliation":"COS INBRE","partners":"National Institutes of Health","funder":"IDeA Network of Biomedical Research Excellence","award_number":"R01EY012146","date":"2023","status":"Active","subject":["zebrafish","cone opsin","cis-regulatory elements","gene expression","retinal development","photoreceptors","tandem duplication"],"confidence":"Medium","source_url":"https://www.stenkamplab.net/research","project_url":"https://www.stenkamplab.net/research","funder_agency":"National Institutes of Health","research_area":"Genomics & molecular biology"},{"objectid":"nsf_mittelstaedt_above_below_quantifying","title":"Collaborative Research: As above so below: Quantifying the role of simultaneous LLSVPs and continents on Earth's cooling history using numerical simulations of mantle convection","gist":"Numerical simulations quantify how simultaneous continents and LLSVPs alter Earth's thermal history, mantle dynamics, and cooling rate.","description":"This project utilizes two-dimensional spherical numerical simulations to quantify how simultaneous surface continents and basal large low-shear-velocity provinces (LLSVPs) influence Earth's thermal evolution and internal mantle dynamics. By employing the ASPECT finite-element code on high-performance computing clusters, the research isolates fundamental processes governing these insulating bodies and examines their impacts through Earth's history. The work addresses critical gaps in understanding the planet's cooling rate, which drives essential processes such as plate tectonics and magnetic field generation. Additionally, the initiative expands Earth Science education through an interdisciplinary game development program and provides training for graduate students and a post-doctoral scholar at two rural, land-grant universities.","abstract":"Earth’s cooling rate affects many processes necessary for a dynamic, living world, from plate tectonics to the generation of the planet’s magnetic field. Deciphering the formation and evolution of such processes requires knowledge of the planet’s thermal history. Much of that history remains unconstrained in part because several controlling mechanisms have yet to be quantified. This project will address these gaps by studying the influence of Earth’s continents and continent-sized piles of anomalous material covering portions of the outer core on the Earth’s cooling history, plate tectonics, and magnetic field. In addition, the project will expand Earth Science education through an interdisciplinary game development program and train graduate students and a post-doctoral scholar at two rural, land-grant universities. \n\nThis project will systematically evaluate how simultaneous surface and basal insulating bodies in Earth’s mantle (continents and large low-shear-velocity provinces (LLSVPs)) jointly alter the thermal evolution and internal mantle dynamics of the Earth. Two-dimensional spherical numerical simulations will be used to quantify the impacts of simulated LLSVP and continental materials in models of increasing rheological, thermal, and temporal complexity. The simulations will address three research objectives: (1) isolate the fundamental processes governing interactions of surface (continent) and basal (LLSVP) insulators, (2) quantify the influence of complex rheology and internal heating on the basal and surface insulator convective system, and (3) examine impacts of time-evolving basal and surface insulators through Earth’s history. Numerical simulations of Earth’s mantle subject to surface (continent) and basal (LLSVP) insulators will be conducted using the highly parallel finite-element code ASPECT (Advanced Solver for Problems in Earth’s ConvecTion). Simulations will be solved in parallel across ~32-256 computational cores on University of Idaho’s Falcon supercomputer (>33k cores, 1.17 Petaflop) or Washington State University’s Kamiak high performance computer cluster.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Eric Mittelstaedt","affiliation":"COS Earth and Spatial Sciences","funder":"National Science Foundation","award_number":"2310324","date":"2023","end_year":"2027","status":"Active","subject":["mantle convection","large low-shear-velocity provinces","continental drift","thermal evolution","numerical simulation","plate tectonics","geodynamics"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2310324","project_url":"https://idahogeodynamics.weebly.com/research.html","funder_agency":"National Science Foundation","research_area":"Other"},{"objectid":"nsf_nuismer_immunological_signature_changing","title":"Collaborative Research: eMB: The immunological signature of a changing world: mathematical models to infer historical patterns of infectious disease","gist":"Develops multiscale models to infer historical spillover rates of Rift Valley fever virus from immunological signatures in host populations.","description":"This project develops new mathematical models and statistical methods to detect changes in the rate of infectious disease spillover from wildlife to humans by analyzing historical patterns imprinted on immune systems. The research addresses the challenge of distinguishing true shifts in spillover forces from background biological processes like age-specific infection and waning immunity using a general framework based on partial differential equations. The methodology will be rigorously tested with simulated data and applied to Rift Valley fever virus to determine if rising case counts in East Africa stem from epidemiological shifts or increased surveillance. Additionally, the work supports student training in advanced mathematical methods and facilitates an international workshop to introduce the resulting software.","abstract":"Spillover of infectious diseases from wildlife to humans and livestock is a pervasive risk to the health and welfare of human populations around the world. Effective management of this risk is facilitated by early detection of changes in the frequency of spillover events.  This research will develop new mathematical models and statistical methods that allow changes in the rate of spillover to be detected from the fossil record of past infection that remains imprinted on human and animal immune systems. The general methodology developed by this project will be rigorously tested using simulated data and applied to Rift Valley fever virus, a pathogen that poses a high risk of global expansion with potentially devastating consequences for human health and agriculture. Work on this project will train students in cutting edge mathematical and statistical methods and support an international workshop where software developed by the project will be introduced and instruction on its use provided.  \n \nPredicting how zoonotic infectious diseases change over time is a fundamentally important challenge with few general mathematical solutions. Central to addressing this problem is disentangling historical changes in the rate or “force” of spillover from background biological processes, such as age-specific infection and wanning immunity, which can cloak or mimic the signal of temporal change. Existing statistical methods to infer historical changes in the force of spillover for zoonotic pathogens rely on piecemeal solutions tailored to specific scenarios, ignore interacting background processes, use only single immunological markers, and have failed to rigorously evaluate parameter identifiability. To fill this gap, this project will develop a general mathematical framework describing the probability that an individual is in a specific multivariate immune state as a function of age and time using a coupled system of partial differential equations (PDEs). Approximate and numerical solutions to this system of PDEs will enable a Bayesian statistical framework for inferring recent historical changes in the force of spillover in the presence of alternative biological processes. Testing this statistical framework using extensive, biologically realistic simulated datasets will allow the identifiability of historical change in force of spillover to be evaluated. Application of this methodology to Rift Valley fever virus, a pathogen with significant pandemic potential, will determine whether increasing case counts in East Africa result from fundamental shifts in disease epidemiology or from increased disease surveillance.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Scott Nuismer","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2527135","date":"2025","end_year":"2028","status":"Active","subject":["zoonotic diseases","spillover","immunological signatures","rift valley fever","mathematical modeling","bayesian inference","east africa"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2527135","funder_agency":"National Science Foundation","research_area":"Health & disease"},{"objectid":"nsf_etienne_measuring_levitated_test","title":"Collaborative Research: Measuring G with a Levitated Test Mass","gist":"Measuring the Newtonian constant of gravitation using a levitated graphite mass in a gravito-magnetic trap to resolve measurement discrepancies.","description":"This project measures the Newtonian constant of gravitation, G, by levitating a graphite composite test mass in an ultra-high vacuum using a gravito-magnetic trap. By eliminating mechanical suspensions, the experiment minimizes systematic errors to achieve a precision of 10 parts per million and resolve existing discrepancies in G measurements. The resulting independent data and openly shared analysis tools support fundamental physics research while developing new instruments for measuring small forces and accelerations applicable to Earth studies and inertial navigation.","abstract":"Gravity was the first force mathematically described by scientists as an explanation of the motion of the moon, planets, and stars. Hundreds of years later, gravity is still considered to be the most poorly understood force. It cannot be consistently described across different theories in physics, and even its strength is poorly known. The Newtonian constant of gravitation, which quantifies the strength of gravity, is perhaps the most poorly measured fundamental property of the universe. This project seeks to greatly improve our knowledge of this constant with the most significant change in technique since the experiments of Henry Cavendish in 1798, who used a torsion balance for his measurements. The measurement funded by this award may be of value across many areas of physics and astronomy, and the new experimental tools being developed may lead to new instruments for measuring extremely small forces and accelerations for use in studying the Earth and for inertial navigation. In addition, the attention to detail required in these experiments makes them an exceptional training ground for tomorrow's STEM workers.\n\nThis project aims to resolve discrepancies in measurements of the Newtonian constant of gravitation, G, advancing our understanding of fundamental forces and potentially uncovering new physics. The approach is to levitate a graphite composite test mass in ultra-high vacuum. Changes in the oscillation frequency of the test mass, induced by carefully positioned field masses, are used to determine G. Eliminating mechanical suspensions minimizes systematic errors, while analysis of the trajectory enables precise modeling of higher-order oscillation modes in the test mass's motion. The goal is to provide an independent and transparent measurement of G with a precision of 10 parts per million, offering valuable insights into resolving discrepancies in existing measurements and paving the way for even more precise determinations. The experiment emphasizes simplicity in design and openness to encourage broader participation from the scientific community. All data and analysis tools will be made openly available to facilitate independent verification. By carefully addressing systematic uncertainties and sharing results transparently, this project aims to contribute constructively to the broader effort of refining the measurement of G, while demonstrating methods with applications in precision metrology and gravitational physics. The project's novel approach, utilizing magneto-gravitational trapping technology, represents a significant leap in precision measurement techniques, with implications for fields ranging from fundamental physics to precision sensing. Beyond improving the accuracy of G, this work could contribute to experiments exploring new interactions, such as potential couplings between dark matter and ordinary matter, as well as to precision accelerometry in space.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Zachariah Etienne","affiliation":"COS Physics","funder":"National Science Foundation","award_number":"2513014","date":"2025","end_year":"2028","status":"Active","subject":["gravitational constant","precision metrology","levitated test mass","fundamental physics","magneto-gravitational trapping","systematic errors","oscillation frequency"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2513014","funder_agency":"National Science Foundation","research_area":"Physics & astronomy"},{"objectid":"nsf_hohenlohe_orcc_integrating_evolutionary","title":"Collaborative Research: ORCC: Integrating evolutionary adaptive capacity and trophic dynamics to predict multi-species responses to climate change","gist":"Integrating genomics and modeling to predict climate vulnerability in Pacific Northwest cutthroat trout and tailed frog populations.","description":"This project investigates thermal vulnerabilities of cutthroat trout and tailed frog tadpoles in U.S. Pacific Northwest mountain streams by integrating genomics, physiology, and computer modeling. Researchers quantify thermal adaptation, adaptive capacity, and predator-prey interactions to predict how climate change affects these cold-water specialists. The study develops a web-based tool for natural resource agencies to assess environmental vulnerabilities and inform conservation decisions for stream biodiversity. Results address the complex interplay between evolutionary history, food web dynamics, and species sensitivity to environmental disruption.","abstract":"Changing climates are a major challenge for humans and nature. One of the most important scientific questions of the 21st century is \"What will determine the vulnerability of species and biological communities to environmental disruption?\" Addressing this question, however, is extremely challenging because changes in climate are complex, evolutionary history will determine species' sensitivity, and species' responses will be affected by the complex food webs of which they are a part. For example, even if a predator species is relatively insensitive to warming temperatures, it may still be vulnerable if the prey species it feeds on are sensitive and disappear. The research team will investigate thermal vulnerabilities of cutthroat trout predators and tailed frog tadpole prey in mountain streams of the U.S. Pacific Northwest using a multidisciplinary approach that combines cutting-edge DNA sequencing technology, physiology experiments, and high-performance computer modeling. This is an excellent predator-prey case study to investigate this question, as cutthroat trout are important predators of tailed frog tadpoles, both species are cold-water specialists that are sensitive to warming, and both species are of conservation concern. Thus, results of this study will be important for informing their conservation and management. The research team will work closely with federal and state natural resource agencies to make sure that results are useful for informing decisions about the conservation and management of stream biodiversity. The team will develop a web-based tool to help managers assess environmental vulnerabilities. The project will also provide training for four early career researchers. \n\n\nIt is essential to integrate organismal, ecological, and evolutionary perspectives to predict the vulnerability of species and biological communities to global change. The proposed research will use a highly interdisciplinary approach to test several novel hypotheses about the mechanisms underlying environmental vulnerability in a predator (cutthroat trout) - prey (tailed frog) system in streams of the U.S. Pacific Northwest. In Aim 1, the research team will test whether predators (cutthroat trout) are more sensitive to increasing temperatures than their prey (tailed frogs) using a combination of environmental characterization, genomics, and physiology to quantify thermal adaptation. In Aim 2, they will test whether different dimensions of adaptive capacity (dispersal, evolutionary potential, and acclimation ability) differ between predators and prey by using genomics to characterize patterns and rates of connectivity across the landscape and evolutionary potential, and physiology to quantify acclimation. In Aim 3, the team will determine how predator-prey interactions respond to temperature and flow by quantifying the diet of cutthroat trout and energy content of tailed frogs, and by using a mechanistic food web model to predict how climate change-driven changes in energy flow and food web dynamics will affect cutthroat trout-tailed frog interactions. In Aim 4, they will integrate the results from Aims 1-3 using an individual-based, eco-evolutionary model to predict how species interactions, intraspecific variation in sensitivity, and adaptive capacity act synergistically to determine spatial patterns of thermal vulnerability in cutthroat trout and tailed frogs.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Paul Hohenlohe","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2413361","date":"2024","end_year":"2027","status":"Active","subject":["climate change","cutthroat trout","tailed frog","predator-prey interactions","thermal vulnerability","population genomics","food web dynamics"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2413361","project_url":"https://hohenlohelab.github.io/research.html","funder_agency":"National Science Foundation","research_area":"Ecology & wildlife"},{"objectid":"nsf_alessa_track_where_live","title":"Collaborative Research: RII Track-2 FEC: Where We Live: Local and Place Based Adaptation to Climate Change in Underserved Rural Communities","gist":"Quantifying perception gaps to improve drought, heat, and wildfire adaptation in rural Idaho, Nevada, and South Carolina communities.","description":"This project investigates the gap between perceived and actual climate risks in rural communities across Idaho, Nevada, and South Carolina to improve adaptation to drought, heat, and wildfire. By combining participatory socio-environmental mapping with advanced computational modeling, the research quantifies how cognitive differences influence adaptive behaviors and community resilience. The initiative engages local residents in co-developing knowledge and scenarios, aiming to replace ineffective hazard mapping with strategies that align perception with biophysical reality. These efforts support national sustainability and security by fostering successful adaptation in regions that provide critical food, water, and energy resources.","abstract":"Nontechnical Description\n\nAdaptation consists of a set of behaviors and activities that occur from individual to institutional scales which result in the ability to remain healthy, effective and prosperous despite changes that occur in the biophysical environment and is predicated on accurate perception of change, a set of abilities embedded in human cognition. Perception has been extensively studied in the context of risk and acute hazards such as flooding and wildfire, but data show that perceiving risk does not lead to successful adaptation which is critical for everything from human health to national security. Our current approaches of hazard, vulnerability and risk mapping are ineffective; they do not accelerate adaptation and data show that they may even drive maladaptive behaviors. Rural communities constitute nearly 84% of the United States (US) land area and are home to only 14% of the population. These areas serve as critical sources of food, freshwater, habitat, and energy as well as supporting carbon sequestration, education, recreation, and tourism but have been effectively left out of adaptation dialogues. Moreover, they are models for settlements in other parts of the world and despite the rapid progress of technologies that can facilitate adaptation to drought, heat, and wildfire, widespread actions remain elusive. The need to understand the gap between knowing and experiencing the effects of a rapidly changing earth system and the behaviors that successfully respond to them has never been greater. When perception varies significantly from real world dynamics we refer to a large gap (or difference) which may be associated with maladaptive behavior. We hypothesize that the size of this gap is a key measure that determines both adaptive capacity, i.e., the potential to take actions that minimize the negative effects of climate change and adaptation, i.e., actually taking the actions. To answer this question we will use participatory socio-environmental systems mapping, engaging the residents of rural communities as well as advanced computational modeling to project futures under different scenarios of change and responses to it.  This project will lead to precise understanding of the mechanisms between perceptions, cultures and adaptation which will enable both better planning by increasing the diversity of knowledge as well as lead to more successful implementation in areas and regions that are central to our Nation’s sustainability, security and thrivability. \n\nTechnical Description\n\nThe RII Track-2:  Where We Live (W2L) Local and Place Based Adaptation to Drought, Heta, and Wildfire in Rural Communities project builds national research competitiveness and capacity to addressing the critical national need of proactively addressing hazards in rural communities. The W2L project advances research, education, workforce development, and partnerships among the Idaho, Nevada, and South Carolina EPSCoR jurisdictions. W2L leverages and enhances linkages in community engagement, computational modeling, engineering,  physical sciences, and social sciences. The goal of W2L is to build the needed capacity to achieve adaptation mapping—the ability to leverage agent-based models to determine how small adaptation actions produce community-scale resilience, a novel contribution to tackling the drought, heat, and wildfire. The scope of the project involves communities and landscapes experiencing drought, heat, and wildfires in Idaho, Nevada, and South Carolina, areas of growing local and national concern. The project advances novel science and training by working collaboratively with rural communities to advance understanding of how perceptions, values, and knowledge promote or impede adaptation to chronic (slow) and acute (fast) hazards. The project uses integrative approaches that bring together climate science, social science, computational modeling, and stakeholder engagement. Methods include development of community data oversight groups in each jurisdiction; and use of a structured workshop called the quadrant-enabled Delphi method to support co-development of knowledge by community members and researchers. Quantification of the delta between perceptions of variability and instrumented measures of drought, heat, and wildfire will use data mining of historical climate data and categorical data analysis from the structured workshops. The identification of adaptation pathways with communities will involve a set of iteratively developed scenarios for each type of hazard supported by projections that are looked at by communities though a dialogues of change activity. Dialogues of change are used to support adaptation mapping for drought, heat, and wildfire. The W2L project emphasizes community engagement and the co-production of knowledge and implements multiple initiatives to increase the participation of members of rural communities in research and in STEM. W2L will support workforce development, early-career advancement, and student training through high-context, community-engaged interdisciplinary science, co-created with community members. The potential contributions of W2L are to build convergence-science through collaborative approaches with community groups; to quantify and analyze the convergence and/or divergence between perceptions of drought, heat, and wildfire and instrument measured records in those impacts; and to build pathways for adaptive capacity and adaptation options in rural communities.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Lilian Alessa","affiliation":"CAA Center of Resilient Communities","funder":"National Science Foundation","award_number":"2316126","date":"2023","end_year":"2027","status":"Active","subject":["climate change adaptation","rural communities","drought","wildfire","heat stress","risk perception","agent-based modeling"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2316126","project_url":"https://sc.edu/study/colleges_schools/artsandsciences/centers_and_institutes/hvri/research/where_we_live/","funder_agency":"National Science Foundation","research_area":"Climate"},{"objectid":"nsf_ma_sustained_resources_onemineralogy","title":"Collaborative Research: Sustained Resources: OneMineralogy - A FAIR and friendly mineralogy data ecosystem to boost data-intensive geoscience research and education","gist":"OneMineralogy expands the Mindat.org database into a FAIR ecosystem with new tools and curation strategies for geoscience research and education.","description":"OneMineralogy expands the Mindat.org database into a FAIR and open science ecosystem to support data-intensive geoscience research and education. The project develops new data curation strategies, computational tools, and community engagement programs to analyze mineralogical systems across deep time and planetary missions. By integrating resources related to paleoenvironments, geomicrobiology, and tectonics, it enables the investigation of Earth's dynamic history and the interpretation of data from the Moon and Mars. This initiative strengthens science education, promotes open data sharing, and supports mineral exploration while empowering the next generation of scientists.","abstract":"Minerals are essential to understanding our planet's past and guiding its sustainable future. This project builds on Mindat.org, the world's largest public database of minerals and their global distributions, which receives nearly 10 million visitors per year. With previous support from the National Science Foundation, the OpenMindat project has made mineral data more accurate and accessible for scientists and the public alike. This new phase of work, called OneMineralogy, will expand these efforts into a broader open science ecosystem. OneMineralogy aims to make mineral data and tools available to a wider range of users, including students, educators, researchers, and decision-makers. Its data, tools, and services will help them ask and answer big questions about how Earth's systems have evolved over time. The activities of OneMineralogy will strengthen science education, promote open data sharing, support mineral exploration (including critical minerals), and accelerate discoveries related to planetary science, Earth-life co-evolution, and environmental change. By fostering new partnerships and offering training opportunities, OneMineralogy will empower the next generation of scientists and ensure that mineralogical data benefit society as a whole.\n\nScientifically, OneMineralogy will advance the frontier of data-driven geoscience by developing new data curation strategies, computational tools, and community engagement programs. It builds on the success of the NSF-funded OpenMindat project, which has already improved the quality and accessibility of over 6,000 mineral species records and data from more than 400,000 global localities. OneMineralogy will consist of three major activity clusters: (1) extending and curating data to support a wider range of geoscientific research, (2) building a data science toolbox to enable large-scale analysis of mineralogical systems, and (3) conducting workshops and outreach programs to grow the user community and build capacity. The project will integrate Mindat with other open cyberinfrastructure resources related to paleoenvironments, geomicrobiology, tectonics, and biosignatures. The enriched data and tools will provide strong support to the investigation of Earth's dynamic history through deep time. It will also provide a foundation for interpreting the growing body of mineralogical data from planetary missions to the Moon and Mars. Through these activities, OneMineralogy will create a sustained, open, and collaborative ecosystem to support transdisciplinary research and education in the Earth and planetary sciences.\n\nThis award by the Geoinformatics program is co-funded by the Innovative Technology Experiences for Students and Teachers (ITEST) program, which supports projects that build understandings of practices, program elements, contexts and processes contributing to increasing students' knowledge and interest in science, technology, engineering, and mathematics (STEM) and information and communication technology (ICT) careers.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Xiaogang Ma","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2514552","date":"2025","end_year":"2028","status":"Active","subject":["mineralogy","geoinformatics","open data","earth science","planetary science","data curation","critical minerals"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2514552","project_url":"https://github.com/ChuBL/OpenMindat","funder_agency":"National Science Foundation","research_area":"Data science & computing"},{"objectid":"nsf_martonick_crossing_innovation_valley","title":"Crossing the Innovation Valley of Death: Democratizing Data and Artificial Intelligence for Research Administration","gist":"Developing open-source AI tools to automate research administration and support minority-serving institutions.","description":"This project develops open-source artificial intelligence and data science tools to enhance post-award research administration by automating manual processes and reducing errors. It focuses on creating trustworthy models for data extraction and compliance verification while adhering to FAIR data principles to improve interoperability. By deploying these tools at partner institutions like the University of Idaho and Southern Utah University, the initiative levels the playing field for emerging and minority-serving institutions. The effort also includes workforce development to train administrators in AI skills and utilizes an independent external evaluator to assess impact and ensure the framework supports efficient, data-driven research management.","abstract":"This project aims to significantly enhance post-award research administration by developing open-source tools that integrate artificial intelligence (AI) and data science. Research administration is crucial for supporting scientific progress, but many institutions face challenges with inefficient processes that hinder their ability to effectively manage grants and contracts. Recent advances in generative AI provide a unique opportunity to augment research administrators' capabilities. By creating accessible, innovative tools, this project will help level the playing field for emerging research institutions, minority-serving institutions, and primarily undergraduate institutions. Improved research administration will accelerate scientific discovery across disciplines by reducing the administrative burden on researchers, allowing them to focus more on their work. The project will also contribute to workforce development by training research administrators in data science and AI skills, preparing them for the increasingly technological future of the field. By making these tools open source, the project promotes collaboration and innovation in the broader research management ecosystem. \n\nThe project has three main objectives: 1) Develop open-source data models and workflows that adhere to FAIR (Findable, Accessible, Interoperable, and Reusable) data principles to improve data accessibility and interoperability in research administration. 2) Create trustworthy AI-powered tools to automate manual processes, reduce errors, and augment the capabilities of research administrators. These will include natural language processing and machine learning models for tasks like data extraction, compliance verification, and decision support. All tools will undergo rigorous testing for accuracy, reliability, and reproducibility. 3) Implement and assess the impact of these tools at partner institutions, starting with the University of Idaho and Southern Utah University, then expanding to additional collaborators. The project will use an iterative, user-centered development approach, incorporating feedback from partners to ensure the tools meet real-world needs. Importantly, the project features an independent external evaluator to ensure the research administration community can learn from both successes and challenges, a critical approach given the rapid advancements in AI capabilities. By integrating data science and AI in a thoughtful, tested manner, this project aims to create a transformative framework for efficient, data-driven research administration that can be adopted widely across diverse institutions.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Sarah Martonick","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2427549","date":"2024","end_year":"2029","status":"Active","subject":["research administration","artificial intelligence","data science","generative ai","natural language processing","machine learning","open source software"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2427549","project_url":"https://ui-insight.github.io/ai4ra-site/","funder_agency":"National Science Foundation","research_area":"Data science & computing"},{"objectid":"ai4ui_data-infrastructure-pilot","title":"Data Infrastructure Pilot","description":"Pilot connecting structured and unstructured data sources to a shared data lakehouse serving the AI4RA partnership, starting with Banner plus at least one other system — fully documented with a data dictionary. The longer vision expands the lake to include ArchAI contract data, targeted core documents from proposals, and other sources the AI4UI application family draws on. Distinct from OIT's Databricks platform deployment, whose workspace OIT controls in its entirety (clarified 2026-08-05, superseding the July reading that the two were one effort).","significance":"Aligns the data used and created by AI4UI applications on one governed foundation instead of per-project extracts — the E.1 data-warehouse priority made concrete.","status":"Exploring","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nsf_etienne_democratizing_numerical_relativity","title":"Democratizing Numerical Relativity: Advancing Binary Black Hole Simulations on Consumer-Grade Hardware","gist":"BlackHoles@Home enables high-fidelity binary black hole simulations on consumer hardware using dynamic multi-patch grids to democratize gravitational wave research.","description":"The BlackHoles@Home project utilizes innovative computational techniques to reduce memory and processing requirements for binary black hole simulations by 40 to 100 times, enabling high-fidelity modeling on consumer-grade hardware. By implementing a dynamic multi-patch numerical grid and advanced solvers for extreme binary black hole initial data, the initiative democratizes access to gravitational wave source modeling for students, educators, and researchers regardless of their resources. This approach serves as a cost-effective supplement to supercomputing facilities while engaging the public in scientific discovery and deepening the understanding of the most frequently observed gravitational wave sources.","abstract":"This project is jointly funded by the Division of Physics Gravitational Physics program and the Established Program to Stimulate Competitive Research (EPSCoR). This award brings high-fidelity binary black hole (BBH) simulations, traditionally the domain of supercomputing, into the realm of consumer-grade hardware, greatly broadening participation in this scientific research. BlackHoles@Home (BH@H) implements innovative computational techniques to reduce memory and computational demands by 40 to 100 times, making it possible to perform these simulations on everyday computers. As a result, this project deepens our understanding of BBH mergers, the most frequently observed sources of gravitational waves. By democratizing access to this technology, BH@H promotes the progress of science, enabling a diverse group of students, educators, and researchers to engage in gravitational wave source modeling irrespective of their resources. Additionally, its integration into a public volunteer computing effort supports the national interest by engaging the public in scientific discovery and providing educational tools that demystify complex astrophysical phenomena, thereby serving as a cost-effective supplement to existing supercomputing facilities.\n\nBuilding on the new BlackHoles@Home (BH@H) numerical relativity (NR) code, this award advances the accessibility and utility of NR simulations on consumer-grade hardware. By implementing a highly efficient, dynamic multi-patch numerical grid, the project significantly reduces the memory and computational demands traditionally associated with binary black hole (BBH) simulations. This enables the execution of high-fidelity simulations within the resource constraints of consumer-grade computing hardware, opening up opportunities for widespread participation in this exciting gravitational wave science. The award also supports the development of enhanced NR tools and techniques, including a solver capable of generating extreme-BBH and beyond-general relativity initial data. Through these advances, the project promises to significantly expand the accessibility of NR, providing valuable resources to the scientific community and enhancing the capacity for groundbreaking gravitational wave research.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Zachariah Etienne","affiliation":"COS Physics","funder":"National Science Foundation","award_number":"2409654","date":"2024","end_year":"2027","status":"Active","subject":["binary black holes","numerical relativity","gravitational waves","black hole mergers","computational astrophysics","volunteer computing","general relativity"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2409654","project_url":"https://blackholesathome.net/","funder_agency":"National Science Foundation","research_area":"Physics & astronomy"},{"objectid":"usda_cumagun_database_seed_testing","title":"Developing a database of seed testing services to facilitate export of Idaho seed","gist":"A database of Idaho and US public seed health testing services to support Idaho seed exports.","description":"The Idaho-Eastern Oregon Seed Association, in partnership with the University of Idaho, is developing a comprehensive database of seed health testing services. This resource aggregates information on diagnostic laboratories located within Idaho as well as public laboratories across the entire United States. The database is designed to facilitate the export of Idaho seed by providing the local seed industry with accessible data on available testing options.","abstract":"The Idaho-Eastern Oregon Seed Association through the University of Idaho will develop a comprehensive database of seed health testing services which shall be made available to the Idaho Seed Industry. This will include testing services available from diagnostic laboratories based in Idaho as well as public labs across the whole US.","project_type":"Subaward","lead":"Christian Cumagun","affiliation":"CALS Entomology,Plt Pathology,Nemat","partners":"USDA Agricultural Marketing Service","funder":"Idaho Eastern Oregon Seed Association","date":"2023","status":"Completed","subject":["seed health","seed testing","plant pathology","seed export","diagnostic laboratories","agricultural trade","idaho"],"confidence":"High","source_url":"https://www.ams.usda.gov/sites/default/files/media/SCBGPDescriptionofFunds2023.pdf","funder_agency":"USDA","research_area":"Agriculture"},{"objectid":"isbe_ytreberg_novel_fungicides_sustainable","title":"Developing Novel Fungicides for Sustainable Potato Production","gist":"Developing novel fungicide compounds with new modes of action to combat resistant fungal pathogens threatening Idaho potato production.","description":"This project addresses the threat of fungal pathogens to Idaho potato production by developing novel fungicides with new modes of action to counter resistant strains. The research utilizes a unique pipeline involving bioinformatics to identify protein targets, molecular modeling to find inhibitors, and laboratory synthesis for experimental validation. The work aims to produce a range of promising compounds ready for field testing to combat critical fungal pathogens affecting agriculture in the region.","abstract":"Potatoes are a staple crop in Idaho, and worldwide, yet they are constantly threatened by fungal pathogens that can lead to enormous yield losses. While fungicides have been developed to combat these pathogens, widespread use has led to the emergence of resistant fungal strains. Treatment options are further limited by the lack of diversity in modes of action with existing fungicides. We seek to revolutionize fungicide development via our unique pipeline that has the potential to lead to the development of novel fungicides with new modes of action. For the proposed Proof of Concept project, we will continue our bioinformatics study to identify potential (novel) protein fungicide targets for the most critical potato fungal pathogens that threaten agriculture in Idaho. We will complete molecular modeling to identify possible inhibitors for these target proteins. Finally, we will synthesize and experimentally validate these inhibitors in laboratory and greenhouse studies. By the end of the funding period, we will have developed a range of promising compounds against multiple protein targets that are ready to be field tested and eventually used to develop commercially available products to combat the most important fungal pathogens of potatoes.","project_type":"Grant","lead":"Marty Ytreberg","affiliation":"RCI IMCI","funder":"Idaho State Board of Education","date":"2024","status":"Completed","subject":["potato","fungicides","fungal pathogens","protein targets","molecular modeling","drug discovery","idaho"],"confidence":"High","source_url":"https://web.archive.org/web/20240923161758/https://boardofed.idaho.gov/wp-content/uploads/2024/05/UI-8-Combined-Full-Proposal-and-Budget.pdf","project_url":"https://www.uidaho.edu/newsroom/new-fungicide","funder_agency":"State of Idaho","research_area":"Agriculture"},{"objectid":"ifg_kimsey_scaled_remotely_sensed","title":"Developing scaled remotely sensed digital forest inventories for Inland Northwest Forests","gist":"Developing scaled remotely sensed digital forest inventories for Inland Northwest forests using lidar and photogrammetric 3D point clouds.","description":"This project develops scaled remotely sensed digital forest inventories for Inland Northwest forests by leveraging the University of Idaho's digital forestry program and its Experimental Forest. The work centers on constructing single-tree digital forest twins using lidar, photogrammetric 3D point clouds, and sensor data to advance AI-driven forest operations. Building on the completion of the first operational single-tree inventory in 2019, the initiative integrates research from the Idaho Digital Forestry Lab and the Intermountain Forestry Cooperative to refine large-scale forest monitoring capabilities.","project_type":"Contract","lead":"Mark Kimsey","affiliation":"CNR Intermountain Forestry Coop-633 (IFTNC)","funder":"Idaho Forest Group","date":"2023","status":"Active","subject":["forest inventory","lidar","photogrammetry","digital twins","remote sensing","single-tree detection","inland northwest"],"confidence":"Low","evidence_note":"Internal source: the University of Idaho sponsored-projects record. The award is confirmed there; this sponsor publishes no project description. A request for one is outstanding.","research_area":"Forestry"},{"objectid":"ai4ui_dgx-stack","title":"DGX Stack","description":"Two-container stack for NVIDIA DGX Spark that serves a multimodal LLM via vLLM alongside a document-OCR container. Supports Gemma 4 26B and Qwen 3.5 35B FP8. Deployed at UI as a MindRouter backend; also deployed at Southern Utah University (AI4RA partner) for Vandalizer.","significance":"On-prem AI compute without cloud recurring costs. Supports compliance-sensitive and air-gapped workloads. Backbone for institutional OCR and LLM serving.","status":"Live","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nsf_sheneman_cumulative_ecological_social","title":"DISES: Cumulative effects of ecological and social stressors on the dynamics of integrated ranching-wildlife systems: drought, wolves, and human decision-makers","gist":"Analyzing how drought and wolf recolonization interact to alter rangeland food webs and human decision-making in Oregon and Idaho.","description":"This research investigates how the combined stressors of increasing drought and recolonizing gray wolves impact the distribution of wild herbivores and free-ranging cattle in shared rangelands across Oregon and Idaho. By integrating social surveys, camera-trap data, and remote sensing, the project analyzes how these environmental changes alter food web dynamics and influence decision-making for ranchers and wildlife managers. The work aims to identify system tipping points and develop forecasting tools to support coexistence strategies in western US ecosystems facing intensifying climate and predation risks.","abstract":"As environmental changes intensify around the world, both humans and wildlife face greater uncertainty and risk, threatening both human livelihoods and wildlife biodiversity. This research seeks to understand how multiple sources of stress impact humans, free-ranging livestock, and wildlife in shared rangelands in the western US. Increasingly frequent and more severe droughts make plant forage for wild herbivores and cattle less predictable and abundant, even as the return of gray wolves to parts of the landscape increases predation risk. As a result, wildlife such as deer and elk, as well as free-ranging livestock, may be forced to trade off food and security, and ranchers grazing their cattle on public land may face more uncertainty. This research will assess (1) how drought and wolves interact to affect wild herbivores and free-ranging cattle distributions across the landscape, (2) how decision-makers respond to these two sources of stress, and (3) how information, provided via a new wildlife and plant forecasting application, is received and used by both ranchers and wildlife managers. The project will also increase public awareness of human and wildlife connections and interactions in rangeland ecosystems via a documentary film, as well as by training citizen scientists to classify camera-trapped images of rangeland wildlife. A diverse group of undergraduate and graduate students as well as a post-doctoral researcher will be trained over the course of this project. Outcomes of this project include a better understanding of how climate and carnivore risks affect human decision-making, as well as how humans impact rangeland food webs via cattle stocking and wildlife removal, potentially leading to increased opportunities for coexistence between humans and wildlife in changing environments.\n\nEcological shifts brought about by climatic change can strongly interact with other sources of change, such as recolonizing large carnivores, to alter food web dynamics and potentially reduce ecosystem provisioning for humans. The uncertainty created by such interactions also challenges human decision-making. A critical gap exists in our knowledge of how climate change affects human-wildlife systems via wild food webs, and how natural resource decision-makers respond to such stress. We hypothesize that multiple environmental stressors (e.g., climate change and novel predators) will have complex and interactive effects on human-wildlife systems. Effects will likely occur via trophic interactions among predators, prey, domestic animals, and plants within shared food webs, potentially reducing the provisioning of humans from the shared ecosystem and human tolerance for predatory and competitive wildlife, and increasing uncertainty for natural resource decision-makers. There is a pressing need to advance models, tools and theory to (A) understand how multiple stressors interactively affect food webs in which humans and domestic animals are embedded, and (B) identify and quantify feedbacks among natural resource decision-makers and human-wildlife systems in response to multiple environmental stressors. Such information would assist in identifying potential “tipping points” in system resiliency and allow for better management of interacting wildland and agricultural systems. Using a factorial design of study sites across combinations of wolf presence and drought in Oregon and Idaho, we will study rancher-wildlife-plant dynamics. Data will stem from rancher surveys, wildlife camera grids, and ground-surveyed and remotely-sensed plant data. We will integrate social and ecological data into a structural equation modeling framework, which will drive ecological forecasts of predation and competition risk to livestock for ranchers and managers to use in future decision making. To understand natural resource manager decisions, which occur at larger spatial scales than rancher decisions, we will conduct a broad-scale analysis of the rangeland SES across the Western US using publicly-available wildlife and social data and remotely-sensed environmental characteristics. By analyzing decision-making across these spatial scales, we anticipate being able to identify key feedbacks, emergent phenomena, and potential tipping points in resilience for the human and wildlife components of the rangeland SES.\n\nThis project is jointly funded by the Dynamics of Integrated Socio-Environmental Systems (DISES) and the Established Program to Stimulate Competitive Research (EPSCoR).\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Subaward","lead":"Luke Sheneman","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","partners":"National Science Foundation","funder":"University of Illinois at Urbana–Champaign","award_number":"2317537","date":"2023","end_year":"2026","status":"Active","subject":["rangeland ecology","gray wolves","drought","human-wildlife conflict","livestock","trophic interactions","natural resource management"],"confidence":"Medium","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2317537","project_url":"https://whisl.org/","funder_agency":"University partner","research_area":"Ecology & wildlife"},{"objectid":"wssa_prather_plant_soil_microbe","title":"Do Plant-Soil Microbe Interactions Explain Ventenata dubia’s Competitive Advantage?","gist":"Testing whether soil-microbe feedbacks drive Ventenata dubia invasion.","description":"A University of Idaho study led by Timothy Prather testing whether soil-microbe feedbacks help explain the spread of the invasive annual grass Ventenata dubia across Western grasslands and dry forests. It compares how native and invaded soils affect plant growth to see whether Ventenata reshapes the soil community to favor its own establishment over native and seeded perennial grasses.","project_type":"Grant","lead":"Timothy Prather","affiliation":"CALS Plant Science","funder":"Weed Science Society of America","date":"2023","status":"Active","subject":["ventenata dubia","plant-soil feedback","invasive species","soil microbiome","plant competition","grassland ecology","microbial interactions"],"confidence":"Medium","research_area":"Ecology & wildlife"},{"objectid":"doe_marx_epscor_revealing_causes","title":"DOE EPSCOR: Revealing the Causes and Consequences of Microbial Non-genetic Variability in Energy-relevant Processes","gist":"How microbial non-genetic variability drives energy-relevant processes.","description":"A DOE EPSCoR project led by University of Idaho biologist Christopher Marx, studying how non-genetic variability among genetically identical microbial cells shapes energy-relevant processes such as bioconversion of aromatics, soil-carbon sequestration, and bioenergy-crop productivity. Across two model bacteria the team combines high-throughput experiments, transcriptomics, biofilm imaging, microfluidics, and mathematical modeling, spanning partners in Idaho and New Hampshire.","project_type":"Grant","lead":"Christopher Marx","affiliation":"RCI IMCI","funder":"U.S. Department of Energy","award_number":"DE-SC0022318","date":"2025","status":"Active","subject":["microbial variability","non-genetic inheritance","phenotypic heterogeneity","energy metabolism","microbial genomics","gene expression","bacterial physiology"],"confidence":"Medium","funder_agency":"Department of Energy","research_area":"Genomics & molecular biology"},{"objectid":"nsf_ma_earthcube_capabilities_openmindat","title":"EarthCube Capabilities: OpenMindat - Open Access and Interoperable Mineralogy Data to Broaden Community Access and Advance Geoscience Research","gist":"OpenMindat creates automated data access tools and open licenses for the Mindat mineral database to enable machine-driven geoscience research.","description":"The OpenMindat project establishes automated querying and bulk download capabilities for the Mindat mineral database, transitioning its data to an open science compatible license. By building a web-based platform and developer tools in Python and R, the initiative enables machine interface access for academic research and education. This effort democratizes the use of large mineralogy datasets, facilitating new studies in mineral evolution and ecology while supporting data-driven geoscience discovery through advanced analytical techniques.","abstract":"Mindat is a community-driven, free-access, online database that records information about all known mineral species and their worldwide distribution. Although all the data on the Mindat website are free for users to browse, the machine interface for data access and download has never been fully established. The OpenMindat project will, for the first time, allow automated querying and downloads from this data resource for academic research. This effort includes technical developments to establish open data access, research and training activities to advance data curation and data-driven geoscience discovery, and outreach activities to EarthCube and the broad geoscience communities. Opening the Mindat data for free academic use will encourage a new generation of research in geosciences as well as other disciplines. Mindat is already an important resource for geoscience education. Currently, it receives more than 3.5 million page views every month. These new data access tools in OpenMindat will make it easier for educational access to mineralogical data in the classroom, the laboratory, and even from home, allowing students greater opportunities to experiment with mineralogical data science. \n\nThe OpenMindat project will involve moving all appropriate Mindat data into an open science compatible license, building and operating a web-based platform for both automated queries and bulk data downloads, preparing all documentation on the use of this data, and building a suite of developer tools including packages in Python and R for direct data access from workflow platforms. OpenMindat will also deploy metadata standards to establish connections to EarthCube GeoCODES. The project will create several training positions and organize a list of engagement and outreach activities, with priorities given to underrepresented groups. Computational and statistical work on large mineralogy datasets has driven the recent studies in Mineral Evolution and Mineral Ecology of which the Mindat data was a critical component. OpenMindat will democratize this research allowing anyone wishing to utilize the Mindat data for research to do so immediately. Using machine learning techniques in combination with the OpenMindat dataset raises the possibility of finding previously unseen patterns in the mineralogical diversity on the Earth and beyond, such as, comparing the mineral assemblages and localities on Earth with other planets. This project will illustrate the importance of collecting and providing certain information when analyzing mineral samples and thus cause a cultural shift in mineralogical data collection and sharing. Likewise, the studies in this project will be an example for how rapidly scientific discovery can move forward when the data are in place and coupled with advanced analytical techniques and data science expertise. The service and tools that will be developed as part of OpenMindat will themselves be open-sourced and potentially of benefit to other projects wishing to provide access to their data.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Xiaogang Ma","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2126315","date":"2025","end_year":"2026","status":"Active","subject":["mineralogy","mineral data","data interoperability","machine learning","mineral evolution","geoscience","open data"],"confidence":"Medium","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2126315","project_url":"https://github.com/ChuBL/OpenMindat_AI","funder_agency":"National Science Foundation","research_area":"Data science & computing"},{"objectid":"nasa_etienne_electromagnetic_signals_merging","title":"Electromagnetic Signals from Merging Supermassive Black Holes","gist":"Simulating gas accretion and photon emission to predict electromagnetic signatures of merging supermassive black hole binaries.","description":"This project combines astrophysical knowledge with detailed physical simulations to predict electromagnetic signals from merging supermassive binary black holes. By modeling gas flows and time-dependent spacetime from large orbital separations through post-merger, the network generates realistic predictions of photon radiation, spectra, and light curves. These efforts are critical for linking upcoming observational data from missions like LISA and Pulsar Timing arrays with theoretical models, enabling the identification of distinct spectral signatures against galactic backgrounds.","abstract":"Accreting supermassive binary black holes are promising multimessenger sources because they strongly emit both gravitational wave (GW) and electromagnetic (EM) radiation. It is the goal of this project to combine astrophysical knowledge about the environments of these sources with detailed physical simulations of gas flows in the immediate neighborhoods of these binaries, and explicit computation of the time-dependent spacetime in which the gas is placed, in order to predict the signals observers would see to identify them.\n\nOur proposed network, comprising experts in the fields of theoretical and computational astrophysics, will provide observable predictions of supermassive black hole binaries with the most thorough and complete effort in the field to simulate the accretion dynamics into binary supermassive black holes from large orbital separations through postmerger. Bringing together more than a dozen researchers spread across four network nodes (RIT, Johns Hopkins, Goddard Space Flight Center, and University of Idaho), their students and collaborators, our work under this TCAN will yield the most astrophysically realistic predictions of EM signals to date. This work is critical for linking the wealth of observational data that we expect about binary mergers containing supermassive black holes in the very near future, as we enter the era of LISA and Pulsar Timing discovery. It is also relevant to many other NASA observational campaigns such as Chandra, Hubble, Swift, Fermi, JWST, and Roman.\n\nOver the past ten years, our group has built the knowledge base and computational methods needed to reach this goal, and we are now ready to take the final steps. We have built the complete simulation infrastructure to permit simulation of gas accretion that will allow us to efficiently evolve these simulations from the early-Newtonian stage into the late-inspiral, merger and post-merger regimes.\n\nOur radiation post-processing tools allow us to transform fluid simulation data into time- and energy-dependent predictions of photon radiation, accounting for the principal radiation mechanisms, opacities, and photon propagation through dynamical spacetimes.\n\nWe propose to use these tools to study how the accretion from a surrounding circumbinary disk is distributed between the members of the supermassive black hole binary as a function of the binary separation, mass-ratio, black hole spins and orbital eccentricity, and how this may change when the separation becomes small enough for relativistic effects to become important. Mass transfer from one member of the binary to the other may play an especially interesting role. We will then simulate what happens to the gas surrounding the black holes during the merger proper and the subsequent relaxation phase. We will use our post-processing machinery to predict EM spectra and light curves throughout all these phases.\n\nThis network will allow us to identify the most distinctive features of the photon emission associated with a supermassive black hole merger and how they may change over time; the clearest spectral signatures to distinguish merging\n\nblack holes against the background of stellar light from their host galaxies or from single supermassive black hole systems along with their jets.\n\n\nThis project will be a guiding beacon to enable current and future observational campaigns to recognize the transient EM signals of supermassive black hole mergers, events that both emit enormous amounts of energy in GWs and strongly influence the cosmological evolution of the supermassive black hole population. Creating such a capability is crucial for the success of the new field of multimessenger astronomy.","project_type":"Grant","lead":"Zachariah Etienne","affiliation":"COS Physics","partners":"National Aeronautic Space Ad.","funder":"Rochester Institute of Technology","award_number":"80NSSC24K0100","date":"2023","status":"Active","subject":["supermassive black holes","binary black holes","accretion disks","electromagnetic radiation","gravitational waves","multimessenger astronomy","numerical relativity"],"confidence":"High","source_url":"https://ccrg.rit.edu/index.php/content/grants/2023/manuela-campanelli/electromagnetic-signals-merging-supermassive-black-holes","project_url":"https://www.uidaho.edu/news/news-articles/news-releases/2024/021324-black-holes","funder_agency":"NASA","research_area":"Physics & astronomy"},{"objectid":"usda_brooks_water_security_wildfire","title":"Ensuring Water Security with Increasing Wildfire Threats in the Western US","gist":"Research on wildfire impacts on soil properties and watershed recovery using WEPPcloud modeling and federal decision support tools.","description":"This University of Idaho research project investigates how high-severity wildfires and low-severity prescribed burns alter soil biophysical, hydraulic, and chemical properties, while analyzing subsequent watershed recovery. Field burn experiments and soil characterization data are utilized to parameterize and test WEPPcloud, a geospatial modeling platform designed to simulate post-fire runoff and erosion. In collaboration with federal partners, the team develops geospatial decision support tools to aid in both pre-fire and post-fire watershed management strategies.","project_type":"Subaward","lead":"Erin Brooks","affiliation":"CALS Soils and Water Systems","partners":"USDA Forest Service","funder":"Washington State University","award_number":"80NSSC22K0920","date":"2023","status":"Active","subject":["wildfire","watershed recovery","soil erosion","prescribed burn","runoff","geospatial modeling","water security"],"confidence":"Low","evidence_note":"Internal source: the University of Idaho sponsored-projects record. The award is confirmed there; this sponsor publishes no project description. A request for one is outstanding.","funder_agency":"University partner","research_area":"Water resources"},{"objectid":"doe_vasdekis_entanglement_enhanced_visual","title":"Entanglement-Enhanced Visual Metabolomics: from Single-Cells to Populations","gist":"Entanglement-enhanced imaging of single-cell metabolism to guide biofuel strain design.","description":"A University of Idaho physics project led by Andreas Vasdekis, building a multimodal imaging platform that makes cellular metabolism visible one cell at a time. It combines interferometry, mid-infrared photothermal, and light-sheet fluorescence imaging with quantum and classical entanglement to sharpen sensitivity and cut phototoxicity, then pairs the imaging with deep learning and genome-scale metabolic models to explain why genetically identical cells become over- or under-producers of biofuel precursors.","project_type":"Grant","lead":"Andreas Vasdekis","affiliation":"COS Physics","funder":"U.S. Department of Energy","award_number":"DE-SC0025418","date":"2024","status":"Active","subject":["metabolomics","single-cell analysis","population biology","quantum sensing","visual metabolomics","cellular metabolism","entanglement"],"confidence":"High","funder_agency":"Department of Energy","research_area":"Genomics & molecular biology"},{"objectid":"usdi_miesel_environmental_climate_drivers","title":"Environmental and climate drivers of fuel treatment longevity in Sierra Nevada mixed-conifer forests","gist":"Analyzing fuel treatment longevity and fire behavior in Sierra Nevada mixed-conifer forests under changing climate conditions.","description":"This project analyzes vegetation and fuel load changes over time in Sierra Nevada mixed-conifer forests following mechanical and fire fuel reduction treatments. By leveraging FBAT data resources, the study evaluates treatment effectiveness, validates fire behavior models against empirical observations, and simulates future fuel accumulation under varying climate scenarios. The research synthesizes findings into a decision support tool to help managers select optimal treatment types, intensities, and frequencies for local conditions, ultimately improving forest resilience and reducing catastrophic wildfire risks.","abstract":"OUR OVER-ARCHING OBJECTIVE IS TO INFORM FUEL REDUCTION STRATEGIES THAT IMPROVE FUEL TREATMENT EFFECTIVENESS FOR REDUCING RISK OF CATASTROPHIC WILDFIRES. WE PROPOSE TO LEVERAGE THE FBAT DATA RESOURCES TO ADDRESS THE FOLLOWING RESEARCH QUESTIONS:   Q1: HOW DO FOREST VEGETATION AND FUEL LOADS CHANGE OVER TIME AFTER MECHANICAL AND FIRE FUEL REDUCTION TREATMENTS  WE WILL USE THE FBAT DATA ON VEGETATION AND FUELS AT MULTIPLE TIME-POINTS TO EVALUATE IMMEDIATE CHANGE AND CHANGE OVER E10 YEARS.   Q2: HOW EFFECTIVE ARE FUEL REDUCTION TREATMENTS FOR REDUCING UNDESIRABLE WILDFIRE EFFECTS, AND HOW DO PREDICTED FIRE BEHAVIOR AND EFFECTS DIFFER FROM EMPIRICAL OBSERVATIONS  WE WILL APPLY THE FBAT DATA TO VEGETATION AND FIRE BEHAVIOR MODELS AND VALIDATE THE PREDICTIONS WITH EXISTING CO-LOCATED EMPIRICAL MEASURES OF FIRE BEHAVIOR AND EFFECTS.   Q3: HOW DOES VEGETATION CHANGE AND FUEL ACCUMULATION VARY WITH CLIMATE CONDITIONS TO INFLUENCE POTENTIAL FUTURE FIRE BEHAVIOR  WE WILL SIMULATE VEGETATION CHANGE AND FUEL ACCUMULATION FOR CURRENT AND FUTURE CLIMATE SCENARIOS AND PREDICT FIRE BEHAVIOR AND EFFECTS FOR CONTRASTING BURNING CONDITIONS.THE PROPOSED PROJECT WILL PROVIDE UNIQUE CAPACITY TO PREDICT CHANGES IN VEGETATION AND FUELS OVER TIME, TO EVALUATE HOW FUEL TREATMENTS AND TIME SINCE TREATMENT INFLUENCE FIRE BEHAVIOR, AND TO EVALUATE HOW RESULTS DIFFER AMONG CONTRASTING TREATMENTS AND WITH ENVIRONMENTAL VARIABILITY. OUR CAPABILITY TO VALIDATE PREDICTED FIRE BEHAVIOR AND EFFECTSUSING EXISTING EMPIRICAL MEASUREMENTS WILL PROVIDE IMPORTANT INSIGHTS ON THE CONFIDENCE OF POTENTIAL FIRE BEHAVIOR PREDICTIONS, WHICH CAN HELP FURTHER ADVANCE MODELS AND DECISION SUPPORT TOOLS. THE RESULTS WILL BE SYNTHESIZED INTO A DECISION SUPPORT TOOL THAT ENABLES MANAGERS TO SELECT THE TYPE, INTENSITY, AND FREQUENCY OF FUEL REDUCTION TREATMENTS BEST SUITED FOR LOCAL FOREST CONDITIONS AND DESIRED OUTCOMES. WE WILL PARTNER WITH THE CALIFORNIA FIRE SCIENCE CONSORTIUM TO OFFER A FIELD TOUR, RESEARCH BRIEFS, AND A WEBINAR. WE WILL ORGANIZE A SPECIAL SESSION AT A SCIENTIFIC MEETING AND COORDINATE A JOURNAL SPECIAL ISSUE ON THE SESSION TOPIC. WE ANTICIPATE THAT OUR RESULTS AND PRODUCTS WILL BENEFIT FUELS AND FIRE MANAGERS, OTHER SCIENTISTS, AND POLICYMAKERS BY IMPROVING KNOWLEDGE OF RELATIONSHIPS AMONG FUELS AND FIRE BEHAVIOR, AND HOW THESE RELATIONSHIPS MAY VARY IN THE FUTURE. THE PROPOSED STUDY AIMS TO PROVIDE ACTIONABLE RESULTS FOR FOREST MANAGEMENT DECISIONS THAT IMPROVE FOREST RESILIENCE IN A CHANGING CLIMATE.","project_type":"Cooperative Agreement","lead":"Jessica Miesel","affiliation":"CNR Forest, Rangeland & Fire Sci","funder":"USDI Bureau Of Land Management","date":"2023","status":"Active","subject":["fuel treatment","wildfire","fire behavior","mixed-conifer forests","sierra nevada","climate change","fuel accumulation"],"confidence":"High","source_url":"https://www.usaspending.gov/award/ASST_NON_L23AC00387_014","project_url":"https://www.frames.gov/fbat","funder_agency":"Bureau of Land Management","research_area":"Fire science"},{"objectid":"wsu_nuismer_epidemiology_modelling_studies","title":"Epidemiology and modelling studies to support Rift Valley fever vaccine efficacy trials in East Africa","gist":"Modeling Rift Valley fever spread in East Africa to identify trial sites for human vaccines.","description":"This project combines epidemiology and computational modeling to forecast the spread of Rift Valley fever in East Africa, a mosquito-borne virus causing severe illness in humans and devastating livestock herds. By analyzing historical data, climate projections, and factors like livestock movement and extreme weather, researchers identify outbreak hotspots in Kenya, Uganda, and Tanzania. These findings provide critical information for selecting sites for upcoming human clinical trials, addressing the current lack of licensed human vaccines for the disease.","abstract":"A two-year, $9.6 million effort led in part by Washington State University will help provide a better understanding of the spread and impact of the deadly Rift Valley fever virus in Africa and to prepare for upcoming human clinical trials.\n\nRift Valley fever is a mosquito-borne illness that can cause severe sickness and death in humans, and it is particularly devastating to livestock herds. Outbreaks have been consistently linked with intense periods of rainfall and flooding, which promotes mosquito breeding and hatching.\n\n[…]\n\nThe project is funded by the Coalition for Epidemic Preparedness Innovations (CEPI), a global partnership working to accelerate the development of vaccines and countermeasures against epidemic and pandemic threats. The goal is to forecast the geographical spread and number of human Rift Valley fever cases in Africa today and in the future, information critical for vaccine development and large-scale clinical trials testing vaccine candidates and other tools. While vaccines exist for livestock, none are currently licensed for human use.\n\n[…]\n\nResearchers will analyze historical and current data to better understand how the virus spreads in animal populations, how it spills over into people and which communities are at risk. They will also examine the roles of livestock movement, land-use changes and extreme weather events, all factors thought to contribute to the disease’s expanding range and more frequent outbreaks.\n\nThe effort includes two complementary studies focused on epidemiology and computational modeling. The Rift Valley Fever Vaccine Efficacy Trial Studies (RVF-VETS) project, led by WSU Global Health – Kenya, will receive $6.2 million, while the Rift Valley Fever Epidemiology and Modelling to Inform Vaccine Efficacy Trials (REMIT) project, led by the Kilimanjaro Clinical Research Institute in Tanzania with WSU as a partner, will receive up to $3.4 million.\n\nRVF-VETS researchers will use infection data in East Africa, along with climate projections, to predict outbreak hotspots in Kenya, Uganda, and Tanzania — regions with some of the highest Rift Valley fever burdens. These models will help identify potential sites for future human vaccine trials.","project_type":"Subaward","lead":"Scott Nuismer","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","partners":"Coalition for Epidemic Preparedness Innovations (CEPI)","funder":"Washington State University","date":"2025","status":"Active","subject":["rift valley fever","epidemiology","disease modeling","vaccine trials","mosquito-borne diseases","east africa","zoonoses"],"confidence":"High","source_url":"https://news.wsu.edu/press-release/2025/09/09/wsu-researchers-join-9-6m-push-to-fight-rift-valley-fever/","project_url":"https://cepi.net/landmark-african-led-research-map-extent-rift-valley-fever-impact","funder_agency":"University partner","research_area":"Health & disease"},{"objectid":"nsf_zhao_epscor_fellows_enhancing","title":"EPSCoR Research Fellows: NSF: Enhancing Water Budget Simulations across CONUS: Modeling Vegetation Uptake of Rock Moisture","gist":"Modifying the Community Land Model Version 5 to simulate vegetation uptake of rock moisture from weathered bedrock across the continental U.S.","description":"This project implements an innovative approach within the Community Land Model Version 5 to represent vegetation uptake of rock moisture stored in unsaturated, weathered bedrock. By truncating root profiles to the unweathered bedrock position, the research addresses a critical gap where current land models ignore substantial plant-available water, leading to biased predictions of ecosystem water consumption. The study evaluates the impact of this modification on water budget simulations across the continental U.S. by comparing model performance against observations of evapotranspiration and streamflow during climatic extremes. These efforts aim to refine simulations of water budget dynamics, thereby improving predictive capabilities for water availability and environmental resilience under a changing climate.","abstract":"Accurate water resource predictions are critical for the nation’s water security, especially during extreme events. Today, communities are experiencing increasingly frequent floods and droughts, heat waves, and wildfires, all of which will impact vegetation behaviors and drive land use/cover changes. As such, predicting the resulting impacts on water budget components is fundamental to enhancing the nation’s preparedness for water-related hazards and water scarcity under a changing climate. However, virtually all land models ignore a substantial volume of plant-available water stored in unsaturated, weathered bedrock. This oversight can lead to biased predictions of ecosystem water consumption and downstream water budget components, jeopardizing the nation’s water-food-energy security. The research objective of this proposed project will be to directly address this knowledge gap by implementing an innovative approach within the Community Land Model Version 5 (CLM5) to represent vegetation's uptake of rock moisture and subsequently evaluate its impact on water budget simulations across the continental U.S. (CONUS). This fellowship will enable the PI to establish a mentor-mentee relationship with Dr. Sean Swenson, a prominent hydrologist and core developer of CLM5, and to receive specialized training and access to state-of-the-art land modeling equipment at the National Center for Atmospheric Research (NCAR).\n\nSpecifically, the PI proposes that modeling plant access to rock moisture will refine simulations of water budget dynamics. To investigate this hypothesis, the PI will visit NCAR for two summers, where Dr. Swenson will mentor the PI in advanced techniques for modifying land models, focusing on CLM5—a leading-edge land model widely used to study the role of land in climate and weather. To enable vegetation water uptake from the weathered bedrock layer, this fellowship project will truncate the root profile by the position of the unweathered bedrock, which will stimulate root growth into the hydrologically active bedrock layer and account for the ability of the vegetation to extract water stored in weathered bedrock. The team will run the original CLM5 and the rock moisture configuration with the same forcing data. Then, they will compare the performance of the two models, assessed by their accuracy in simulating observations of evapotranspiration and streamflow, as well as their responses to climatic extremes. This collaborative endeavor will advance the understanding of land-atmosphere interactions and improve the predictive capabilities of land models, ultimately contributing to more accurate assessments of water availability and environmental resilience across the CONUS. The broader impacts of this fellowship will be further extended through installing CLM5 on Idaho’s supercomputer, organizing a workshop for academic professionals and students, and crafting a hands-on CLM5 course. Together, these efforts will enhance Idaho’s hydroclimate modeling infrastructure, enhance research capabilities, empower STEM researchers and students, and elevate Idaho’s standing in national research endeavors.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Meng Zhao","affiliation":"COS Earth and Spatial Sciences","funder":"National Science Foundation","award_number":"2429739","date":"2024","end_year":"2027","status":"Active","subject":["land surface modeling","community land model","rock moisture","vegetation water uptake","hydrology","evapotranspiration","continental united states"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2429739","funder_agency":"National Science Foundation","research_area":"Water resources"},{"objectid":"nsf_ma_epscor_fellows_incorporating","title":"EPSCoR Research Fellows: NSF: Incorporating Knowledge Graphs and Reasoning Capabilities for Enhanced Visual Data Exploration in Mineral Evolution","gist":"A fellowship developing data science workflows for mineralogy research through collaboration with the Deep-time Data Driven Discovery initiative at the Carnegie Institution for Science.","description":"This fellowship supports a six-month visit to the Carnegie Institution for Science to develop a reusable methodology for deploying data science in geoscience studies, specifically within mineralogy. The project integrates existing software and data elements to create workflows that bridge the gap between data scientists and geoscientists, enhancing the lead researcher's capabilities in software development and data curation. By fostering collaboration with the Deep-time Data Driven Discovery initiative, the work establishes frameworks for open data and code practices that will be incorporated into university curricula and applied across geosciences, agricultural science, physics, and chemistry.","abstract":"The goal of this fellowship project is to enhance the lead researcher's career trajectory in data science and geoinformatics through a six-month visit to the Carnegie Institution for Science in Washington, DC (CIW), a leading laboratory in the field. The fellowship will establish a reusable methodology for efficiently deploying data science in geoscience studies to accelerate scientific discoveries. Focusing on mineralogy, the project will implement an empirical approach to integrate existing software and data elements for data exploration. The lead researcher, who has developed software packages for knowledge graphs and data visualization, will collaborate with scientists from the Deep-time Data Driven Discovery (4D) initiative at CIW. This established long-term collaboration with 4D and CIW will enhance the researcher’s research capabilities at the University of Idaho (UI), including software development, data curation, and leadership in cross-disciplinary research. The resulting data science methodology will have a sustained impact on the researcher’s future career. As researchers across many disciplines seek methods to efficiently deploy data science in their work, this fellowship will open numerous opportunities for the researcher to collaborate with researchers both within and outside UI.\n\nThis fellowship will provide an innovative approach to improving the interconnection and usability of existing software building blocks in open data and open science, facilitating data-driven scientific discoveries within the 4D initiative, a community of over 220 earth, space, life, and data scientists from several countries. The project will significantly enhance the researcher's research capacity, progressing from the development of data and software elements to constructing comprehensive data science frameworks. These efforts will ultimately create workflows that bridge the gap between data scientists and geoscientists. Through the established long-term connection with the 4D network, the researcher will explore cutting-edge topics in data science applications, contribute to the international research community, and cultivate a pioneering professional path that impacts various cross-disciplinary studies. More significantly, the project will provide a foundation for the researcher to contribute to the theoretical underpinnings of data science and develop methods that improve the efficiency of data science application and education. This project will enable the researcher to incorporate new examples and methods into the data science curriculum at UI. Additionally, the software tools and workflows developed will be broadly applicable to researchers and students in geosciences, agricultural science, physics, and chemistry at UI and beyond. The planned conference sessions and presentations aim to promote a shift towards more open practices in data and code across geoscience and other disciplines, fostering a growing acceptance of open data and open code as standard practices in data-intensive research.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Xiaogang Ma","affiliation":"COE Computer Science","funder":"National Science Foundation","award_number":"2428775","date":"2024","end_year":"2026","status":"Active","subject":["mineral evolution","knowledge graphs","data visualization","geoinformatics","open data","mineralogy","data science"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2428775","project_url":"https://www.uidaho.edu/newsroom/marshall-ma-epscor-award","funder_agency":"National Science Foundation","research_area":"Data science & computing"},{"objectid":"nsf_pennick_epscor_fellows_obtaining","title":"EPSCoR Research Fellows: NSF: Obtaining Data Science Expertise to Support Evidence-based Policymaking for Public Lands Counties","gist":"Uses natural language processing to build a dataset analyzing how federal public lands affect rural county tax and expenditure decisions.","description":"This project establishes a fellowship to develop data science expertise for analyzing the economic impacts of public lands on rural western counties. By applying natural language processing and large language models to unstructured local government financial reports, the research creates a standardized dataset of fiscal decision variables. This infrastructure enables new investigations into how federal public lands influence county-level tax and expenditure decisions while accounting for state aid and local policies. The resulting data framework supports the development of a Public Lands County Finance Center and strengthens computational research capabilities within the University of Idaho.","abstract":"This Research Infrastructure Improvement EPSCoR Research Fellows project provides a fellowship to a Research Assistant Professor at the University of Idaho. This work is conducted in collaboration with Dr. Tyler Scott and the Center for Environmental Policy & Behavior (CEPB) at University of California, Davis. CEPB is a research training center for quantitative social scientists from multiple graduate programs. The principal investigator (PI) will learn how to create and maintain a program for environmental policy and management research that scales across individual faculty and students. The PI will also draw from CEPB’s expertise in natural language processing and related data science skills. These tools will be applied to process and analyze novel data about the economics of public lands and local government budgets in the rural west.  The novel dataset resulting from this project will provide infrastructure for new research on the impacts of public lands on local government financial conditions. \n\nAdvances in data science, such as the use of large language models, present unrivaled opportunities to make unstructured data available to answer important questions. As part of this fellowship, the PI proposes to use natural language processing and transformer-based models (i.e., large language models) to collect, aggregate, and standardize local government financial reports and administrative records to build a dataset of local government fiscal decision variables, enabling the PI to explore new questions about the relationship between federal public lands and county-level fiscal outcome variables (tax and expenditure decisions). Further, the study will simultaneously investigate the factors that mediate or exacerbate these relationships including state factors (state-level aid, tax and expenditure restrictions) and local circumvention policies (special districts, redistribution policies). This fellowship will provide core research infrastructure for computational data science within the PI’s department and the data infrastructure to support the development of a Public Lands County Finance Center in conjunction with the University of Idaho’s Institute for Interdisciplinary Data Science. This project is supported by the EPSCoR Research Infrastructure Improvement Program: EPSCoR Research Fellows, which supports early- and mid-career investigators in eligible jurisdictions to develop collaborations at the nation’s private, government or academic research institutions.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Chelsea Pennick","affiliation":"CNR Natural Resources & Society","funder":"National Science Foundation","award_number":"2531762","date":"2025","end_year":"2027","status":"Active","subject":["public lands","local government finance","natural language processing","fiscal policy","rural west","large language models","environmental policy"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2531762","funder_agency":"National Science Foundation","research_area":"Social & economic"},{"objectid":"nsf_hendricks_equipment_track_acquisition","title":"Equipment: MRI: Track 1 Acquisition of Element AVITI System to Enable Multi-Omics Research and Research Training.","gist":"University of Idaho acquires an Element AVITI24 platform to enable multi-omics research in agriculture, conservation, and infectious diseases.","description":"The University of Idaho's Genomics and Bioinformatics Resources Core acquires an Element Biosciences AVITI24 sequencing platform to enable multi-omics research and single-cell profiling. This instrumentation supports studies in agricultural resilience, endangered species protection, and infectious disease mechanisms while expanding regional scientific infrastructure. The project also facilitates training for students and early-career scientists in genomics and bioinformatics to build a skilled STEM workforce.","abstract":"An award is made to the University of Idaho (UI) to enable the Genomics and Bioinformatics Resources Core (GBRC) to acquire an Element Biosciences AVITI24 sequencing platform, a technology that combines traditional sequencing with advanced single-cell and multi-omics capabilities. This instrumentation will power transformative research with direct societal impact, including efforts to improve agricultural resilience, protect endangered species, and advance biomedical discoveries related to infectious diseases. As the first platform of its kind in Idaho and the inland Pacific Northwest, the AVITI24 will strengthen regional scientific infrastructure, foster new collaborations, and expand access to high-quality genomics tools across institutions. The research will also support training initiatives that equip students and early-career scientists with hands-on experience in cutting-edge genomics and bioinformatics, helping build a skilled STEM workforce.\n\nThe research enabled by this platform at UI will significantly expand the capacity for innovative work across disciplines such as biomedical science, microbial ecology, conservation biology, and evolutionary genetics. The AVITI24’s high-throughput sequencing and single-cell profiling features will allow researchers to investigate gene expression, microbial communities, and cellular interactions at unprecedented resolution. These capabilities will enhance ongoing studies of species adaptation, genetic disease mechanisms, and host-pathogen dynamics while also promoting cross-disciplinary collaboration. By fostering technological advancement and generating new knowledge, this investment will elevate research competitiveness at UI and broaden the region’s contribution to national scientific priorities.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Sarah Hendricks","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2511003","date":"2025","end_year":"2028","status":"Active","subject":["genomics","single-cell sequencing","multi-omics","bioinformatics","microbial ecology","conservation biology","infectious diseases"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2511003","funder_agency":"National Science Foundation","research_area":"Genomics & molecular biology"},{"objectid":"nih_robison_eradicating_misconceptions_about","title":"Eradicating Misconceptions about Viruses using Multimodal Trace Data in an Intelligent Game-based Environment across Educational Contexts","gist":"A game-based simulation uses multimodal trace data to remediate infectious disease misconceptions and build systems thinking skills across educational contexts.","description":"This project develops a game-based simulation to address pervasive scientific misconceptions about infectious diseases, which pose significant medical and social risks. By integrating evidence-based information with societal factors and individual risk representations, the initiative moves beyond simple fact correction to effectively remediate deeply held misunderstandings. The program provides teachers with digital tools that foster systems thinking and data science literacy while simultaneously inspiring diverse young people to pursue careers in biomedical research.","abstract":"Project Summary / Abstract.\nScientific misconceptions are becoming increasingly pervasive and damaging to the national\ninterest. The ongoing SARS-CoV-2 pandemic has highlighted how misconceptions related to\ninfectious disease can pose serious medical, economic, and social challenges by increasing\nnon-compliance with public health recommendations and undermining trust in scientific\ninstitutions. Unfortunately, once scientific misconceptions are adopted by an individual, they are\nnotoriously difficult to remediate by merely presenting the “correct” information. We need\neducational programs and tools that integrate evidence-based information with broader societal\nfactors, representation of individual risk, and multiple representations of information to improve\nour ability to correct misconceptions. Our goal is to create an innovative, sustainable, and\nreproducible educational program that: (1) Creates and deploys an innovative game-based\nsimulation to educate users about infectious diseases, (2) Inspires young people from diverse\nbackgrounds to consider careers in biomedical research, (3) Provides teachers with engaging\nand easily adopted digital tools that build students’ systems thinking and data science literacy\nskills, and (4) Conducts innovative STEM education research about the remediation of\nmisconceptions using systems thinking and Advanced Learning Technologies.","project_type":"Grant","lead":"Barrie Robison","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Institutes of Health","award_number":"R25GM150142","date":"2023","end_year":"2028","status":"Completed","subject":["infectious diseases","scientific misconceptions","game-based learning","systems thinking","stem education","multimodal data","sars-cov-2"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/10664776","project_url":"https://polymorphiced.uidaho.edu/","funder_agency":"National Institutes of Health","research_area":"Health & disease"},{"objectid":"nsf_li_drones_enabled_active","title":"ERI: Drones-Enabled Active Sensing System (DEASS) for Detection of Subsurface Defects in Civil Infrastructure through Synchronized Drone Swarming and Thermal Imaging","gist":"A synchronized drone swarm system using active microwave heating and thermal imaging to detect subsurface defects in concrete infrastructure within GPS-denied environments.","description":"This Engineering Research Initiation project develops a drones-enabled active sensing system using synchronized leader-follower swarms to detect subsurface defects in civil infrastructure within GPS-denied environments. One drone performs thermal imaging while the other provides active microwave heating, overcoming the payload and battery limitations of single-drone systems. The research establishes new strategies for cooperative robot swarming and active thermal imaging to identify issues like delamination and horizontal cracks in reinforced concrete, transforming current passive inspection practices that rely on sunlight conditions.","abstract":"This award is funded in whole or in part under the American Rescue Plan Act of 2021 (Public Law 117-2).\n\nThis Engineering Research Initiation (ERI) project will explore an active thermal imaging system carried by a pair of drones, one (leader) for thermal imaging and the other (follower) for active heating (e.g., microwave), to enable subsurface defect detection in the next-generation inspection of civil infrastructure in a GPS-denied environment (e.g., underneath bridge decks). Due to its limited payload and battery time, a single drone cannot support additional payload and its associated accessories required for active sensing. The concept of two leader-follower drones is thus introduced. This award supports fundamental research for the development of a drones-enabled active sensing system through synchronized drone swarming and thermal imaging. The new technique will transform the current passive surface deterioration inspection practice, which is subject to the change in sunlight conditions, into an active thermal imaging inspection for subsurface condition deterioration, such as delamination and horizontal cracks in reinforced concrete structures. In addition to infrastructure inspection and maintenance, the new technique will impact multiple frontiers with cooperative robot swarming and active sensing, such as interactive manufacturing and healthcare, and academic communities in science and engineering. The technique and research results will be transferred into the hands of engineering professionals through a national workshop.\n\nThe drones-enabled active sensing system will be investigated via software/hardware-in-the-loop simulations and experimental tests. This research will overcome two technical challenges: (1) to synchronize drone swarming and thermal imaging in an energy-efficient strategy and (2) to enable new thermal imaging detectability with a heat source distributed on a leader-follower drone platform to stimulate the appearance of subsurface defects in active imaging. It will lay a foundation on cooperative robot swarming and active sensing research in multiple frontiers. First, it will develop a new strategy of leader-follower formation for drone swarming with visual relative navigation and collision avoidance based on a three-dimensional stereo vision and potential field algorithm during cooperative active sensing and inspection of subsurface defects in a GPS-denied environment. Second, it will establish optimal characteristics of active sensing of microwave heated concrete decks with optimized microwave excitations (energy source, frequency and duration) and sensing protocols (measurement sensitivity, frame rate and time window). Third, it will develop a method to evaluate and improve the performance of cooperative drone swarm formation and active thermal imaging of defects in a markup solid deck concrete bridge and a potential field infrastructure inspection.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Johnny Li","affiliation":"CALS Soils and Water Systems","funder":"National Science Foundation","award_number":"2312081","date":"2023","end_year":"2025","status":"Active","subject":["drone swarming","active thermal imaging","subsurface defect detection","civil infrastructure","cooperative robotics","microwave heating","gps-denied navigation"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2312081","funder_agency":"National Science Foundation","research_area":"Data science & computing"},{"objectid":"usdi_tranmer_prioritizing_public_lands","title":"Evaluating and prioritizing public lands for large-scale native riparian forest regeneration","gist":"Decision-support tools for prioritizing Henry's Fork riparian restoration.","description":"A University of Idaho project led by Andrew Tranmer that gives the Bureau of Land Management decision-support tools for riparian and aquatic restoration along the lower Henry's Fork of the Snake River. The team models aquatic habitat for Yellowstone cutthroat trout, floodplain regeneration of native cottonwood and willow, and habitat for the threatened Western yellow-billed cuckoo, using advanced LiDAR to map riparian forest structure tree by tree so managers can prioritize restoration and quantify outcomes.","project_type":"Grant","lead":"Andrew Tranmer","affiliation":"COE Ctr for Ecohydraulics Research","funder":"USDI Bureau Of Land Management","date":"2024","status":"Active","subject":["riparian forest","forest regeneration","public lands","conservation prioritization","native species","land management","restoration ecology"],"confidence":"Medium","funder_agency":"Bureau of Land Management","research_area":"Forestry"},{"objectid":"idhw_brown_excessive_alcohol_factsheets","title":"Excessive Alcohol Use Factsheets- IDHW","gist":"Part of Modeling Idaho Health, this program generates county-level health risk data from CDC surveys to guide local public health interventions and strategic planning.","description":"Part of Modeling Idaho Health, an evaluation and research team within the University of Idaho's Institute for Modeling Collaboration and Innovation, this entry covers the broader effort to generate county-level adult health measures using CDC Behavioral Risk Factors Surveillance System data. The team utilizes small area estimates modeling to identify health risks and plan strategic interventions for Idaho counties, cities, and public health districts. While alcohol-related studies are currently listed as 'Coming Soon,' the program focuses on downscaling data previously available only at the public health district level to support local action.","project_type":"Grant","lead":"Helen Brown","affiliation":"RCI IMCI","partners":"Centers for Disease Control and Prevention","funder":"Idaho Department of Health and Welfare","date":"2025","status":"Active","subject":["alcohol use","small area estimation","behavioral risk factors","public health surveillance","county-level health","health interventions","idaho"],"confidence":"Medium","source_url":"https://modelingidahohealth.org/","project_url":"https://modelingidahohealth.org/","funder_agency":"State of Idaho","research_area":"Health & disease"},{"objectid":"ai4ui_execord","title":"ExecOrd","description":"Compliance tracking prototype for federal Executive Order impacts on the institution.","significance":"Systematic EO response posture. Reduces scramble when new EOs drop. Living view of EO-driven obligations for leadership.","status":"Building","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nih_rowley_exploring_mechanisms_cellular","title":"Exploring the Mechanisms and Cellular Specificities of Antifungal Toxins","gist":"Investigates molecular mechanisms, cell-type specificity, and resistance evolution of fungal killer toxins using the Saccharomyces K1 model.","description":"This research program investigates the molecular mechanisms of fungal toxin-mediated cell killing, the pathways governing toxin susceptibility, and the evolutionary dynamics of toxin-target interactions. By integrating molecular modeling, artificial intelligence, evolutionary biology, and biochemistry, the project uncovers the determinants of toxin cell-type specificity. The work utilizes the Saccharomyces K1 toxin as a model to explore structural homology, cellular interactions, and resistance evolution through changes to the fungal cell wall and membrane. These findings enhance understanding of fungal resistance mechanisms against external stressors and open new avenues for antifungal strategies targeting opportunistic fungal pathogens.","abstract":"PROJECT SUMMARY\nFungal toxins are critical to microbial competition and pathogenicity, offering valuable insights into\ntheir interactions with fundamental cellular processes and in microbial ecology. This research\nprogram investigates the molecular mechanisms of fungal toxin-mediated cell killing, the\npathways that govern toxin susceptibility, and the evolutionary dynamics of toxin-target\ninteractions. By integrating molecular modeling, artificial intelligence, evolutionary biology, and\nbiochemistry, the program aims to uncover the determinants of toxin cell-type specificity, with\nfuture implications for understanding the molecular mechanisms of protein toxins and\nfundamental cellular processes in fungi.\nThe investigator has established foundational knowledge of killer toxin diversity, specificity, and\nmechanisms of action. These studies have identified critical pathways influencing toxin\nsusceptibility, demonstrated the rapid evolution of toxins and their targets, and uncovered novel\nantifungal activities with potential commercial applications. The investigator’s proven productivity,\ndedication to mentoring future scientists, and development of innovative methodologies highlight\nthe ability to deliver impactful research while adapting to emerging technologies and evolving\nquestions in killer toxin research.\nThis program will advance our understanding of diverse killer toxins produced by fungi, focusing\non their cytotoxicity and interactions with cellular structures. It aims to address key knowledge\ngaps in toxin function and specificity by developing a rapid toxin characterization pipeline. The\nprogram will also use the Saccharomyces K1 toxin as a model to investigate its structural\nhomology with other toxins, explore its interactions with fungal cells, and examine the evolution\nof resistance, mainly through changes to the fungal cell wall and membrane. This research will\nenhance our understanding of resistance mechanisms evolved by fungi in response to external\nstressors and open new avenues for antifungal strategies targeting opportunistic fungal\npathogens.","project_type":"Grant","lead":"Paul Rowley","affiliation":"RCI IMCI","funder":"National Institutes of Health","award_number":"R35GM161960","date":"2025","end_year":"2031","status":"Active","subject":["killer toxins","fungal toxins","antifungal resistance","cell wall","membrane","molecular modeling","evolutionary biology"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/11260778","project_url":"https://www.rowleylab.com","funder_agency":"National Institutes of Health","research_area":"Genomics & molecular biology"},{"objectid":"usda_eigenbrode_harnessing_artificial_intellig","title":"FACT-AI: Harnessing artificial intelligence for implementing integrated pest management in small-grain production systems","gist":"An AI system for automated pest identification in wheat production using photo analysis to support integrated pest management in the Inland Pacific Northwest.","description":"This project develops an artificial intelligence-based decision support system to automate pest identification in wheat-based production systems across the Inland Pacific Northwest. By utilizing machine learning to analyze photographs, the system addresses the time and expertise barriers that often lead to unnecessary pesticide applications. The resulting tool allows growers, researchers, and extension educators to identify pests accurately, share photos and expertise, and access the platform via desktop interfaces as well as iOS and Android applications.","abstract":"A cornerstone of successful implementation of integrated pest management (IPM) in agriculture is correct pest identification but this requires time and expertise. As a result, many growers forgo identification and pesticide applications are made unnecessarily. This is a problem because indiscriminate use of pesticides is costly to growers and harmful to human health and the environment. Machine learning and artificial intelligence (AI) for automated pest identification from photographs has the potential to address this issue.The goal of this project is to develop such anAI-based decision support system for pest identification in wheat-based production systems of the Inland Pacific Northwest (PNW) USA, with extensibility to other wheat growing regions. In addition to the identification tool, this system will allow users to share photos and otherinformation as well as expertise about pests found. This system will be available to growers, crop researchers, and extension educators as a desktop computer interface as well as iOS and Android apps.","project_type":"Subaward","lead":"Sanford Eigenbrode","affiliation":"CALS Entomology,Plt Pathology,Nemat","partners":"National Institute of Food and Agriculture/USDA","funder":"Colorado State University","award_number":"2021-67021-34253","date":"2023","status":"Active","subject":["integrated pest management","small grains","wheat","pest identification","machine learning","artificial intelligence","inland pacific northwest"],"confidence":"High","source_url":"https://portal.nifa.usda.gov/web/crisprojectpages/1025693-fact-ai-harnessing-artificial-intelligence-for-implementing-integrated-pest-management-in-small-grain-production-systems.html","project_url":"https://github.com/sheneman/CerealPestAID","funder_agency":"University partner","research_area":"Agriculture"},{"objectid":"ai4ui_financial-planning-suite","title":"Financial Planning Suite (Axiom Replacement)","description":"Phased replacement of the Syntellis/Strata Axiom financial planning suite, whose contract runs through the end of calendar 2027 (~$200K/year to continue beyond that). Of the licensed modules, only Capital Planning is in production use; Strategic Financial Planning is signed off but unused, and the Budget & Forecasting and Tuition Planning implementations are stalled. Phase 1 delivers a capital planning solution before the contract ends so UI can exit Axiom without losing its one working module; later phases take up Budget & Forecasting, Tuition Planning, and Strategic Financial Planning — the modules the Budget Office originally wanted most.","significance":"Avoids ~$200K/year in vendor fees from 2028 onward and replaces stalled vendor-module implementations with tools the Budget Office actually uses. Phase 1 protects the one Axiom module in production before the contract lapses.","status":"Exploring","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nsf_etienne_frameworks_enabling_multimessenger","title":"Frameworks: E=mc2 - Enabling Multimessenger astrophysics through Community-driven Cyberinfrastructure","gist":"E=mc2 builds an open-source, exascale-ready simulation framework for binary neutron star and black hole-neutron star mergers with realistic neutrino transport.","description":"The E=mc2 project develops a community-driven, open-source cyberinfrastructure for simulating cosmic events like binary neutron star and black hole-neutron star mergers. By creating the first exascale-capable numerical relativity framework with realistic neutrino transport, the initiative enables multi-messenger observations that yield critical insights into general relativity, nuclear physics, and plasma physics. This high-performance software integrates with the Einstein Toolkit to support GPU and CPU architectures, fostering an inclusive scientific community through education and outreach while advancing fundamental physics knowledge.","abstract":"The E=mc2 project develops a community-driven cyberinfrastructure for simulating cosmic events such as binary neutron star and black hole-neutron star mergers. These cosmic collisions are incredibly energetic, emitting observable gravitational waves, electromagnetic waves, and neutrinos. Such \"multi-messenger\" observations provide critical insights into general relativity, nuclear physics, and plasma physics. The insights gained through these simulations promote the progress of science and enhance national scientific capabilities. By creating an open-source, high-performance simulation software framework, the project supports education and diversity, fostering a broad and inclusive scientific community. The cyberinfrastructure integrates into the Einstein Toolkit, making it widely accessible and facilitating interdisciplinary collaborations that benefit society by advancing knowledge in fundamental physics.\n\nThe E=mc2 project aims to develop the first open-source, exascale-capable numerical relativity and general relativistic magnetohydrodynamics cyberinfrastructure with realistic neutrino transport capabilities. This involves creating new codes based on Monte Carlo and moment schemes for neutrino modeling, and high-performance software compatible with both CPU and GPU architectures. The project will leverage existing frameworks like AMReX and the Einstein Toolkit, ensuring that the developed cyberinfrastructure can fully exploit modern high-performance computing resources. Key deliverables include modules for GPU-enabled particle-based neutrino simulations, a fully tabulated equation of state module for relativistic hydrodynamics, and advanced code generation tools to optimize performance. These tools will be rigorously tested and validated to ensure reliability and efficiency. The project also includes extensive community outreach and education efforts, including summer schools and workshops to train new users and expand the user base, ensuring sustained impact and community engagement in computational astrophysics.\n\nThis award supports research in relativity and relativistic astrophysics, and it addresses the priority areas of NSF's \"Windows on the Universe\" Big Idea.\n\nThis award by the Office of Advanced Cyberinfrastructure is jointly supported by the National Science Foundation's Big Idea activities in Windows on the Universe (WoU) and the Physics at the Information Frontier program in the Division of Physics in the Directorate of Mathematical and Physical Sciences.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Subaward","lead":"Zachariah Etienne","affiliation":"COS Physics","partners":"National Science Foundation","funder":"University of Illinois at Urbana–Champaign","award_number":"2411068","date":"2024","end_year":"2028","status":"Active","subject":["numerical relativity","multimessenger astrophysics","binary neutron stars","black hole mergers","general relativistic magnetohydrodynamics","neutrino transport","high-performance computing"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2411068","project_url":"https://einsteintoolkit.org/","funder_agency":"University partner","research_area":"Physics & astronomy"},{"objectid":"usdi_waits_genetic_monitoring_great","title":"Genetic Monitoring of the Great Gray Owl in Yosemite National Park","gist":"University of Idaho researchers analyze Great Gray Owl feathers in Yosemite to monitor genetic diversity and predict climate change impacts on the endangered subspecies.","description":"This project establishes a genetic monitoring protocol for the Great Gray Owl in Yosemite National Park by analyzing up to 1000 feathers using single nucleotide polymorphism panels. Researchers from the University of Idaho collaborate with park staff to assess population stability, genetic diversity, and relatedness within this isolated Sierra Nevada subspecies. The resulting data addresses critical information gaps regarding threats from habitat fragmentation and climate change, providing a scientific basis for managing the species which has fewer than 200 individuals remaining in California.","abstract":"Great gray owls (GGOs) are one of the rarest and most endangered birds in the state of California. With fewer than 200 individuals remaining, this Sierra Nevada endemic subspecies has a smaller population size than that of the California Condor. Yosemite National Park (YOSE) represents the core of the owl’s habitat, supporting two thirds of the remaining individuals, and the park provides a sanctuary for the southern range of the species, yet their population stability and trends are unknown.\n\nRecent research has revealed the fragility of the park’s population and has highlighted information gaps that limit our ability to manage and protect the species. There are genetic concerns about decreasing genetic diversity and increased relatedness of this geographically isolated population, and just outside the park boundaries, the owl is threatened by impacts from timber harvest, grazing, recreation, and hydrologic diversions. Much of the GGO habitat within the park is bisected by highways and highly trafficked meadows, and current and future construction sites.\n\nA research group led by Dr. Lisette Waits at the University of Idaho (UI) conducts genetic work to develop single nucleotide polymorphism (SNP) panels using next generation sequencing such as GT-Seq and RAD-Seq. Under this agreement, YOSE staff will work with Drs. Waits and Nerkowski to sequence and analyze up to 1000 feathers. Waits and Nerkowski will develop and use a GGO SNP panel to carry out population genetic analyses and develop a monitoring protocol for GGOs throughout YOSE.\n\nFurthermore, these data will enable researchers to better understand the past response of this species to large scale changes to historical climate fluctuations and better predict its response to expected future climate changes forecasted for North America","project_type":"Grant","lead":"Lisette Waits","affiliation":"CNR Fish & Wildlife Sciences","funder":"USDI National Park Service","date":"2024","status":"Active","subject":["great gray owl","population genomics","single nucleotide polymorphisms","yosemite national park","endangered species","climate change","non-invasive sampling"],"confidence":"High","source_url":"https://depts.washington.edu/pnwcesu/?p=17269","project_url":"https://affable-lwaits5f536fc511.wordpress.com/","funder_agency":"National Park Service","research_area":"Genomics & molecular biology"},{"objectid":"gwis_parent_graduate_women_science","title":"Graduate Women in Science Fellowships Award for Kelly Martin","gist":"The Parent Lab studies snail biodiversity and evolution using phylogenetics, genomics, and museum specimens to understand biogeographic drivers.","description":"Part of the Parent Lab at the University of Idaho, which investigates the drivers and processes of biodiversification through evolutionary and ecological research. The group focuses on understanding how biogeography impacts the distribution, ecology, and evolution of snails, particularly Galapagos Coleoptera and Pulmonate land snails. Utilizing phylogenetic, statistical, and genomic approaches, the team analyzes museum specimens and ecological gradients to answer questions about adaptive zone shifts and biodiversity patterns across varying spatial and temporal scales.","project_type":"Grant","lead":"Christine Parent","affiliation":"COS Biological Sciences","funder":"Graduate Women in Science","date":"2023","status":"Active","subject":["biogeography","land snails","phylogenetics","biodiversification","museum specimens","adaptive zones","evolutionary ecology"],"confidence":"Medium","source_url":"https://parentlab.weebly.com/people.html","project_url":"https://parentlab.weebly.com/people.html","research_area":"Other"},{"objectid":"nih_fortunato_hcmv_infection_downregulates","title":"HCMV infection downregulates nidogen 1 and myelin protein zero","gist":"A human 3D Schwann cell-neuron co-culture model investigates HCMV-induced downregulation of myelin protein zero and its link to sensorineural hearing loss.","description":"This project utilizes a novel all-human three-dimensional co-culture system of Schwann cells and neurons to investigate how Human Cytomegalovirus (HCMV) downregulates myelin protein zero (MPZ) and nidogen 1. By establishing baseline parameters for myelination and nerve conduction, the research assesses the specific impacts of HCMV infection and the tegument protein pp71 on peripheral nervous system development. The study addresses the mechanism behind sensorineural hearing loss in congenitally infected infants and late-onset cases, providing a species-restricted platform to examine extracellular matrix crosstalk and myelin production defects.","abstract":"ABSTRACT Human Cytomegalovirus (HCMV) is a leading cause of congenital birth defects. The most\ncommon sequela observed in symptomatic infants is sensorineural hearing loss (SNHL). SNHL is also\nobserved, somewhat perplexingly, during early childhood, developing over a period of years in children\nborn hearing competent and asymptomatic for infection at birth. The most abundant peripheral nervous\nsystem (PNS) myelin protein, myelin protein zero (MPZ), is largely responsible for compaction of the\nPNS myelin sheath. Charcot-Marie-Tooth Type 1B and Dejerine-Sottas syndromes patients, with\nmutations in MPZ, frequently suffer from late-onset SNHL, similar to that observed in HCMV\ncongenitally-infected children. MPZ expression is dramatically decreased in congenital HCMV-infected\ntissue samples. Schwarm cells (SCs) are the only cells in the body that produce MPZ. HCMV infection of\nSCs, or sole expression of the HCMV tegument protein pp71 in culture, causes large decreases in MPZ\nmRNA levels. SCs express MPZ protein only when directly contacting the neurons they sheathe, making a\ntractable co-culture system essential to studying defects in myelination. Substantial literature describes\nrat SC/neuron co-culture; however, very little work has reported using only human cells, essential for the\nstudy of species-restricted Human CMV pathogenesis. We have developed an all-human threedimensional\n(3D) SC/neuron co-culture system, amenable to the study of HCMV interactions. Our\npreliminary experiments have produced robust neurite outgrowth, SC/neuron interactions, MPZ\nexpression and myelination. Initial experiments with pp71-expressing SCs produced very different\ninteractions between the cell types and no evidence of myelination. In this application, we propose three\nAIMS. AIM 1 will fully characterize the co-culture system, establishing the baseline parameters of\noutgrowth and myelination, additionally assessing the functionality of the system using nerve conduction\nvelocity studies, over a 30-day timecourse using wildtype SCs. After defining the co-culture system's\nbaseline parameters, AIM 2 will assess the ramifications of HCMV infection and pp71 expression on all\nparameters defined in AIM 1. AIM 3 will utilize the co-culture system to examine crosstalk between the\nextracellular matrix (ECM) and myelin production, MPZ in particular, since the literature suggests a\ncritical link between the ECM and SCs' ability to properly myelinate neurons. We believe this 3D system\nwill enable us to accurately assess the effects ofHCMV infection on the developing PNS. Moreover, we\nbelieve our new system has the potential to be utilized by the wider scientific community studying\ninteractions between glia and neurons and associated defects in myelination with an eye on its utilization\nas an efficient platform for drug discovery and development.","project_type":"Grant","lead":"Lee Fortunato","affiliation":"COS Biological Sciences","funder":"National Institutes of Health","award_number":"R01AI139503","date":"2023","end_year":"2029","status":"Active","subject":["human cytomegalovirus","myelin protein zero","schwann cells","sensorineural hearing loss","peripheral nervous system","myelination","nidogen 1"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/10882644","funder_agency":"National Institutes of Health","research_area":"Health & disease"},{"objectid":"ai4ui_historical-contracts","title":"Historical Contracts","description":"Extraction effort over the university's legacy contract pool (~1,400 documents): pull the fields the State of Idaho's Transparency Database requires and produce a clean upload for the state portal. The SIGGY contracts database serves as ground truth for validating extracted data. Approved and scoped; extraction begins once the same tooling proves itself on the smaller ongoing-contracts stream.","significance":"Turns days per contract into minutes per contract across a 1,400-document backlog — an estimated 5.2 FTE of one-time effort avoided, while bringing UI into compliance with state transparency requirements.","status":"Exploring","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"udibr_tonina_formation_lemhi","title":"Ice Formation Lemhi","gist":"Investigating frazil ice formation and transport in the Lower Lemhi River using numerical simulations and field data.","description":"This project investigates the formation and transport of ice in mountain streams, specifically focusing on frazil ice accumulation in the Lower Lemhi River in Idaho. By combining numerical simulations with field data and statistical analysis, the research examines the hydromorphological and meteorological conditions that drive these processes. The work addresses critical implications for river morphology, flooding risks, infrastructure safety, and aquatic habitat preservation within a multi-agency collaboration.","abstract":"We are looking for 1 energetic and dynamic PhD student interested in investigating the formation and transport of ice in mountain streams starting on January 2025. Ice formation has important implications for river morphology, flooding, safety, infrastructure damage and aquatic habitat. The candidate will join an active, dynamic, multi-agency team which include the University of Idaho, of Saskatchewan, Southern Illinois University and Reclamation. The successful candidate will study the hydromorphological and meteorological conditions that are conducive to the formation and accumulation of frazil ice in the Lower Lemhi river (Idaho) with a set of numerical simulations supported by field data and statistical analysis. The position will be based in Boise at the Center for Ecohydraulics Research and expected starting date at the beginning of January.","project_type":"Other","lead":"Daniele Tonina","affiliation":"COE Ctr for Ecohydraulics Research","funder":"US Department of Interior-Bureau of Reclamation","date":"2024","status":"Active","subject":["frazil ice","ice formation","river morphology","mountain streams","hydromorphology","flood risk","aquatic habitat"],"confidence":"Medium","source_url":"https://web.archive.org/web/20250421164240/https://ecohydraulics.org/3567-2/","research_area":"Water resources"},{"objectid":"hsf_bartholomaus_sheet_model_intercomparison","title":"Ice Sheet Model Intercomparison Project for CMIP7 (ISMIP7)","gist":"ISMIP7 generates consensus sea level rise projections from ice sheet models using CMIP forcing to inform IPCC AR7 and adaptation planning.","description":"The Ice Sheet Model Intercomparison Project for CMIP7 establishes consensus estimates of sea level rise contributions from ice sheet changes across various climate trajectories. It designs and delivers projections using Coupled Model Intercomparison Project forcing through large-scale community intercomparisons between standalone ice sheet models and coupled Earth system models. This work specifically targets the needs of the Seventh Assessment Report of the Intergovernmental Panel on Climate Change and provides critical data to practitioner communities focused on sea level rise impacts and adaptation.","abstract":"The mission of ISMIP7 is to establish consensus estimates of the sea level rise contribution from ice sheet change over the coming decades and centuries, given different trajectories for Earth's climate.\n\nISMIP7’s core activity is the design and delivery of projections of the sea level contribution of the ice sheets using Coupled Model Intercomparison Project (CMIP) forcing. These projections are based on large-scale community intercomparisons among standalone ice sheets models and coupled Earth system models. This core activity is distinct from the wider ambitions of the ice sheet science community, for instance activities whose sole aims may be to improve individual ice sheet models, conduct research that relies on a limited number of models, or are designed primarily for better glaciological understanding alone.\n\nISMIP7 activities are designed for completion in time to inform the Seventh Assessment Report of the Intergovernmental Panel on Climate Change (IPCC AR7). ISMIP7 additionally provides information to practitioner communities working on the impacts of and adaptation to sea level rise.","project_type":"Grant","lead":"Timothy Bartholomaus","affiliation":"COS Earth and Spatial Sciences","funder":"Heising-Simons Foundation","date":"2025","status":"Active","subject":["ice sheet models","sea level rise","climate projections","earth system models","model intercomparison","glaciology","climate change"],"confidence":"High","source_url":"https://www.ismip.org/","project_url":"https://github.com/ismip","funder_agency":"Private foundation","research_area":"Climate"},{"objectid":"nih_bohach_inbre_establishing_developmentally","title":"Idaho INBRE: Establishing a developmentally inspired biomaterial platform to direct stem cell tenogenesis","gist":"Developing zwitterionic polyampholyte hydrogels to direct mesenchymal stem cell tenogenesis using developmental biochemical and mechanical cues.","description":"This project establishes a developmentally inspired biomaterial platform using zwitterionic cross-linked polyampholyte hydrogels to direct mesenchymal stem cell tenogenesis. By leveraging embryonic and postnatal tendon development data, the team designs hydrogels that deliver specific biochemical signals from cell-cell junction and extracellular matrix proteins while matching the mechanical properties of developing tendon tissue. The research addresses the clinical need for regenerative therapies for tendon injuries by determining how combined biochemical and mechanical factors regulate stem cell differentiation into functional tendon cells.","abstract":"PROJECT SUMMARY\nThis Idaho INBRE team science administrative supplement titled, “Establishing a developmentally inspired\nbiomaterial platform to direct stem cell tenogenesis” fits the Idaho INBRE-4 parent grant scientific theme of\nCell Signaling. Tendons are strong, collagenous musculoskeletal tissues that transfer mechanical forces from\nmuscle to bone. There is a clinical need for novel regenerative therapies to treat tendon injuries as healing is\nlimited and injuries are associated with long-term loss of function. Three interdisciplinary investigators will work\nas a team to leverage their individual expertise to design a biomaterial polymer platform to control tenogenesis.\nOur team includes experts in the areas of tendon development and mesenchymal stem cell (MSC)\ndifferentiation (Dr. Schiele – Biomedical Engineering), polymeric hydrogels and biomaterials (Dr. Bernards –\nChemical Engineering), and peptide synthesis and organic chemistry (Dr. Waynant – Chemistry). There is a\nlimited understanding of the biochemical and mechanical factors that regulate tenogenesis. Normal embryonic\nand postnatal tendon development will inform our tenogenic strategy. By leveraging the strengths of the team,\nwe will advance a novel hydrogel platform and knowledge of tenogenic regulators. We will determine the\ncombination of developmentally identified biochemical and mechanical factors that regulate tenogenesis and\ndeliver those factors with a novel biomaterial platform. We hypothesize that developmental factors can be\nrationally designed into a new class of zwitterionic cross-linked polyampholyte hydrogels to direct MSC into\nfunctional tendon cells. The project has two specific aims. Specific Aim 1 develops our team and defines the\nroles that peptides mimicking the developmentally identified cell-cell junction proteins (cadherin-11 and N-\ncadherin) and extracellular matrix proteins (fibronection and collagen) have on the induction of stem cell\ntenogenesis. These signals will be delivered from polyampholyte hydrogels synthesized with novel zwitterionic\ncross-linkers, which are designed to control the presentation of the desired cell signaling peptides. Specific Aim\n2 expands this family of zwitterionic cross-linkers to finetune the mechanical properties of the polyampholyte\nhydrogels to match specific stages of tendon development. This will determine how the tissue elastic modulus\nand biochemical signaling together control tenogenesis. To meet Idaho INBRE goals, this team science project\nalso provides opportunities for undergraduate and graduate students to design and test this biomaterial\nplatform, which further enhances the pipeline of well-trained biomedical researchers. The combined results\nfrom this team effort will be a family of tunable zwitterionic cross-linker species that are incorporated into\npolyampholyte hydrogels designed to deliver biochemical and mechanical developmental factors that regulate\ntenogenesis. We anticipate this will represent a significant breakthrough in modeling and understanding tendon\ndevelopment to guide effective regeneration strategies. These results will be the preliminary data for a\ncollaborative NIH funding application.","project_type":"Grant","lead":"Carolyn Bohach","affiliation":"COS INBRE","funder":"National Institutes of Health","award_number":"P20GM103408-23S9","date":"2024","end_year":"2025","status":"Active","subject":["tendon regeneration","stem cell differentiation","biomaterials","hydrogels","tenogenesis","mesenchymal stem cells","tissue engineering"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/11044547","project_url":"https://www.uidaho.edu/newsroom/tendon-research","funder_agency":"National Institutes of Health","research_area":"Health & disease"},{"objectid":"nih_vanleuven_identifying_phage_bacteria","title":"Identifying phage-bacteria interactions using a multispecies model","gist":"A study of phage-bacteria interaction dynamics and resistance evolution in the honey bee gut using modeling and multispecies culturing.","description":"This project investigates how ecological and evolutionary forces shape animal microbiomes by studying phage-bacteria interactions within the honey bee gut. Using an integrative approach combining mathematical modeling, laboratory culturing, and in vivo testing, researchers examine how growth conditions and multispecies bacterial interactions influence the tempo of phage resistance evolution. The work addresses critical gaps in understanding the stability and function of microbial communities that are integral to animal health and development.","abstract":"The microbial communities colonizing animals are integral to animal health and development but details \nabout what make these communities functional and stable are lacking. Bacteriophages (viruses that infect \nbacteria) are the numerically dominant members of animal microbiomes and they influence many \nproperties of these communities. Bacteriophages regulate bacterial community composition by predation, \ntransfer genetic material between host genomes, and beneficially stimulate the immune system of animals. \nHowever, our knowledge of bacteriophages is largely restricted to a limited set of lab-adapted strains and \nthus our understanding of their role in animal microbiomes is lacking. Bacteriophages may influence \ndisease through ecological processes by regulating bacterial community composition and abundance or by promoting changes in the virulence of their bacterial hosts. \nThe factors causing microbial composition to change over time are often hard to determine and empirically test because most animal microbiomes are complex and experimental intractable. We propose to utilize an important animal model system, the honey bee (Apis mellifera), to determine how ecological and evolutionary forces shape animal microbiomes. To this end, we outline two Aims that will help us \ncharacterize these forces. \nAim 1: Determine how phage resistance evolution is dependent on microbial growth conditions. In this aim \nwe will comprehensively test different parameters of growth than are likely to influence how quickly \nbacteria evolve resistance against bacteriophage infections. We will carefully measure the tempo of \nchange in sets of bacteria and phages growing together. We anticipate identifying how these dynamics are impacted by growth conditions. \nAim 2: Measure the impact of microbial interactions on phage resistance evolution dynamics. In this aim \nwe expand our research to include interacting bacterial species. In most natural conditions that microbes \nlive in they will encounter other bacteria. These interactions likely alter how bacteria respond to and evolveresistance against the bacteriophages that infect them. Our experiments will address this by co-culturing bacteria and again measuring the tempo of evolution in these systems. \nIn both aims we adopt an integrative approach that utilizes mathematic modeling, culturing of bacteria and phages in the lab, and testing their growth in the honey bee gut. In doing so, we benefit from the strengths of each approach and increase the rigor of our results.","project_type":"Grant","lead":"James VanLeuven","affiliation":"RCI IMCI","partners":"National Institutes of Health","funder":"Center for Modeling Complex Interactions","award_number":"P20GM104420","date":"2023","end_year":"2025","status":"Active","subject":["bacteriophages","microbiome","honey bee","phage resistance","bacterial evolution","microbial ecology","host-microbe interactions"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/10796330","funder_agency":"National Institutes of Health","research_area":"Genomics & molecular biology"},{"objectid":"usda_brooks_post_fire_watershed","title":"Improving Post-fire Watershed Response Predictions","gist":"Research on wildfire impacts on soil properties and watershed recovery using WEPPcloud modeling and field experiments.","description":"University of Idaho research investigates how high-severity wildfires and low-severity prescribed burns alter soil biophysical, hydraulic, and chemical properties, while tracking subsequent watershed recovery. Field burn experiments and soil characterization data parameterize and test WEPPcloud, a geospatial modeling platform designed to simulate post-fire runoff and erosion. The project culminates in the development of geospatial decision support tools for pre-fire and post-fire watershed management through collaboration with federal partners.","project_type":"Cooperative Agreement","lead":"Erin Brooks","affiliation":"CALS Soils and Water Systems","funder":"USDA Forest Service","date":"2025","status":"Active","subject":["wildfire","prescribed burn","soil properties","watershed recovery","erosion","runoff","geospatial modeling"],"confidence":"Medium","source_url":"https://wepp.cloud/weppcloud/","project_url":"https://wepp.cloud/weppcloud/","funder_agency":"USDA","research_area":"Fire science"},{"objectid":"nih_bohach_inbre_team_science","title":"INBRE Team Science NOSI: Dynamic Cellular Events in Assembling the Vertebrate Eye","gist":"Live imaging of zebrafish embryos creates dynamic atlases and analysis tools for vertebrate eye development.","description":"This project investigates the spatiotemporal dynamics of relationships among neuronal progenitors, neurons, glia, and non-nervous system cell types during vertebrate eye development. Using live confocal imaging of developing zebrafish embryos and novel image analysis methods, the team generates reference static and dynamic atlases of retinal development. These resources, including interactive tools for systematic and quantitative comparison of eye phenotypes, are made publicly accessible to address a key knowledge gap in developmental biology and strengthen biomedical research capacity in Idaho.","abstract":"PROJECT SUMMARY\nThe goal of the Idaho INBRE-4 Program is to continue to augment and strengthen Idaho's capacity to perform\nand sustain biomedical research. This Team Science Supplement, Dynamic Cellular Events in Assembling the\nVertebrate Eye, will advance this goal by bringing together three University of Idaho (UI) investigators with\ncomplementary expertise in developmental neurobiology, immunology/glial biology/imaging, and image\nanalysis/computer vision to address a key knowledge gap in biomedical science. Project co-directors will focus\non the development of the vertebrate eye, and therefore will be directly in alignment with the Cell Signaling\nscientific theme of the Idaho INBRE-4 Program, as this organ carries out numerous developmental and functional\nsignaling activities. This Supplement project will pursue the spatiotemporal dynamics of relationships among\nneuronal progenitors, neurons, glia, and non-nervous system cell types using live confocal imaging of developing\nzebrafish embryos, and novel means of image/video analysis. The project will generate reference static and\ndynamic atlases of vertebrate eye development over the time of retinal development/differentiation and create\nimage and video analysis tools for the vision science community for systematic and quantitative comparison of\neye phenotypes. These resources will be made publicly accessible and interactive and will utilize the INBRE Data\nScience Core facility at the UI. This Core and its infrastructure were or are supported by IDeA (COBRE and\nINBRE) awards and institutionally by the UI. The three project co-directors, DL Stenkamp, DM Mitchell, and L\nNguyen all have strong research records and have mentored numerous trainees. This Supplement furthers their\nteam approach and will provide preliminary data for future collaborative studies and competitive grant proposals,\ncomplying with the goal of this funding Supplement. This team science approach will benefit each investigator\nthrough their collective effort and bring new perspectives to address this key knowledge gap in developmental\nbiology. The project research questions do not duplicate those currently being pursued by the parent Idaho\nINBRE-4 Program award. This Team Science Supplement to INBRE-4 encourages competitiveness that will\ncontinue to have an enduring impact on biomedical research and training in Idaho.","project_type":"Grant","lead":"Carolyn Bohach","affiliation":"COS INBRE","funder":"National Institutes of Health","award_number":"P20GM103408-23S4","date":"2023","end_year":"2025","status":"Active","subject":["zebrafish","eye development","retinal development","live imaging","cellular dynamics","developmental neurobiology","image analysis"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/10851286","funder_agency":"National Institutes of Health","research_area":"Genomics & molecular biology"},{"objectid":"doe_robison_incoming_joint_appointment","title":"Incoming Joint Appointment for Falcon HPC Administrator from University of Idaho","gist":"Falcon is a petascale SGI ICE X supercomputer owned by Idaho National Laboratory and managed by an Idaho university consortium to provide free high-performance computing access to researchers.","description":"Falcon is an SGI ICE X high-performance supercomputer owned by Idaho National Laboratory and operated by a consortium of Idaho research universities, including the University of Idaho, Boise State University, and Idaho State University. Ranked 97th on the Top500 list upon its 2014 operationalization and significantly upgraded in 2017, the system delivers over 1 PetaFLOPS of compute capacity across approximately 932 nodes with 33,552 cores. Located in the INL Collaborative Computing Center, Falcon provides free access to faculty, staff, and students from the three universities via the Idaho Regional Optical Network, representing a major expansion of high-performance computing resources for Idaho researchers.","project_type":"Grant","lead":"Barrie Robison","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","partners":"U.S. Department of Energy","funder":"Battelle-INL- Idaho National Laboratory","date":"2025","status":"Active","subject":["high-performance computing","supercomputing","data science","parallel computing","computational infrastructure","cluster computing"],"confidence":"High","source_url":"https://www.c3plus3.org/falcon-metadata/","project_url":"https://www.c3plus3.org/falcon-metadata/","funder_agency":"Idaho National Laboratory","research_area":"Data science & computing"},{"objectid":"usda_hatzenbuehler_integrated_pest_management","title":"Integrated Pest Management for Cereal Aphid and Barley Yellow Dwarf Control in the Eastern and Southeastern USA","gist":"Updating integrated pest management strategies for barley yellow dwarf virus and cereal aphids in southeastern US winter wheat.","description":"This project addresses the threat of barley yellow dwarf virus to winter wheat in the southeastern United States by updating outdated integrated pest management strategies. Current recommendations rely on data from over twenty years ago that no longer align with modern climate patterns or best practices. The initiative generates research-based support to prevent unnecessary insecticide applications and develops educational materials alongside a revenue calculator to assist producers in making informed decisions.","abstract":"Barley yellow dwarf virus is transmitted by several species of cereal aphids and has been a threat to winter wheat in the southeastern USA in recent years. Integrated pest management (IPM) is the most effective approach to managing BYDV and aphids. However, the recommended strategies in the southeastern USA (i.e., planting date, seed treatment, and/or timing of foliar insecticide application) are based on information generated more than two decades ago, which no longer fit to our current climate patterns or best management practices. This proposal aims to provide research-based support for the effective management of BYDV and cereal aphids in winter wheat in the southeastern United States and develop much-needed, up-to-date educational material to prevent the unnecessary application of insecticides and promote the implementation of IPM. We will also provide estimates of expected revenue associated with implementing each practice and develop a calculator and educational material to assist producers with the decision-making process.","project_type":"Subaward","lead":"Patrick Hatzenbuehler","affiliation":"CALS Ag Econ Rural Sociology","partners":"National Institute of Food and Agriculture/USDA","funder":"Virginia Tech","award_number":"2024-68008-42760","date":"2024","status":"Active","subject":["barley yellow dwarf virus","cereal aphids","winter wheat","integrated pest management","southeastern usa","insecticide resistance","crop protection"],"confidence":"High","source_url":"https://portal.nifa.usda.gov/enterprise-search/projects/1032280","project_url":"https://news.vt.edu/articles/2024/09/USDA-grant-barley-yellow-dwarf-virus.html","funder_agency":"University partner","research_area":"Agriculture"},{"objectid":"usda_kaiser_integrated_predictive_water","title":"Integrated predictive water quantity and quality models to support healthy agroecosystems and water resource management","gist":"Develops predictive water quantity and quality models for the Silver Creek watershed to support trout fishery health and agricultural water management.","description":"This project investigates connections between water quantity and quality within the Silver Creek watershed, an area characterized by significant agricultural usage and a valuable trout fishery. Researchers will improve existing predictive water quantity models and develop a combined model to elucidate stream health implications, utilizing pre-existing data to examine empirical relationships between water volume, stream temperature, and dissolved oxygen. The initiative delivers open-source code and an online interface for interactive modeling tools, providing a reproducible mechanism to support data-informed regional management and facilitate discussion among resource managers and stakeholders.","abstract":"We will investigate connections between water quantity and quality in the Silver Creek watershed, which hosts substantial agricultural usage and a highly valuable trout fishery. Specifically, we propose to improve a predictive water quantity model and develop a combined model that elucidates the stream health implications of predicted water quantity dynamics. Pre-existing data sources will support the examination of empirical relationships between water quantity, stream temperature, and dissolved oxygen. Open-source code for data visualization and interactive modeling tools provide a reproducible mechanism to increase data-informed management regionally. We will develop an online interface for the suite of predictive modelling tools to inform and facilitate discussion among resource managers and stakeholders to improve the health of this agroecosystem. This project meets the Water Quantity and Quality Program Area Priorities by creating innovative modeling tools for irrigators and water resources managers to gain a deeper understanding of physical and biogeochemical fluxes from agroecosystems and their impact on natural resources and environment. This is the first step in meeting our long-term goal of evaluating how adaptive management of agroecosystems may conserve water and improve water quality.","project_type":"Grant","lead":"Kendra Kaiser","affiliation":"UOFNI Water/Energy Resource ResInst","funder":"National Institute of Food and Agriculture/USDA","award_number":"2022-67020-44948","date":"2026","status":"Active","subject":["water quality","water quantity","agroecosystems","stream temperature","dissolved oxygen","predictive modeling","silver creek"],"confidence":"High","source_url":"https://portal.nifa.usda.gov/enterprise-search/projects/1033881","project_url":"https://github.com/kendrakaiser/WRWC","funder_agency":"USDA","research_area":"Water resources"},{"objectid":"ai4ui_invoice-processing","title":"Invoice Processing","description":"Automates the front of the AP invoice pipeline: emailed invoices are captured, invoices without a PO number are auto-rejected back to the submitter, and the rest have key fields extracted (PO number, dates, invoice number, amount, remit-to address) and compared against PO data in Banner. AP staff work a review queue in a dashboard — correcting low-confidence extractions, requesting fixes from submitters, and marking invoices processed. User testing with Accounts Payable resumed in July 2026.","significance":"Cuts manual capture and re-keying on a daily, continuous workload (20,000+ invoice entries since 2022). Estimated 0.7 FTE of AP capacity returned by automating rejections and extraction.","status":"Building","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_ir-reporting-modernization","title":"IR Reporting Modernization (SAS Replacement)","description":"OIT is replacing SAS, the platform behind Institutional Research's reporting dashboards, with modern reporting tooling. Retiring the SAS contract is projected to save $80,000–$100,000 annually (per OIT, July 2026; recorded conservatively at the low end). Tracked here as part of the AI projects inventory; detail will be added as OIT shares scope and timeline.","significance":"Retires the SAS contract — $80,000–$100,000 per year in hard-dollar savings — and moves institutional reporting onto supported tooling.","status":"Tracked","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nasa_werneck_gravitational_wave_signatures","title":"LPS: Gravitational-Wave Signatures of Massive Black Hole Formation","gist":"Simulating direct-collapse black hole formation and mergers to predict gravitational-wave signatures for the Laser Interferometer Space Antenna.","description":"This project simulates the formation, collapse, and merger of direct-collapse black holes (DCBHs) to extract their resulting gravitational-wave signals and assess their detectability by the Laser Interferometer Space Antenna (LISA). Using cosmological simulation data from the Enzo code, the research identifies likely DCBH regions and applies Newtonian methods followed by fully dynamical general relativistic hydrodynamics to model strong-field collapse and binary mergers. By investigating this poorly understood source class, the work prepares for the analysis of the LISA data stream and deepens understanding of the early gravitational Universe.","abstract":"Direct-collapse black holes (DCBHs) are an important component of the massive black hole population of the early universe, and their formation and early mergers will be prominent in the data stream of the Laser Interferometer Space Antenna (LISA). However, the population and binary properties of these early black holes are poorly understood, with masses, mass ratios, spins, and orbital eccentricities strongly dependent on the details of their formation, and the properties of the remaining exterior material (baryonic and non-baryonic), which may be substantial to the point of merger.\n\nWe propose to simulate the formation, collapse, and/or merger of such DCBH regions in order to extract the resulting gravitational-wave signals, and to assess the ability of LISA to detect and identify them.\n\nOur approach for this work will involve cosmological simulation data produced with the Enzo code. We will identify regions of likely DCBH formation in this data, and use Newtonian methods to follow these regions to the point of strong-field collapse. We will then employ fully dynamical general relativistic hydrodynamics (GRHD) to simulate the collapse of these DCBHs, and the merger of any resulting DCBH binaries, using standard techniques to extract the resulting gravitational radiation, and assess its observational potential for LISA.\n\nThis work will help prepare for the overall analysis and interpretation of the LISA data stream by investigating a less-understood LISA source class, and help deepen our understanding of the early gravitational Universe.","project_type":"Grant","lead":"Leo Rosa Werneck","affiliation":"COS Physics","partners":"National Aeronautic Space Ad.","funder":"University of Maryland Baltimore County","award_number":"80NSSC24K0360","date":"2023","status":"Active","subject":["direct-collapse black holes","gravitational waves","lisa","general relativistic hydrodynamics","cosmological simulations","massive black holes","early universe"],"confidence":"High","source_url":"https://lisa.nasa.gov/LPSprogram.html","funder_agency":"University partner","research_area":"Physics & astronomy"},{"objectid":"nsf_parent_species_diversification_community","title":"MCA: Species Diversification and Community Assembly in Andean Land Snails","gist":"Analyzing Andean land snail mucus chemistry to explain species diversification and community assembly in the Peruvian Andes.","description":"This research investigates chemical communication mediated by snail mucus among land snail communities in the Peruvian Andes to understand species interactions and community assembly. By integrating chemical ecology, phylogenetics, and morphometrics, the project quantifies chemical, morphological, and genetic variation to reveal how mucus traits influence species recognition, coexistence, and diversification. The study addresses a critical gap in knowledge regarding the chemical basis of biodiversity in this hotspot, offering insights into ecological adaptation and community stability. Additionally, the project supports educational workshops for undergraduates and early graduate students in the USA and Peru to foster research skills and international collaboration.","abstract":"This research explores the world of chemical communication among land snails forming communities in the Peruvian Andes, an area particularly rich in biodiversity. Chemical interactions, such as those mediated by snail mucus, are crucial yet understudied components of community assembly and biodiversity. By focusing on the chemical properties of snail mucus, the project aims to uncover how these traits related to communication between organisms influence species interactions, which in turn are shaping the assembly of biological communities. This study is addressing an important gap in knowledge by merging the fields of chemical ecology and evolutionary biology to better understand how species interact and coexist at a local scale. Understanding species interactions is crucial for biodiversity conservation, as it can reveal how species adapt to their environments and maintain stable communities, especially in the face of environmental changes. The project will support educational workshops for undergraduates and early graduate students in the USA and Peru, emphasizing research skills and leadership, particularly for participants from underrepresented groups, thereby fostering a diverse scientific community and international collaborations.\n\nThis project integrates chemical ecology, phylogenetics, and morphometrics to quantify chemical (mucus), morphological (shell), and genetic (DNA) variation in Andean land snails and how this variation contributes to community assembly and species diversification. In particular, using mass spectrometry and proteomics, the research will identify and quantify mucus components across different snail species. Phylogenetic analyses will be conducted to understand the evolutionary relationships among these species, while morphometric techniques will assess shell characteristics. Together, these approaches aim to test hypotheses regarding the role of mucus in species recognition and community dynamics, providing insights into the mechanisms of species coexistence, competition, and ecological adaptation. By combining these interdisciplinary approaches, the research seeks to advance our understanding of the chemical basis of species interactions and its impact on community structure and evolution. Ultimately the research will provide insights into the mechanisms driving community dynamics and species diversification in this biodiversity hotspot, and serve as a model to understand these processes in other systems. \n\nThe award is co-funded by the Population and Community Ecology program.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Christine Parent","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2423020","date":"2024","end_year":"2027","status":"Active","subject":["land snails","chemical ecology","community assembly","species diversification","mucus","andes","proteomics"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2423020","funder_agency":"National Science Foundation","research_area":"Ecology & wildlife"},{"objectid":"nsf_mittelstaedt_merging_particle_physics","title":"Merging Particle Physics and Earth Science to develop a new tool to constrain the physical and chemical properties of LLSVPs","gist":"Develops a multi-detector neutrino tomography framework to constrain the composition and density of Large Low Velocity Provinces in Earth's lower mantle.","description":"This project develops a new multi-detector framework for Neutrino Oscillation Tomography of the Earth (NOTE) to directly measure the composition and density of Large Low Velocity Provinces (LLVPs) in Earth's lowermost mantle. By integrating data from multiple neutrino detectors and combining them with existing geophysical constraints, the research creates a unified method to estimate LLVP properties that current seismic mapping cannot determine. These measurements are critical for understanding how LLVPs influence deep-Earth dynamics, mantle circulation, and the planet's magnetic field. The work modifies the EarthProbe code to handle multi-detector inputs and conducts sensitivity tests to demonstrate that robust density and composition determinations are achievable within a decade.","abstract":"Seismic mapping of Earth’s lowermost mantle reveals the presence of at least two continent-sized structures located just above the outer-core within the mantle. Due to these structures slow seismic wave speeds, they are commonly referred to as Large Low Velocity Provinces (LLVPs). LLVPs potentially influence deep-Earth dynamics, alter lower mantle circulation, decrease core heat flow, and consequently modify the planet’s magnetic field. The extent of these potential impacts depends on LLVP material properties, including their composition and density, among others. However, current geophysical methods do not directly measure composition and density. To address this, this project will leverage low-mass, elementary particles called neutrinos that have direct sensitivity to the composition and density of matter using a technique known as Neutrino Oscillation Tomography of the Earth (NOTE). The NOTE method can infer properties of the lower mantle by analyzing the characteristics of Earth-crossing neutrinos arriving at a detector (e.g., angles of arrival, energies, and neutrino types). To enhance the sensitivity of NOTE and complement existing geophysical methods, the researchers will create a new NOTE framework capable of integrating data from multiple neutrino detectors into a single analysis, providing new, independent estimates of the composition and density of LLVP. With several neutrino detectors online or in development, this project will develop tools to harness their collective capabilities, while also leveraging existing geophysical data toward new breakthroughs in understanding our planet. The goal is to build the tools necessary to demonstrate that with the use of multiple detectors, NOTE can provide a robust determination of LLSVP density and composition within a decade. This project will establish and strengthen international collaboration, while providing and training and mentoring for students, and facilitating outreach opportunities.\n\nThe composition and density of an LLVP impact its viscosity and relative buoyancy, thereby governing its dynamic behavior and lifetime in the mantle. By developing a new tool to constrain the density and composition of LLVPs, this project will open new approaches for exploring the Earth’s deep interior. The researchers will create a novel multi-detector framework for NOTE and integrate it with existing geophysical constraints, yielding a unified method for estimating LLSVP properties. The project has three primary objectives: 1) incorporate multiple detectors into the NOTE code EarthProbe, 2) systematically assess the sensitivity of multi-detector NOTE to LLVP properties, and 3) integrate geophysical constraints into the proposed framework to improve data statistics and decrease required data collection times. To achieve Objective 1, the project team will modify the EarthProbe code and data structures to account for neutrinos arriving at multiple detectors, as well as the covariance matrix used by existing minimization algorithms to yield estimates of LLVP properties. Objective 2 will be accomplished through a series of systematic sensitivity tests of the new multi-detector framework across a range of anomalous LLSVP densities and compositional contrasts. Finally, for Objective 3, the team will incorporate existing geophysical estimates of either composition or density to quantify any reduction in data collection period required for NOTE analysis. This project will establish and strengthen international collaboration with a PhD student at the center, while providing and training and mentoring for students, and facilitate outreach opportunities. This project is jointly funded by Cooperative Studies for the Earth’s Deep Interior (CSEDI) and the Established Program to Stimulate Competitive Research (EPSCoR).\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Eric Mittelstaedt","affiliation":"COS Earth and Spatial Sciences","funder":"National Science Foundation","award_number":"2406115","date":"2024","end_year":"2027","status":"Active","subject":["large low velocity provinces","neutrino oscillation tomography","earth's mantle","neutrino detectors","geophysics","particle physics","deep earth dynamics"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2406115","funder_agency":"National Science Foundation","research_area":"Physics & astronomy"},{"objectid":"brightfocus_farre_microglial_regulation_restor","title":"Microglial Regulation of Developing and Restored Cone Visual Circuits","gist":"Research on how retinal microglia facilitate synaptic rewiring of regenerated photoreceptors to improve age-related macular degeneration treatments.","description":"This project investigates how retinal microglia contribute to the development and regeneration of functional synaptic connections in the eye. By observing live cell-cell interactions in zebrafish larval retinas, the research examines how immune cells help new photoreceptors establish connections with other neurons after damage. These findings aim to identify specific microglial functions necessary to support photoreceptor-replacement treatments for age-related macular degeneration, ensuring optimal integration of new cells into diseased retinas.","abstract":"Goals\n\nWith this project, I aim to determine whether and how retinal microglia contribute to the development and regeneration of functional synaptic connections in the retina.\n\nSummary\n\nIn late stages of age-related macular degeneration (AMD), light sensing cells (photoreceptors) in the eye die, leading to vision loss. To treat this with future approaches, we can potentially replace photoreceptors, but in order to work properly, these cells need to be able to communicate with other neurons in the eye that process light information and pass it to the brain. With this project, we will determine how microglia (immune cells of the eye) could help new photoreceptors establish connections with other neurons, potentially making future AMD treatments more effective.\n\nUnique and Innovative\n\nThere are two particularly unique aspects to this proposal. First, we will be able to observe live cell-cell interactions between neurons and microglia in living zebrafish larval retinas in the context of neuronal activity. Second, exploiting the endogenous regenerative capacity of the zebrafish retina, we will study the potential roles microglia play in synaptic rewiring of regenerated photoreceptors into existing retinal circuits after retinal damage.\n\nForeseeable Benefits\n\nUnderstanding how microglia assist in the development and regeneration of cone synapses will allow us to best support photoreceptor-replacement treatments for age-related macular degeneration by helping us identify microglial functions that must be preserved, directed, or mitigated to ensure the optimal integration and function of new photoreceptors in diseased retinas. This work will also reveal novel microglial functions in the retina as well as the mechanisms that underlie these functions.","project_type":"Fellowship","lead":"Ashley Farre","affiliation":"COS Biological Sciences","funder":"BrightFocus Foundation, Inc.","date":"2025","status":"Active","subject":["microglia","retina","synaptic regeneration","cone photoreceptors","age-related macular degeneration","zebrafish","neural circuits"],"confidence":"High","source_url":"https://www.brightfocus.org/grant/microglial-regulation-of-developing-and-restored-cone-visual-circuits/","project_url":"https://www.mitchelllabuofi.com/","funder_agency":"Private foundation","research_area":"Health & disease"},{"objectid":"ai4ui_mindrouter","title":"MindRouter","description":"LLM inference load balancer fronting a heterogeneous Ollama + vLLM cluster. Provides unified OpenAI-, Ollama-, and Anthropic-compatible endpoints with fair-share scheduling, quotas, telemetry, Azure AD SSO, and full audit logging. Open-sourced at mindrouter.ai and deployed at UI.","significance":"Enables every downstream AI app at UI. Keeps data on-prem for compliance. Avoids per-seat vendor lock-in. Institutional audit trail. Fair access across research and operations workloads.","status":"Live","subject":["artificial intelligence"],"confidence":"High","source_url":"https://mindrouter.uidaho.edu","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_mindrouter-video-storyboard","title":"MindRouter Video Storyboard","description":"Video previsualization workflow requested by University Communications and Marketing to mock up an advertisement before filming. IIDS added a model-agnostic video-generation endpoint to MindRouter, currently backed by the open-weight LTX-Video 2.3 model on a dedicated NVIDIA H200, with integrated voice support. The standalone storyboard web application generates clips from text prompts, generated images, or uploaded keyframes; refines prompts with an AI function that considers the chosen keyframes; arranges clips on a storyboard with an app-aware AI chatbot guide; and stitches them into a draft video that can be exported and downloaded. Delivered to Melissa Hartley's team in July 2026; first production use is a 30-second UCM advertisement, for which Hartley produced two AI mockup proofs cut to music and voice-over in Premiere. Her first measured comparison (2026-08-06; one project, so directional): storyboard build 1.5 hours per AI mockup versus 3 hours for one static board, and first-cut editing 2 hours of timeline assembly plus a projected 4–6 hours fitting filmed content into the pre-timed timeline, versus 10–12 hours in the typical process — with the AI pre-draft expected to eliminate the first of three review/approval rounds. Fuller numbers are due after the first project completes filming and editing (early September 2026). CETL saw a demo in August 2026 and is likely to adopt the tool in place of the storyboard solution it had planned. Broader release is deliberately gated: UI has no policy for AI-generated media beyond a social-media disclosure request, so IIDS is drafting usage guidelines — surfaced in the application itself — with UCM brand leadership before wider rollout.","significance":"Compresses ad concept development from a filming-first process to rapid visual iteration, gives stakeholders a concrete mockup before production resources are committed, and avoids per-clip commercial generation credits during early creative development. First measured use (one UCM ad, Aug 2026): 50% faster storyboard builds and a first-cut edit dropping from 10–12 hours to roughly 6–8, with the pre-draft expected to remove an entire review/approval round.","status":"Live","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"idhw_seamon_modeling_covid_disease","title":"Modeling COVID-19 Disease Severity","gist":"A multidisciplinary team uses SEIRS and agent-based models to predict rural COVID-19 spread and evaluate interventions for public health officials.","description":"Part of the University of Idaho's Pandemic Modeling Group, this effort combines modelers, mathematicians, and sociologists to predict COVID-19 spread in rural communities. The team utilizes SEIRS and survey-informed agent-based models to evaluate intervention effectiveness and protect vulnerable populations. Their work aims to transparently share findings with the public and assist health officials in pandemic response through updated risk maps and behavioral analysis.","project_type":"Grant","lead":"Erich Seamon","affiliation":"RCI IMCI","partners":"Centers for Disease Control and Prevention","funder":"Idaho Department of Health and Welfare","date":"2023","status":"Active","subject":["covid-19","disease severity","agent-based modeling","seirs models","pandemic response","rural communities","intervention effectiveness"],"confidence":"Medium","source_url":"https://pandemic-modeling.uidaho.edu/","project_url":"https://pandemic-modeling.uidaho.edu/","funder_agency":"State of Idaho","research_area":"Health & disease"},{"objectid":"usda_kimsey_usfs_region_2024","title":"MODIFICATION: USFS Region 6 IFC Research 2024","gist":"The IFC is an applied silviculture research cooperative managing over 500 installations across five western states to support diverse forestry objectives.","description":"Part of the University of Idaho's Intermountain Forest Cooperative (IFC), this effort represents a broader applied forest management research initiative. The cooperative administers, develops, and distributes forest management information derived from over 500 research installations across Idaho, Washington, Oregon, California, and Montana. Committed to supporting federal, state, and private forestry organizations, the IFC specializes in applied silviculture to help members meet their ecological, economic, and regulatory forest management objectives.","project_type":"Contract","lead":"Mark Kimsey","affiliation":"CNR Intermountain Forestry Coop-633 (IFTNC)","funder":"USDA Forest Service","date":"2023","status":"Active","subject":["silviculture","forest management","intermountain west","forest ecology","applied forestry","regional forestry","forest installations"],"confidence":"Medium","source_url":"https://www.intermtnforestcoop.com/","project_url":"https://www.intermtnforestcoop.com/","funder_agency":"USDA","research_area":"Forestry"},{"objectid":"nasa_boschetti_modis_viirs_continuity","title":"MODIS to VIIRS continuity of the Global Wildfire Information System (GWIS) policy-relevant information portal in support of national and sub-national wildfire reporting and decision making.","gist":"GWIS aggregates global fire data to evaluate regimes and support operational management across national and international scales.","description":"Part of the Global Wildfire Information System (GWIS), a joint GEO and Copernicus initiative that aggregates regional and national data to provide a comprehensive global evaluation of fire regimes and effects. The system builds on the European Forest Fire Information System (EFFIS) and GOFC-GOLD activities to offer tools supporting operational wildfire management from national to global scales. This effort complements existing worldwide wildfire information gathering while facilitating collaboration between the EU and Latin American countries to improve fire prevention capacities.","project_type":"Cooperative Agreement","lead":"Luigi Boschetti","affiliation":"CNR Forest, Rangeland & Fire Sci","funder":"National Aeronautic Space Ad.","date":"2024","status":"Active","subject":["wildfire","fire science","remote sensing","fire regimes","satellite imagery","fire management","global monitoring"],"confidence":"Medium","source_url":"https://gwis.jrc.ec.europa.eu/","project_url":"https://gwis.jrc.ec.europa.eu/","funder_agency":"NASA","research_area":"Fire science"},{"objectid":"nsf_nuismer_monitoring_measuring_wild","title":"Monitoring and measuring wild animals without the need for capture","gist":"An AI-powered instrument identifies small mammals and measures traits in real-time without capture, reducing costs and expanding biological research scope.","description":"This project engineers an instrument using artificial intelligence to identify small mammal species, discriminate among individuals, and measure body weight and morphological traits in real-time without capturing animals. By eliminating the need for physical handling, the device reduces research costs and increases the efficiency, pace, and geographic scope of data collection in biological sciences. The system also facilitates research in harsh environments and supports science education through partnerships with K-12 schools and engineering student projects at the University of Idaho.","abstract":"An award is made to the University of Idaho to engineer an instrument that uses advances in artificial intelligence to identify small mammal species, discriminate among individuals, and measure body weight and morphological traits in real-time. Despite their abundance and applied importance as agricultural pests and reservoirs of human infectious disease, the methods used to study small mammals in the wild have changed little over time and generally require that individual animals are captured and handled by well-trained and permitted research staff. By removing this requirement, the instrument developed by this project will reduce research costs and increase the efficiency, pace and extent of data collection in both the pure and applied biological sciences. Beyond advancing research instrumentation, work on this project will enhance science education at the interface of artificial intelligence, engineering, and biology through partnerships with K-12 schools and integration into senior design projects for engineering students at the University of Idaho.\n\nBy enabling automated monitoring of wild animals, the proposed work will enhance biological research capacity in three ways. First, the cost and labor required for data collection will be vastly reduced, increasing sample sizes and the geographic and temporal scope of study. Second, regulatory obstacles and safety concerns to studying threatened or endangered species will be reduced because animals need not be captured and handled. Third, because the instrument is capable of autonomous operation and data transmission for extended periods of time, it will facilitate research in harsh or dangerous environments. Instrument adoption by researchers in the biological sciences will be facilitated by instrument loan to Idaho Department of Fish and Game for use in small mammal surveys and through the donation of ten instruments to a non-profit selected through a merit-based application process.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Scott Nuismer","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2451775","date":"2025","end_year":"2028","status":"Active","subject":["wildlife monitoring","small mammals","computer vision","non-invasive sampling","wildlife ecology","automated identification","morphological traits"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2451775","funder_agency":"National Science Foundation","research_area":"Ecology & wildlife"},{"objectid":"ncasi_poolakkal_ncasi_foundation_2663","title":"NCASI Foundation Project # FO-SFG-2663","gist":"NCASI/CAFS matching award supporting forest small-area estimation.","description":"A University of Idaho award from the NCASI Foundation, led by Jaslam Poolakkal with Mark Kimsey, providing matching support tied to the Center for Advanced Forestry Systems for the University's forest small-area-estimation work. It is a companion to the University's larger NCASI Partnership for Small Area Estimation project.","project_type":"Other","lead":"Jaslam Poolakkal","affiliation":"CNR Idaho Forest Innovations Lab-918 DO NOT USE See RCI 3979/918 FII","funder":"NCASI Foundation","date":"2025","status":"Active","subject":["forestry","sustainable forest management","forest ecology","timber production","forest health","silviculture","biodiversity conservation"],"confidence":"Medium","funder_agency":"Private foundation","research_area":"Forestry","parent_project":"usda_poolakkal_small_area_estimation"},{"objectid":"ai4ui_nexus","title":"Nexus","description":"React + FastAPI application platform running on OIT-managed secure infrastructure, built collaboratively by OIT and IIDS. Nexus is the institutional template where University of Idaho application modules are deployed, providing a shared, audited, and security-hardened runtime for AI-enabled and traditional unit-level apps. Complements TEMPLATE-app: where TEMPLATE-app is the development scaffold, Nexus is the production landing zone. Governed by OIT's Enterprise AI Development Framework (the approved tech stack) and AI-Assisted Builder Guide (the six-stage pathway for teams outside OIT). The Retroactive Payment Requests module is deployed on Nexus and in production use by Payroll; OpenERA and UCM Daily Register are next through the pathway. Nexus continues to receive regular updates; recurring security-review tickets and approval steps on pull requests are the main reported delivery friction.","significance":"Standardizes where institutional application modules live. Shared security posture, audit trail, and operational footprint across UI units. Reduces per-app hosting overhead and fragmentation.","status":"Tracked","subject":["artificial intelligence"],"confidence":"High","source_url":"https://nexus.uidaho.edu","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"usda_kimsey_nrcs_soil_moisture","title":"NRCS Soil Moisture Regime Project - Phase 3","gist":"Monitoring soil moisture and temperature for a decade to validate plant communities as proxies for soil moisture regimes in the Pacific Northwest.","description":"This project quantitatively describes variability in soil physical characteristics within defined control sections relative to specific soil moisture regimes while monitoring soil moisture and temperature for up to ten years. It assesses plant community assemblages to determine their reliability as proxies for soil moisture and temperature regimes, addressing the difficulty of field identification in the western US. The work substantiates relationships between soil moisture regimes and plant communities, particularly for the xeric regime in the Pacific Northwest, to improve understanding of carbon storage, climate change impacts, and agricultural water management.","abstract":"Purpose\n\nThe importance of soil moisture is well known for its impact on stream forecasting, agricultural water supply management, and ecosystem health. But it is also emerging as a critical variable in carbon storage and climate change. When soils are dry, plants do not photosynthesize, which means they stop taking up carbon, increasing CO2 amounts in the atmosphere. The cooling effect of transpiration also ceases. Decreasing soil moisture reduces the capacity of soils to buffer against extreme temperature changes and drought, creating challenges for food production, and ultimately desertification.\n\nSoil Moisture Regimes (SMRs), as identified in Soil Taxonomy, are directly related to plant growth potential and many pedogenic processes. Field identification of SMRs is difficult, particularly in the western US where climate can vary considerably over short distances as a function of landscape position – aspect, elevation, slope gradient. For example, it has long been assumed that potential differences in SMRs between north- and south-facing slopes are reflected in the plant communities. As such, in the absence of soil climate data, plant communities are frequently used as proxies for SMRs and soil temperature regimes (STRs). However, reliability of these proxies is not well established nor documented in many cases.\n\nThe xeric SMR presents challenges in the Pacific Northwest region. It is assigned to soils having a wide range in mean annual precipitation (MAP). Xeric soil series mapped in Eastern Idaho receive MAP amounts ranging from 200 mm to 1,200 mm. The xeric SMR is also mapped adjacent to aridic, ustic, and udic SMRs across the Pacific Northwest region. Determination of these boundaries has often been based on plant communities, but relatively little data has been available to substantiate the relationships between SMRs and plant communities.\n\nThe objectives of this project are to: 1) quantitatively describe the variability in soil physical characteristics within a defined control section relative to a selected soil moisture regime, 2) monitor soil moisture and temperature for up to 10 yrs, and 3) assess plant community assemblages for their ability to serve as proxies for SMRs.","project_type":"Grant","lead":"Mark Kimsey","affiliation":"CALS PSES Admin","funder":"USDA Natural Resources Conservation Service","date":"2025","status":"Active","subject":["soil moisture regimes","soil taxonomy","plant communities","soil temperature regimes","xeric regime","soil moisture","aridic regime"],"confidence":"Medium","source_url":"https://www.drought.gov/sites/default/files/events/SoilMoistureRegime_Handout_SMRStudy_MarkKimsey.pdf","project_url":"https://depts.washington.edu/pnwcesu/project/soil-moisture-regimes-in-the-western-us","funder_agency":"USDA","research_area":"Agriculture"},{"objectid":"usda_kimsey_nrcs_soils2026_digital","title":"NRCS Soils2026 Digital Forestry","gist":"Building single-tree digital forest twins from lidar and photogrammetric data at the University of Idaho Experimental Forest.","description":"The University of Idaho operates a digital forestry program centered on its Experimental Forest, which serves as the primary smart and digital forestry research unit. This initiative works at the intersection of artificial intelligence, remote sensing, and advanced forest operations to build single-tree digital forest twins using lidar, photogrammetric 3D point clouds, and sensor data. The program builds upon the completion of the first full operational single-tree inventory in 2019 and functions alongside the Intermountain Forestry Cooperative, a public-industry research group directed by Mark Kimsey.","project_type":"Grant","lead":"Mark Kimsey","affiliation":"CNR Idaho Forest Innovations Lab-918 DO NOT USE See RCI 3979/918 FII","funder":"USDA Natural Resources Conservation Service","date":"2025","status":"Active","subject":["digital forestry","forest inventory","lidar","photogrammetry","forest operations","remote sensing","experimental forest"],"confidence":"Low","evidence_note":"Internal source: the University of Idaho sponsored-projects record. The award is confirmed there; this sponsor publishes no project description. A request for one is outstanding.","funder_agency":"USDA","research_area":"Forestry"},{"objectid":"usda_brooks_nrcs_wepp_model","title":"NRCS WEPP Model Programming, Testing and Support (Rev 3)","gist":"Evaluating and updating the WEPP model to improve erosion predictions in the Palouse region and support NRCS field applications.","description":"This project evaluates, updates, and tests the WEPP model for use in Natural Resources Conservation Service field and watershed applications. It supports NRCS WEPP hillslope model applications by analyzing database updates on model performance and specifically targets the improvement of erosion predictions in the Palouse region of Washington and Idaho. The work includes preparing peer-reviewed or internal reports to support ongoing modeling efforts.","abstract":"NRCS WEPP MODEL PROGRAMMING, TESTING AND SUPPORT - SPECIFIC OBJECTIVES ARE TO: 1. EVALUATE, UPDATE AND TEST THE WEPP MODEL FOR USE IN NRCS FIELD AND WATERSHED APPLICATIONS. 2. SUPPORT NRCS WEPP HILLSLOPE MODEL APPLICATIONS BY ANALYZING DATABASE UPDATES ON MODEL PERFORMANCE. 3. EVALUATE AND IMPROVE WEPP MODEL EROSION PREDICTIONS IN THE PALOUSE REGION OF WASHINGTON AND IDAHO STATES. 4. PREPARE PEER REVIEWED OR INTERNAL REPORTS TO SUPPORT MODELING WORK.","project_type":"Cooperative Agreement","lead":"Erin Brooks","affiliation":"CALS Soils and Water Systems","partners":"USDA Natural Resources Conservation Service","funder":"USDA Agricultural Research Service (USDA-ARS)","date":"2023","status":"Completed","subject":["water erosion","soil erosion","watershed modeling","wepp model","palouse region","hillslope erosion","erosion prediction"],"confidence":"High","source_url":"https://www.usaspending.gov/award/ASST_NON_5950200001_012","project_url":"https://wepp.cloud/weppcloud/","funder_agency":"USDA","research_area":"Water resources"},{"objectid":"odfw_tranmer_ocrf_river_restoration","title":"OCRF Using river restoration to increase thermal buffering capacity in meadow streams","gist":"Monitoring hyporheic fluxes and water temperatures in the Middle Fork John Day River to evaluate meadow restoration efficacy for native salmonid thermal buffering.","description":"This project implements a four-year monitoring strategy in the Middle Fork John Day River Conservation Opportunity Area to evaluate how meadow restoration influences thermal buffering and streamflow during drought conditions. By deploying a dense network of sensors to track hyporheic fluxes, groundwater levels, and water temperatures, the research links specific restoration actions to hydrologic processes and thermal responses across local, reach, and watershed scales. The work addresses the critical need to alleviate thermal stress on native salmonids, such as Chinook and steelhead, by assessing the efficacy of strategies designed to increase physical channel heterogeneity and floodplain connectivity. Additionally, the initiative engages rural community members to connect them with concepts of hydrologic connectivity as a solution for aquatic species survival under acute climatic forcing.","abstract":"Climate change is driving drier conditions and drought throughout Oregon and the Western U.S., resulting in higher stream water temperatures and increasing thermal stress on native aquatic species. The Middle Fork John Day River (MFJDR) Conservation Opportunity Area is a high priority monitoring watershed and is representative of many climates and meadow environments that are critical habitats for native salmonids (e.g., Chinook and steelhead). High summer water temperatures are one of the primary factors limiting native salmonid habitat availability in the basin. To alleviate instream thermal stress, successful meadow restoration must ensure late-season streamflow and thermal buffering capacity to support long-term salmonid survival. Recent stream restoration activities have focused on increasing physical channel heterogeneity and hydrologic connectivity with the floodplain to generate thermal buffering and aquatic habitat resilience. However, it is difficult to evaluate the efficacy of different restoration strategies in addressing high water temperatures owing to the complex hydrologic processes that spatially change over the season. To address these challenges, we have partnered with multiple agencies in Oregon to develop a four-year comprehensive monitoring strategy to link restoration actions, hydrologic processes and thermal responses at the local, reach, and watershed scale.\n\nWe are requesting funds from OCRF to support the first two years of post-river restoration monitoring. During this initial phase, we will deploy a spatially dense network of monitoring sensors within the river corridor to evaluate hyporheic fluxes, groundwater levels, and surface-subsurface water temperatures. We will further leverage the OCRF funding to connect rural community members with the concepts of hydrologic connectivity and thermal resilience in streams as a potential solution for native aquatic species to survive drought and acute climatic forcing in wet meadow environments.","project_type":"Grant","lead":"Andrew Tranmer","affiliation":"COE Ctr for Ecohydraulics Research","funder":"Oregon Department of Fish & Wildlife","date":"2025","status":"Active","subject":["river restoration","thermal buffering","meadow streams","hyporheic flux","groundwater levels","salmonids","hydrologic connectivity"],"confidence":"High","source_url":"https://www.dfw.state.or.us/conservationstrategy/OCRF/projects/2025-8/Evaluating_stream_temperature_heterogeneity.html","funder_agency":"State agency","research_area":"Water resources"},{"objectid":"ai4ui_oit-data-modernization","title":"OIT Data Modernization (Huron)","description":"OIT is leading an institutional data modernization effort in partnership with Huron Consulting. The work is tracked here as part of the AI projects inventory; detailed information will be added as OIT shares scope, timelines, and integration points with related IIDS-built work.","significance":"Foundation for institutional reporting, analytics, and interoperability across enterprise systems.","status":"Tracked","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_ongoing-contracts","title":"Ongoing Contracts","description":"Companion to the Historical Contracts effort, covering the stream of new and active contracts: extract the required fields and build clean uploads for the State of Idaho's Transparency Database. Runs on the ArchAI contract-extraction tooling; currently paused while requested improvements to that application are prioritized and implemented.","significance":"Turns days per contract into minutes per contract on the ongoing stream — an estimated 0.6 FTE returned — and keeps state-portal compliance current instead of batch-remediated.","status":"Paused","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_openera","title":"OpenERA","description":"Institutional sponsored-research administration system, operated by IIDS for the Office of Research and Economic Development. The canonical implementor of the AI4RA Unified Data Model in research administration: 32 tables spanning 20 canonical UDM tables and 12 project-specific extensions. AI4RA Core dual-destiny project; designed to be deployable beyond UI as the partnership matures. As of July 2026, the team has outlined the VERAS-replacement MVP and the required dual-operation period, with three to four developers contributing; transfer of the repository to the ui-AI4UI GitHub organization is pending.","significance":"On-prem, UDM-aligned ERA system with shared data semantics across ORED tooling. Enables AI features (extraction, lookup, classification) on research-admin data without third-party data egress. Reference deployment for AI4RA partners.","status":"Building","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_out-of-state-tax-tracking","title":"Out-of-State Tax Tracking","description":"Tracks state tax withholdings for UI employees working outside Idaho — including international W-4 cases routed through Payroll — and gets them remitted to the right state authorities. Automates the data transfer across systems that Payroll previously reconciled by hand. The project is feature-complete and paused pending onboarding onto OIT's Nexus platform, following the Retroactive Payment Requests module.","significance":"Compliance with multi-state withholding requirements with less manual risk — an estimated 0.2 FTE of Payroll capacity returned.","status":"Paused","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"pcd_lew_palousesat_crop_residue","title":"PalouseSAT- Crop Residue 2024","gist":"Estimating fall crop residue cover in Whitman County sub-watersheds using field measurements and satellite data from 2013 to present.","description":"This project estimates changes in crop residue across Whitman County by measuring 90 fields with varying tillage practices and utilizing moderate resolution satellite imagery. Researchers develop a statistical model to estimate fall crop residue cover, tracking changes from 2013 to the present across all sub-watersheds. Ongoing field measurements by the Palouse Conservation District refine these estimates to support conservation efforts in the region.","abstract":"The Palouse Conservation District has been working with researchers at the University of Idaho to estimate changes in crop residue in Whitman County. The goals for this project are to:\n\n- Measure crop residue in 90 fields including a variety of conventional tillage, mulch tillage, and no-till management practices\n- Track and map changes in crop residue from 2013 to present, as data become available, in all the sub watersheds (HUC 12) found in Whitman County\n\nThe field measurements along with freely available moderate resolution satellites are used to develop a statistical model that estimates fall crop residue cover. Palouse Conservation District staff will continue to collect field measurements over the next several years to further refine the estimates of fall residue cover. This work has been funded by Washington State Department of Ecology.","project_type":"Subaward","lead":"Roger Lew","affiliation":"CAA Virtual Technology and Design","partners":"Washington State Department of Ecology","funder":"Palouse Conservation District","date":"2024","status":"Active","subject":["crop residue","no-till","tillage","remote sensing","satellite imagery","soil conservation","whitman county"],"confidence":"Medium","source_url":"https://palousesat.org/","funder_agency":"State agency","research_area":"Agriculture"},{"objectid":"usda_murdoch_genomic_reference_materials","title":"PARTNERSHIP: Development of genomic reference materials for cattle","gist":"Development of curated cattle genomic reference materials and cell lines to benchmark variant calls and standardize high-throughput data analysis.","description":"This project develops and disseminates highly curated reference materials for cattle to address the lack of a comprehensive benchmark dataset in agricultural genomics. By creating standardized resources, the initiative enables the evaluation of completeness and accuracy in high-throughput data, overcoming current inefficiencies where individual laboratories develop their own isolated standards. The work includes producing cell lines for reference samples to support future data collection for emerging technologies, thereby facilitating comparison across datasets and ensuring correctness within genomic analyses.","abstract":"AGRICULTURAL GENOMICS HAS ADVANCED RAPIDLY OVER THE LAST DECADE, LARGELY DRIVEN BY TECHNOLOGY ADVANCEMENTS RELATED TO SEQUENCE DATA GENERATION AND ANALYSIS. THIS HAS LED TO DEVELOPMENT OF HIGH-QUALITY REFERENCE GENOMES, SNP-CHIPS AND LOW-PASS SEQUENCING/IMPUTATION WHICH IN TURN HAS ENABLED GENOMIC SELECTION AND THE GENERATION OF RAW DATA AT UNPRECEDENTED SCALE. HOWEVER, THE GENOMICS COMMUNITY HAS NOT YET DEVELOPED A COMPREHENSIVE AND HIGHLY CURATED DATASET WHICH CAN BE USED AS A BENCHMARK TO EVALUATE THE COMPLETENESS OR ACCURACY OF THE HIGH THROUGHPUT DATA BEING GENERATED TODAY. CURRENTLY, EACH LAB DEVELOPS THEIR OWN STANDARDS, IF DONE AT ALL, WHICH IS LABORIOUS AND DOES NOT FACILITATE COMPARISON ACROSS DATASETS LEADING TO INEFFICIENCY AND MAKES IT DIFFICULT, OR IMPOSSIBLE, TO EVALUATE CORRECTNESS WITHIN AND BETWEEN DATASETS. THIS PROPOSAL IS FOCUSED ON DEVELOPING AND DISSEMINATING HIGHLY CURATED REFERENCE MATERIAL FOR CATTLE THAT CAN BE USED TO BENCHMARK VARIANT CALL SETS AND PROVIDEA COMPREHENSIVE SET OF ANCILLARY DATA NEEDED FOR MOST GENOMIC ANALYSES. ADDITIONALLY, WE WILL PRODUCE CELL LINES FOR THE REFERENCE SAMPLES TO ENABLE FUTURE DATA COLLECTION FOR TECHNOLOGIES NOT YET DEVELOPED.","project_type":"Grant","lead":"Brenda Murdoch","affiliation":"CALS Animal, Vet & Food Sciences","partners":"National Institute of Food and Agriculture/USDA","funder":"University of Missouri","award_number":"2023-67015-39261","date":"2023","status":"Active","subject":["cattle","genomic reference materials","variant calling","benchmarking","cell lines","agricultural genomics","genomic selection"],"confidence":"Medium","source_url":"https://www.usaspending.gov/award/ASST_NON_20236701539261_012","funder_agency":"University partner","research_area":"Genomics & molecular biology"},{"objectid":"nih_stenkamp_patterning_genes_retinal","title":"Patterning Genes in Retinal Development","gist":"The study examines thyroid hormone signaling and nuclear receptors to regulate tandemly-replicated cone opsin genes in zebrafish and human retinal organoids.","description":"This project investigates cellular and molecular events governing the generation of specific cell types in the vertebrate retina, with a focus on endocrine signaling pathways and nuclear hormone receptors. Research centers on the genetic elements regulating differential expression of cone visual pigment genes within tandemly-replicated arrays, utilizing zebrafish models and human iPSC-derived retinal organoids. Understanding these mechanisms offers potential therapeutic strategies for heritable color blindness, X-linked retinal degenerations, and age-related macular degeneration by enabling the manipulation of gene expression to restore cone phenotypes.","abstract":"Patterning Genes in Retinal Development\n Project Summary\n The long-range goal of this grant is to determine the cellular and molecular events that lead to the\ngeneration of specific cell types in the vertebrate retina. In this renewal we focus upon endocrine signaling\npathways, nuclear hormone receptors, and genetic elements that regulate differential expression of the cone\nvisual pigment genes on tandemly-replicated gene arrays. In humans a tandemly-replicated array on the X\nchromosome consists of one long wavelength-sensitive (LWS) gene followed by 1-9 medium wavelength-\nsensitive (MWS) genes, which have diverged spectrally from LWS. This recent replication has provided most\nhumans with trichromatic color vision, because LWS, MWS, and SWS1 opsin proteins are uniquely expressed\nin separate cone populations. Heritable defects in the LWS/MWS array result in various forms of color\nblindness, X-linked retinal degenerations, and Bornholm Eye Disease, a cone dysfunction associated with high\nmyopia. Insights into regulation of differential expression of LWS vs. MWS opsins could allow therapeutic\nmanipulation of gene expression to treat these disorders. In addition, future regenerative approaches to the\ntreatment of other retinal disorders that involve the loss of cones (age-related macular degeneration;\nStargardt's disease) would ideally include similar in vitro or in vivo manipulations to generate cone phenotypes\nin ratios that support high-acuity color vision. A decades-old model for human LWS vs. MWS opsin regulation\nstates that a stochastic event favors an association of an upstream regulatory region with the LWS or most\nproximal MWS opsin promoter or exon. However, topographic patterns of the LWS:MWS ratio suggest that a\nnonrandom, trans-regulatory mechanism may be involved. Pursuit of regulatory mechanisms has been limited\nbecause within mammals, only primate and bat genomes are known to harbor tandem opsin arrays. In\ncontrast, the genomes of teleost fish, including zebrafish, contain numerous tandem arrays of opsins, which\nare the consequences of independent gene replication events and neofunctionalization. In the previous award\nperiod, we demonstrated that in zebrafish, the endocrine signal thyroid hormone (TH) regulates differential\nexpression of the tandem duplicates, lws1 vs. lws2, an array that shares a common ancestral LWS gene with\nthe genes of the human LWS/MWS array. Our preliminary data suggest the hypothesis that the TH receptor,\nThrb2 (already known to promote the LWS cone phenotype), may have been evolutionarily co-opted to also\nregulate differential expression of lws1 vs. lws2, such that unliganded Thrb2 promotes lws2 and suppresses\nlws1, while liganded Thrb2 promotes lws1. We have identified two predicted, palindromic TH response\nelements (ppTREs) on the lws locus, and preliminary studies suggest that each element has roles in regulating\nendogenous patterns of lws1 vs. lws2, and in the response to TH. Additional preliminary data suggest that TH\ncan regulate expression of LWS vs. MWS opsin transcripts in human iPSC-derived 3D retinal organoids.\nTogether these findings represent tremendous breakthroughs in revealing novel pathways for regulation of\ntandemly-replicated gene arrays in vertebrates. In this renewal we drill down to examine the signaling\npathways, receptors, and genetic elements that mediate this regulation, with three Aims: Aim 1. Identify the\nreceptor(s) that mediate the response of lws1 and lws2 to TH. Aim 2. Identify the regulatory elements on the\nlws locus that mediate the response of lws1 and lws2 to TH. Aim 3. Determine the role of TH signaling in\nregulating LWS vs. MWS ratios in human cones.","project_type":"Grant","lead":"Deborah Stenkamp","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Institutes of Health","award_number":"R01EY012146","date":"2024","end_year":"2029","status":"Active","subject":["retinal development","opsin genes","thyroid hormone signaling","gene regulation","cone photoreceptors","color vision","zebrafish"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/10883042","funder_agency":"National Institutes of Health","research_area":"Genomics & molecular biology"},{"objectid":"usda_vanleuven_phage_bacteria_interactions","title":"Phage-bacteria interactions in honey bee microbiomes: Identifying factors contributing to healthy bees and disease prevention","gist":"Research on bacteriophage interactions in honey bee microbiomes to identify factors for disease prevention and resistance management.","description":"This project investigates the role of bacteriophages, the viruses that infect bacteria, within honey bee microbiomes to determine their impact on bee health and disease susceptibility. By analyzing differences between diseased and non-diseased colonies, the research identifies phages capable of targeting specific pathogens and adapts them to overcome evolving resistance in foulbrood. The work aims to develop methods for manipulating hive microbial communities to reduce disease, thereby supporting agricultural production and reducing reliance on antibiotics.","abstract":"The microorganisms living in honey bees (the microbiome) are key to bee health. Disruptions of the microbiome often have negative consequences. Yet we know very little about the most abundant microbes in honey bees; the viruses that infect bacteria (bacteriophages). Our work seeks to learn about the role that these viruses play in the health of bees; if they affect susceptibility to disease and how they can be used to influence the bee microbiome. An improved understanding of how bacteriophages interact with bacteria and animal hosts will result in innovative ways to increase agricultural production, ensure food stability, and relieve our dependence on antibiotics in agriculture.The long-term goal of this work is to manipulate the microbial community of the hive using phages to reduce disease. Towards this goal, we propose three objectives: (1) to understand the difference between diseased and non-diseased honey bee microbiomes, (2) to identify and improve phages that infect honey bee pathogens, and (3) to adapt phages to overcome foulbrood resistance when it evolves. During this project, we will innovate ways to improve bee health, train students in high-demand skills, and engage the public in honey bee and scientific research.","project_type":"Grant","lead":"James VanLeuven","affiliation":"RCI IMCI","funder":"National Institute of Food and Agriculture/USDA","award_number":"2023-67013-39067","date":"2023","status":"Active","subject":["honey bee","bacteriophage","microbiome","foulbrood","disease resistance","phage therapy","apiary health"],"confidence":"High","source_url":"https://portal.nifa.usda.gov/enterprise-search/projects/1029829","project_url":"https://github.com/jtvanleuven/plarvae_resistance","funder_agency":"USDA","research_area":"Health & disease"},{"objectid":"ibc_piaskowski_phone_online_public","title":"Phone App and Online Public Database of Barley Variety Testing Trials","gist":"WAVE is a multi-state Pacific Northwest hub providing public access to filter, query, and download historic and current variety testing data for wheat and emerging crops like barley.","description":"WAVE serves as a multi-state hub for exploring variety testing data for crops vital to the Pacific Northwest, currently featuring wheat while expanding tools for barley, canola, lentils, dry peas, and chickpeas. This initiative provides an open online database allowing producers, researchers, and the public to filter, query, and download current and historic trial data. The platform aims to deliver standalone analytical summaries and dedicated web applications for each supported crop to enhance data accessibility.","project_type":"Grant","lead":"Julia Piaskowski","affiliation":"CALS Research Administration","funder":"Idaho Barley Commission","date":"2024","status":"Active","subject":["barley","variety testing","wheat","canola","lentils","dry peas","chickpeas"],"confidence":"Medium","source_url":"https://westernagdata.org/","project_url":"https://westernagdata.org/","funder_agency":"State of Idaho","research_area":"Agriculture"},{"objectid":"nsf_nuismer_predicting_spread_transmissible","title":"Predicting the spread and impact of transmissible vaccines","gist":"Developing mathematical models to predict the spread and human health impact of self-disseminating wildlife vaccines for diseases like Lassa virus.","description":"This project develops mathematical, statistical, and computational tools to evaluate the performance of self-disseminating wildlife vaccines before field trials. By creating models that integrate reservoir age structure and vaccine shedding patterns, the work quantifies the likelihood that these vaccines will reduce spillover of diseases like Lassa virus into human populations. The research addresses the critical gap in current reactive approaches to zoonotic threats by enabling informed decisions on vaccine deployment. Additionally, the initiative trains first-generation college students from rural backgrounds in these modeling techniques and maintains a public website to explain the technology and share research results.","abstract":"Infectious diseases that normally thrive in wild animals occasionally make the leap into the human population. For instance, rabies virus infects and kills tens of thousands of people each year when wild animals carrying the virus bite humans and transmit the virus to them. Other viruses that occasionally leap from animals to humans are even more dangerous because they can also transmit from human to human and thus potentially seed epidemics or pandemics. Unfortunately, we do not yet have effective solutions in place to stop these infectious diseases from spilling over into the human population. Instead, our current approach to these animal diseases is reactive, and focuses on medical treatment of humans who have become infected and corralling human outbreaks before they can spread and become full blown epidemics or pandemics. A promising solution to this challenging problem is the development of wildlife vaccines that can spread themselves from one animal to the next. By self-disseminating, these vaccines magnify the spread of immunity within the wild animal population and reduce or eliminate the risk of spillover into the human population. Although multiple self-disseminating animal vaccines are being developed, we do not yet have the mathematical, statistical, and computational tools we need to critically evaluate their performance and thus make informed decisions about their possible use. Work on this project will develop these quantitative tools and enable candidate self-disseminating vaccines to be critically evaluated before they are used. In addition, this project will train first-generation college students from rural backgrounds to use mathematical and computational models to evaluate and optimize emerging biotechnologies critical to the future of the US economy. Student recruitment will be facilitated by offering competitive financial support that relieves pressure to abandon research experiences in favor of traditional employment. Finally, this project will continue development of a website that explains self-disseminating vaccines to the public, disseminates relevant research results, and examines the state of this emerging technology.\n\nBefore making the decision to conduct even small-scale field trials, the likelihood that a self-disseminating vaccine will improve human health should be quantified. This requirement poses a formidable technical challenge because data on the behavior of the vaccine within the target animal population cannot be collected prior to release. This project will overcome this technical challenge using mathematical models of recombinant vector transmissible vaccines that can be parameterized using a combination of field and laboratory data. Specifically, mathematical models will be developed that integrate the age structure of the reservoir population and the explicit pattern of vaccine shedding from animals infected with vaccine. These models will take the form of a system of partial differential equations. Field data will come from trapping studies of the reservoir animal that record the age of each captured animal and whether it was infected by the vector virus used to construct the candidate vaccine. Laboratory data will describe the temporal pattern of vaccine shedding from reservoir animals experimentally infected with the vaccine. Approximate Bayesian computation will be used to parameterize the models and a stochastic simulation framework developed for predicting the outcome of a proposed vaccine release. By repeatedly simulating a vaccine release for models parameterized by drawing randomly from the posterior distribution, this framework faithfully integrates reservoir ecology, randomness in biological processes, and uncertainty in parameter estimates. The methodology developed by this project will be applied to a prototype self-disseminating vaccine for Lassa virus but will be broadly applicable to self-disseminating vaccines developing for a range of animal reservoirs.\n\nThis project is jointly funded by the Population and Community Ecology (PCE) Cluster in the Division of Environmental Biology, the Established Program to Stimulate Competitive Research (EPSCoR), and the Mathematical Biology Program in the Division of Mathematical and Physical Sciences.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Scott Nuismer","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2314616","date":"2023","end_year":"2027","status":"Active","subject":["transmissible vaccines","zoonotic diseases","spillover","mathematical modeling","lassa virus","wildlife vaccination","approximate bayesian computation"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2314616","project_url":"https://transmissiblevaccines.org/","funder_agency":"National Science Foundation","research_area":"Health & disease"},{"objectid":"ai4ui_processmapping","title":"ProcessMapping","description":"Full-stack app plus data repository for Research Administration process intelligence. Canonical process-map JSON, Vandalizer-powered transcript ingest, workflow comparison, schema-validated projection into insight-db. AI4RA dual-destiny project.","significance":"Shared vocabulary and visibility for RA processes. Identifies process/tool coverage gaps. Requirements source for automation. Onboarding and training asset.","status":"Building","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nsf_jones_experiences_undergraduates_grant","title":"Research Experiences for Undergraduates supplement to NSF grant, entitled “Genomics of Sexual Selection in Pipefishes and Seahorses” (DEB-1953170)","gist":"Sequencing twelve seahorse and pipefish genomes to analyze how sexual selection and conflict drive genome evolution and sex-specific gene expression.","description":"This project utilizes modern sequencing methodologies to compare the genomes of twelve seahorse and pipefish taxa with varying histories of sexual selection and conflict. By analyzing monogamous species with weak selection against polygamous species with strong selection, researchers delineate how these evolutionary mechanisms shape genome evolution and sex-specific gene expression. The work integrates complete genome sequencing, comparative transcriptomics, and population genomics to explain genomic differences between sexes, while training students in genomic techniques and expanding the research community through workshops and public data release.","abstract":"Sexual selection is an important evolutionary mechanism that results in the evolution of extravagant ornaments, strong mating preferences, and differences between the sexes. Sexual selection also sets the stage for sexual conflict, a situation in which the evolutionary interests of the two sexes fail to coincide, resulting in traits or genes that can be beneficial to one sex but harmful to the other sex. While the effects of sexual selection and conflict on traits are well understood, little is known about how these mechanisms affect the genome. A key test of theory relating sexual selection, sexual conflict and genome evolution would entail genome comparisons in groups of related species in which some have had a history of strong sexual selection and some have had a history of weak sexual selection. In this project, the researchers will use seahorses and the related pipefishes to conduct such a test. Seahorses and some pipefishes are monogamous with long-term pair-bonds, and this mating system results in weak sexual selection and little sexual conflict. Other pipefishes have independently evolved polygamy (multiple mating by one or both sexes), which results in strong sexual selection and substantial conflict. The researchers will apply modern sequencing methodologies to delineate the impacts of sexual selection and conflict on genome evolution in these species. This project has significance well beyond seahorses and pipefishes, as many species, including humans, have had a recent evolutionary history involving sexual selection and conflict. This history can explain why the sexes are different at the level of the genome and why the same gene can have different effects in the sexes. This project will also train a new generation of graduate students and undergraduates in cutting-edge genomic techniques and statistical methodologies. In addition, it will expand the pipefish and seahorse research community by offering week-long workshops and a new wealth of publicly available genomic data.\n\nThe project will involve a total of twelve taxa, including three seahorses and nine pipefishes, chosen for their phylogenetic relationships and known patterns of sexual selection. The seahorses (genus Hippocampus) and three of the pipefish species (genus Doryrhampus) are monogamous with pair-bonds, and the other six pipefish (three each from the genera Syngnathus and Nerophis) are polygamous with a history of strong sexual selection. The project will involve (1) the complete sequencing of the genomes of all twelve taxa, (2) comparative transcriptomics, which will examine patterns of sex-specific gene expression, and (3) comparative population genomics, which will detect contemporary genome-level selection. Data will be integrated across these three levels of approaches to understand the genome-level effects of sexual selection and sexual conflict in light of evolutionary theory.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Adam Jones","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"1953170","date":"2024","end_year":"2027","status":"Active","subject":["sexual selection","sexual conflict","pipefish","seahorse","comparative genomics","population genomics","gene expression"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=1953170","funder_agency":"National Science Foundation","research_area":"Genomics & molecular biology"},{"objectid":"nsf_ewart_infrastructure_networking_infrastruc","title":"Research Infrastructure: CC*Networking Infrastructure: Deep Soil to Supercomputing - Infrastructure Enhancements as a Force Multiplier for Idaho Research","gist":"Upgrades fiber and Science DMZ networks to enable 10Gbps access to the Deep Soil Ecotron and 100Gbps throughput for the Falcon supercomputer.","description":"This project upgrades network infrastructure at the University of Idaho to remove bottlenecks and accelerate data-intensive research across the state. It replaces legacy multi-mode fiber to enable 10Gbps access to the Deep Soil Ecotron and modernizes 100Gbps campus Science DMZ networks supporting the Falcon supercomputer. These enhancements facilitate efficient scientific data exchange for peer research universities, undergraduate institutions, and tribal partners, maximizing shared cyberinfrastructure resources.","abstract":"This network improvement project enables and accelerates data-intensive research at the University of Idaho and beyond by addressing acute network bottlenecks and improving multi-institutional access to shared research infrastructure. Idaho’s unique model for statewide cyberinfrastructure collaboration stems from a collective need to share and maximize limited resources while advancing multi-institutional science efforts. This project accelerates research and education at the University of Idaho while improving access to shared cyberinfrastructure for our peer research universities, primarily undergraduate institutions, and tribal research partners.\n\nThis project achieves two primary objectives: 1) replacing legacy multi-mode fiber optics to enable 10Gbps high-speed access to the Deep Soil Ecotron, a new NSF mid-scale infrastructure project, and 2) end-to-end modernization of 100Gbps campus Science DMZ networks through targeted equipment improvements to remove barriers to efficient scientific data exchange.\n\nThe Deep Soil Ecotron represents unique research infrastructure hosted at the University of Idaho, allowing U.S. investigators to conduct soil biochemistry experiments at extreme soil depths. This network improvement project replaces aging multi-mode fiber infrastructure to enable efficient data exchange with the Ecotron facility, multiplying the reach and impact of this unique national research resource. Under University of Idaho leadership, Idaho’s research universities co-manage and co-utilize significant shared cyberinfrastructure such as the Falcon supercomputer. This project provides an order-of-magnitude upgrade in data throughput to existing Science DMZ networks supporting Falcon. As multi-institutional dependency on Falcon increases, these improvements are a necessary step to support a growing set of known and future University of Idaho science drivers and collaborations within the state.\n\nThis award by the Office of Advanced Cyberinfrastructure is jointly supported by the Established Program to Stimulate Competitive Research (EPSCoR).\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Dan Ewart","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Science Foundation","award_number":"2346652","date":"2024","end_year":"2026","status":"Active","subject":["cyberinfrastructure","science dmz","high-speed networking","deep soil ecotron","supercomputing","data-intensive research","soil biochemistry"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2346652","funder_agency":"National Science Foundation","research_area":"Data science & computing"},{"objectid":"ai4ui_retroactive-payment-requests","title":"Retroactive Payment Requests","description":"Replaces the paper/email retroactive payment request process with a validated electronic submission flow plus a dashboard for payroll analysts. Submissions are checked for completeness and verified against Banner data before they reach an analyst, so corrections happen at intake instead of mid-process. Deployed on OIT's Nexus platform and in production use by Payroll since July 2026; payroll-staff feedback now drives the enhancement backlog.","significance":"Employees are paid correctly with less back-and-forth: an estimated 0.3 FTE returned by shortening the process and catching incomplete submissions at intake.","status":"Live","subject":["artificial intelligence"],"confidence":"High","source_url":"https://nexus.uidaho.edu","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_rfd-career","title":"RFD CAREER Dashboard","description":"Interactive cohort dashboard tracking participant progress through CAREER Club workbook data. Supports faculty development program leaders in identifying stuck participants and evaluating program effectiveness.","significance":"Cohort visibility for program leaders. Data-driven program improvement. Stronger NSF CAREER-grant pipeline.","status":"Live","subject":["artificial intelligence"],"confidence":"High","source_url":"https://rfdcareerclub.insight.uidaho.edu","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_rfd-companion","title":"RFD Companion","description":"Standalone operational workspace for proposal-development support, faculty-development programs, internal competitions, events, reviews, shared calendars, and staff and faculty next actions. RFD Companion integrates with OpenERA through explicit least-privilege APIs, is intended to replace RFD's InfoReady workflows after parity and migration validation, and will replace TDX for proposal-development operations after a controlled cutover.","significance":"Replaces fragmented spreadsheets and vendor-shaped workflows with one RFD-owned operating model, reduces duplicate entry across research-administration systems, and positions RFD to retire the approximately $17,000-per-year InfoReady contract after validated parity and migration.","status":"Building","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nsf_kliskey_track_community_engaged","title":"RII Track-1: Idaho Community-engaged Resilience for Energy-Water Systems (I-CREWS)","gist":"I-CREWS uses the Snake River Basin to model energy-water resilience and co-develop tribal research networks for equitable futures.","description":"The I-CREWS project utilizes Idaho's Snake River Basin to examine how trade-offs in energy and water systems influence resilience against climate, population, and technological shifts. By integrating diverse knowledge systems, advanced modeling, and community engagement, the initiative evaluates socio-environmental-technological typologies to determine patterns of multisystemic resilience. Administered by the University of Idaho with tribal and university partners, the work develops alternative futures scenarios and fosters a Tribal Nations Research Network to center indigenous knowledge in research. These efforts aim to inform national strategies for equitable energy-water governance while supporting workforce development through co-created community projects.","abstract":"There is a national need to proactively address the impacts of climate, population, and technological change on energy and water (E-W) systems across key watersheds in the western U.S. This \"Idaho Community-engaged Resilience for Energy-Water Systems\" (I-CREWS) project will use Idaho’s Snake River Basin watershed to address two questions:  1) What role do trade-offs and changes in E-W systems, including storage, efficiency, conservation, local knowledge, and governance dynamics, play in determining resilience strategies for climate-driven, population, and technological change? and (2) How does incorporating diverse ways of knowing, community engagement, and advanced modeling lead to more equitable and resilient E-W futures? The State of Idaho provides an excellent testbed for the project. This is due to the features of Idaho’s landscapes, which span a range of gradients (e.g., hydrologic, topographic, demographic, jurisdictional) and population densities (e.g., small rural towns and Native American communities to expanding urban areas). The results of the I-CREWS project will inform multisystemic resilience and E-W issues nationally. I-CREWS will be administered by the University of Idaho in collaboration with Boise State University, Idaho State University, the Shoshone-Bannock Tribes, and the Coeur d'Alene Tribe.  The I-CREWS project will grow research capacity with partner Tribal nations through a new Tribal Nations Research Network (TNRN), which will be developed to recenter knowledge exchange between Tribes and Idaho universities, focusing on collaboration through the development of tribally-originated research.  \n\nThe key research themes of I-CREWS are to: (1) characterize and evaluate E-W configurations for a continuum of resilience strategies; (2) model and represent E-W configurations and their resilience; and (3) develop alternative futures scenarios of E-W trajectories and their resilience to change. I-CREWS researchers will use socio-environmental-technological systems (SETS) typologies in their hypothesis that communities undergoing changes in their E-W systems can be characterized by SETS typologies at different scales to determine patterns of multisystemic resilience to climate-driven, demographic, and technological changes. I-CREWS researchers aim to determine whether the adoption of SETS interventions increases resilience and reduces vulnerability in E-W systems. The research will investigate the interaction of competing objectives (e.g., energy, water, resources, public use, local values) in a community-decision context. The I-CREWS project will engage partners across constituencies (scientists, land managers, policymakers, administrators, Tribal nations, and end users) in order to advance the integration of more comprehensive science with management and policy strategies for resilient stewardship and governance, thus providing locally-valued choices as well as capacity-building to achieve the project’s impacts.  I-CREWS will support workforce development and student training through high-context, community-engaged courses and projects that are co-created with community members to address E-W systems issues.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Cooperative Agreement","lead":"Andrew Kliskey","affiliation":"RCI EPSCoR","funder":"National Science Foundation","award_number":"2242769","date":"2023","end_year":"2028","status":"Active","subject":["energy-water nexus","resilience","community engagement","socio-environmental systems","tribal knowledge","watershed management","climate adaptation"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2242769","project_url":"https://idahocrews.org/","funder_agency":"National Science Foundation","research_area":"Water resources"},{"objectid":"ai4ui_sem-experiential","title":"SEM Experiential Learning","description":"Platform for managing experiential learning and student engagement records. MVP covers organizations, events, attendance, dashboard metrics, and admin user lifecycle. Scaffolded from TEMPLATE-app following OpenERA patterns. This is an early example of IIDS diffusing agentic-coding capability out into partner units: SEM is co-building alongside IIDS, not just consuming.","significance":"Consolidates fragmented student engagement tracking. Supports recruitment/retention reporting. Demonstrates unit-led co-build pattern — a repeatable path for other UI units to develop their own AI-assisted tooling.","status":"Building","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"usda_poolakkal_small_area_estimation","title":"Small Area Estimation Techniques Using Strategic and Stand-level Forest Inventory Data","gist":"Developing robust small-area estimation strategies to produce accurate stand-level diameter distributions for forest inventory applications.","description":"This project develops robust small-area estimation strategies to generate accurate stand-level diameter distributions for forest inventory data. Led by PI Jaslam Poolakkal at the University of Idaho, the work addresses technical challenges in estimating forest attributes at fine spatial scales by integrating strategic and stand-level data. The research aims to transition these methods from experimental to operational status, enhancing the precision of estimates for subpopulations across small geographic areas and short time intervals.","project_type":"Grant","lead":"Jaslam Poolakkal","affiliation":"CNR Idaho Forest Innovations Lab-918 DO NOT USE See RCI 3979/918 FII","partners":"USDA Forest Service","funder":"NCASI Foundation","date":"2025","status":"Active","subject":["small area estimation","forest inventory","diameter distribution","stand-level data","spatial estimation","forest attributes"],"confidence":"High","source_url":"https://www.ncasifoundation.org/projects/partnership-for-small-area-estimation/","project_url":"https://www.ncasifoundation.org/projects/partnership-for-small-area-estimation/","funder_agency":"Private foundation","research_area":"Forestry"},{"objectid":"nasa_bernards_gsfc_global_dryland","title":"SMD/GSFC: Improving global dryland streamflow modeling by better characterizing vegetation use of deep water resources using NASA’s GRACE/GRACE-FO, SWOT, and LIS","gist":"The University of Idaho uses NASA GRACE/GRACE-FO, SWOT, and LIS data to refine global dryland streamflow models by analyzing vegetation's use of deep water resources.","description":"This project, led by the University of Idaho, aims to improve global dryland streamflow modeling by better characterizing how vegetation utilizes deep water resources. The research integrates data from NASA's Gravity Recovery and Climate Experiment (GRACE/GRACE-FO) and Surface Water and Ocean Topography (SWOT) missions with the Land Information System (LIS) to enhance hydrological understanding in arid regions.","project_type":"Cooperative Agreement","lead":"Matthew Bernards","affiliation":"COE Idaho Space Grant","funder":"NASA Shared Services Center","date":"2024","status":"Active","subject":["dryland hydrology","streamflow modeling","vegetation water use","deep groundwater","grace","swot","land surface modeling"],"confidence":"High","source_url":"https://www.nasa.gov/news-release/nasa-awards-expand-research-capabilities-at-institutions-nationwide/","project_url":"https://www.nasa.gov/news-release/nasa-awards-expand-research-capabilities-at-institutions-nationwide/","funder_agency":"NASA","research_area":"Water resources"},{"objectid":"ai4ui_stratplan","title":"Strategic Plan Dashboard","description":"Data-driven dashboard visualizing and analyzing how 25 academic and administrative units align their tactics with the University's 2025–2030 Strategic Plan. Evolving toward an execution and investment portfolio tool. Currently used for executive review; could expand to unit self-service.","significance":"Makes strategic execution visible. Surfaces under-served priorities, cross-unit synergies, and misalignment. Supports investment prioritization conversations.","status":"Live","subject":["artificial intelligence"],"confidence":"High","source_url":"https://strategicplan.insight.uidaho.edu","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nsf_budwig_v200756_ey5516_system","title":"Supplement to V200756/EY5516 NAS System for VVS","gist":"A Volumetric Velocimetry System maps 3D fluid flows to study lava breakouts, streambed transport, and validate computational models.","description":"This project funds the acquisition of a Volumetric Velocimetry System (VVS) to map three-dimensional flow fields within physical models of geoscience phenomena. By capturing all three temporally and spatially resolved components of velocity data, the system enables the direct solution of Navier-Stokes equations to retrieve pressure and force distributions. These capabilities support research into solute mixing, sediment transport, and microbial colonization while providing essential data to validate complex computational models. The initiative also includes a web presence for data visualization and educational partnerships with local schools to facilitate student visits to the Center for Ecohydraulics Research.","abstract":"Fluid flows in nature vary intrinsically over space and time.  Simultaneously mapping the flow field within a three-dimensional (3D) volume will allow the full characterization of not only the flow field, but also the pressure field and any shear and normal forces within the fluid and at boundaries. This will have a transformative impact on our ability to characterize solute mixing, particle and solute transport, and aquatic organisms, ranging from microorganisms within porous media to fish moving in a river.  This project funds the acquisition of a Volumetric Velocimetry System (VVS) to support experimental research that will map flow fields in physical models of geoscience phenomena.  The VVS will provide researchers the capability to acquire volumetric realizations of flow structures using this minimally invasive tool.   Example applications of the system include model studies of breakout during surface lava flow which will improve prediction of when lava will arrive at specified location.   In a second application, the VVS will probe critical questions about and solute and sediment grain transport in streambeds.  Results from these studies will, for example, improve predictions of channel stability and be applied to the design of river restoration projects.  Lastly, volumetric descriptions of the experimental flow fields from this system will be powerful tools for the validation of complex computational models, which are becoming a common investigative tool even though in many circumstances models are not benchmarked with proper data. A web presence highlighting VVS projects will provide visualizations and links to available data. A partnership with a local middle-school teacher will facilitate visits of local students to the Center for Ecohydraulics Research at University of Idaho. \n\nThe acquisition of a Volumetric Velocimetry System (VVS) will enable researchers to overcome the crucial shared challenge faced by scientists and engineers who seek understanding of the fundamental nature of several types of fluid flows: the inability to acquire all three temporally and spatially resolved components of velocity data and their spatial and temporal derivatives, whose information will allow direct solution the Navier-Stokes equations retrieving information on the pressure and force distribution. Moreover, volumetric descriptions of the experimental flow fields from this system will be powerful tools for the validation of complex computational models, which are becoming a common investigative tool even though in many circumstances models are not benchmarked with proper data. Pursuing these research avenues will yield insights into geoscience phenomena, including entrainment in deep-sea hydrothermal systems and breakout during surface lava flows. In addition, coupling the VVS with the refractive index matching will probe critical questions about microbial colonization of pore interstices, turbulence dissipation at and within streambeds and its impact on organisms, and solute and sediment grain transport in streambeds.\n\nThis award reflects NSF's statutory mission and has been deemed worthy of support through evaluation using the Foundation's intellectual merit and broader impacts review criteria.","project_type":"Grant","lead":"Ralph Budwig","affiliation":"COE Ctr for Ecohydraulics Research","funder":"National Science Foundation","award_number":"2043382","date":"2023","end_year":"2023","status":"Active","subject":["fluid dynamics","volumetric velocimetry","turbulence","sediment transport","solute mixing","lava flow","hydrothermal systems"],"confidence":"High","source_url":"https://www.nsf.gov/awardsearch/showAward?AWD_ID=2043382","funder_agency":"National Science Foundation","research_area":"Water resources"},{"objectid":"usdi_waits_demographic_genetic_monitoring","title":"SWBRPP: Demographic and genetic monitoring of the endangered Sonoran pronghorn in Organ Pipe Cactus National Monument, Mexico, and surrounding areas using fecal DNA sampling","project_type":"Grant","lead":"Lisette Waits","affiliation":"CNR Fish & Wildlife Sciences","funder":"USDI National Park Service","date":"2025","status":"Active","subject":["sonoran pronghorn","fecal dna","population genomics","endangered species","genetic monitoring","organ pipe cactus national monument","non-invasive sampling"],"confidence":"High","source_url":"https://www.nps.gov/orgs/1461/funded-projects.htm","project_url":"https://www.nps.gov/orgs/1461/funded-projects.htm","funder_agency":"National Park Service","research_area":"Genomics & molecular biology"},{"objectid":"ai4ui_template-app","title":"TEMPLATE-app","description":"Archived scaffold that established an opinionated starting point for University business applications built with agentic AI development. It combined UI's technology stack, documentation standards, data-governance classification, security controls (JWT, RBAC, dependency scanning), CI/CD, and agent guidance. The record is retained as a reference for applications that adopted its patterns.","significance":"Consistent app patterns across UI units. Faster new-app delivery. Propagates institutional standards by construction. Lowers the barrier for unit-led co-builds (the SEM pattern).","status":"Retired","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"usda_strickland_interaction_increased_atmosphe","title":"The interaction of increased atmospheric temperature and agricultural antibiotic deposition on the soil community and soil carbon dynamics","gist":"A field study examining how agricultural antibiotics and soil warming jointly affect soil carbon dynamics, microbial communities, and antibiotic-resistant genes.","description":"This project investigates the effects of agricultural antibiotic inputs on soil community structure and function within a soil warming field experiment. It measures microbial efficiency to quantify impacts on soil carbon dynamics and assesses the contribution of antibiotic-resistant genes from these inputs. By examining how soil ecosystems respond to combined antibiotic perturbation and climate change, the research determines the full potential impact of these factors to inform sustainable agricultural management practices.","abstract":"Agricultural antibiotic contamination from anthropogenic use is widespread, where they can spread through manure amendments to soil as well as through wind-borne antibiotic deposition. In the United States, livestock production consumed 11 million kg of antibiotics in 2017 alone, and up to 90% of the doses given to livestock enter the environment as un-metabolized and biologically active compounds through feces and/or urine. The project investigates the potentially important, but under-studied, role agricultural antibiotic inputs have on soil ecosystems. Additionally, this research seeks to better understand the susceptibility of particular soil communities and soil functions to antibiotic perturbation and climate change. Thisstudy will be the first to examine the effects of antibiotics inputs in a soil warming field experiment. The results gained from this research will lead to a more complete understanding of the full potential impact antibiotic inputs have on soil community structure and function, and their implications to properly manage our soil optimizing agricultural practices.To assess the effects of agricultural antibiotics and climate change, microbial efficiency will be measured to quantify their impacts on the soil carbon dynamics as well as quantifying the amount of antibiotic resistant genes contributed by antibiotic inputs. Furthermore, the soil community will be assessed for changes in their composition. Ultimately, all of these assessments will determine the impactof agricultural antibiotics on the soil, and will promote a more sustainable agricutural management.","project_type":"Fellowship","lead":"Michael Strickland","affiliation":"CALS Soils and Water Systems","funder":"National Institute of Food and Agriculture/USDA","award_number":"2023-67011-40518","date":"2023","status":"Completed","subject":["soil microbiome","antibiotic resistance","soil carbon","climate change","agricultural antibiotics","soil warming","microbial efficiency"],"confidence":"High","source_url":"https://portal.nifa.usda.gov/enterprise-search/projects/1030871","project_url":"https://www.stricklandlab.com/","funder_agency":"USDA","research_area":"Agriculture"},{"objectid":"kentucky_mcguire_milc_moringa_lactation","title":"The MiLC Study: Moringa in Lactation and Early Childhood","gist":"A randomized trial in Western Kenya testing if Moringa oleifera leaf powder increases breastmilk volume and improves maternal and infant health markers.","description":"This randomized controlled trial evaluates the impact of Moringa oleifera leaf powder supplementation on breastmilk volume, composition, and maternal and infant health among undernourished mothers in Western Kenya. Building on pilot data showing doubled milk volume without nutrient dilution, the study investigates whether daily consumption of 20g of moringa enhances lactation, extends exclusive breastfeeding duration, and improves growth markers like insulin-like growth factor-1 and hemoglobin. By collecting biological samples and health metrics over two years, the research aims to define the role of this nutrient-dense food in supporting vulnerable populations and addressing child undernutrition.","abstract":"Exclusive breastfeeding (EBF) for the first six months of life is estimated to save over 800,000 child deaths\nunder 5 years. In low- and middle-income countries with high rates of child undernutrition, the importance of\nEBF increases further. Despite this, there are limited proven medications or foods to increase milk volume. We\ninvestigated the benefits of a nutrient-dense potential galactagogue, the powdered leaf of the Moringa oleifera\n(moringa), in a pilot randomized controlled trial of moringa leaf powder supplementation in 50 mother-infant\npairs in Western Kenya. We found that mothers consuming 20g of moringa daily for three months had double\nthe volume of breast milk compared to controls, with no dilution of protein and fat content. In addition, infants of\nmothers consuming moringa had increased growth-related hormone insulin-like growth factor-1 (IGF-1) and\nhemoglobin over controls. Our overall objective is to evaluate the effect of moringa on mothers of\nundernourished infants on milk volume, milk composition, EBF rates, and maternal and infant health. We\nhypothesize that moringa supplementation to mothers of undernourished infants increases milk volume,\nenhances milk nutrients, and improves select markers of maternal and infant health. These changes are driven\nby maternal hormonal regulation of lactation, longer duration of EBF, and increased concentration of nutrient\ndelivery to mothers directly and to infants via breastmilk. Design: We will perform a cluster-randomized single-\nblinded controlled trial. Mothers of undernourished infants in Western Kenya will either receive 20g moringa\nleaf powder in corn porridge or corn porridge alone daily for six months with follow-up visits every 3 months for\ntwo years. Milk, serum, and urine samples, dietary variables, and a survey of perceptions of breastfeeding at\nbaseline and periodically throughout the study will be collected. We will perform anthropometrics and collect\ninformation on medical diagnoses and feeding practices at each visit. Aims: 1: Determine the impact of\nmaternal moringa consumption on milk volume and infant milk consumption and investigate mechanisms\ndriving these effects. 2: Quantify the impact of maternal moringa supplementation on duration of EBF and\nconcentrations of selected nutrients in human milk. 3: Assess the effect of moringa supplementation on\nselected indicators of maternal and infant health. Primary outcomes: Comparing between groups, we will\nexamine increases in milk volume, prevalence and duration of EBF, and infant growth via changes in IGF-1.\nSignificance: This trial investigates the role of moringa in lactation and early childhood. This innovative study\nintersects with the NICHD Pediatric Growth and Nutrition Branch priority on understanding how human milk\n“affects the health of the infant and lactating parent” and will define the role of moringa in enhancing lactation\nand supporting maternal and child health in vulnerable populations.","project_type":"Subaward","lead":"Shelley McGuire","affiliation":"CALS Family Consumer Science","partners":"Department of Health and Human Services","funder":"University of Kentucky","award_number":"R01HD114728-01A1","date":"2023","end_year":"2030","status":"Active","subject":["moringa oleifera","lactation","exclusive breastfeeding","infant growth","human milk","maternal nutrition","western kenya"],"confidence":"Medium","source_url":"https://reporter.nih.gov/project-details/11047986","funder_agency":"University partner","research_area":"Health & disease"},{"objectid":"usda_schroeder_infection_onion_bulb","title":"The role of co-infection in onion bulb rot in the Treasure Valley","gist":"Quantifying how combined bacterial and fungal pathogens drive onion bulb rot severity in Idaho's Treasure Valley.","description":"This project investigates the impact of co-infection by multiple bacterial and fungal pathogens on onion bulb rot in the Treasure Valley of Idaho and Eastern Oregon. Although the region produces 30% of the nation's onions, dry conditions do not prevent widespread bacterial presence that causes rot in fields and storage. The University of Idaho will quantify how combinations of these specific pathogens contribute to the severity of bulb rot, addressing a critical threat to regional onion production.","abstract":"The Treasure Valley of Idaho and Eastern Oregon produces approximately 30% of the nation's onions. Despite the dry climate, a wide range of bacteria are present in onion crops and cause bulb rot both within the field and in storage. It is thought that the presence of multiple pathogens will increase the severity of onion bulb rot. The University of Idaho will quantify the contribution of various bacterial and fungal pathogens, in combination, to the development of onion bulb rot.","project_type":"Grant","lead":"Brenda Schroeder","affiliation":"CALS Entomology,Plt Pathology,Nemat","partners":"USDA Agricultural Marketing Service","funder":"Idaho State Department of Agriculture","date":"2023","status":"Active","subject":["onion bulb rot","co-infection","bacterial pathogens","fungal pathogens","onion","treasure valley","crop disease"],"confidence":"High","source_url":"https://www.ams.usda.gov/sites/default/files/media/SCBGPDescriptionofFunds2023.pdf","funder_agency":"USDA","research_area":"Agriculture"},{"objectid":"ai4ui_ucm-daily-register","title":"UCM Daily Register","description":"Editorial pipeline for The Daily Register and My UI. Submission intake, AI-assisted style editing (Claude or OpenAI via MindRouter, with AP + UI style enforcement), word-level diff review, section-organized auto-assembly, and branded .docx export. The application is in advanced user testing with the UCM newsletter team and is ready for repository migration to ui-AI4UI.","significance":"Faster newsletter turnaround. Enforces AP + UI style consistently across issues. Reduces manual editorial burden per issue.","status":"Live","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nih_grieshaber_cell_forms_that_2","title":"Understanding the cell forms that underlie the chlamydial developmental cycle (R21AI180738-01A1)","gist":"Single-cell analysis of gene regulation governing the reticulate, intermediate, and elementary body forms in the Chlamydia developmental cycle.","description":"This project investigates the single-cell mechanisms regulating the three distinct phenotypic forms—reticulate body, intermediate body, and elementary body—that constitute the chlamydial developmental cycle. By addressing how mixed cell populations within the replication niche obscure current understanding, the research utilizes CRISPRi knockdown screens and single-cell spatial gene expression analysis to map gene regulation across four developmental stages. Elucidating these regulatory pathways is critical for dissecting the pathogenesis of Chlamydia species, which cause diseases ranging from trachoma and pneumonia to infertility and atherosclerosis.","abstract":"“Understanding the chlamydial developmental cycle at the single cell level”.\nProject Summary/Abstract\nThe bacteria in the chlamydiales order are obligate intracellular parasites of eukaryotic cells. They are reliant on\na developmental cycle consisting of at least three phenotypically distinct cell forms termed the reticulate body\n(RB), the intermediate body (IB) and the elementary body (EB). The EB is infectious but does not replicate. The\nRB replicates in the host cell but is non-infectious, while the IB is an intermediate form that transitions to the EB\nform. Completion of this developmental cycle is central to chlamydial pathogenesis. Within this order, the genus\nChlamydia contains the causative agents of a number of important pathogens of humans. C. psittaci causes\nzoonotic infections resulting in pneumonia, while C. pneumoniae is a human pathogen that causes respiratory\ndisease and is linked to atherosclerosis. Biovars of C. trachomatis are the causative agents of trachoma, the\nleading cause of preventable blindness worldwide, as well as sexually transmitted infections with the potential to\ncause pelvic inflammatory disease and infertility. Irrespective of the resulting disease, all chlamydial species\nshare the same obligate intracellular life cycle and developmental cell forms. The mechanisms that regulate the\ndevelopment of the distinct cell forms are currently poorly understood. Our preliminary and recently published\ndata indicates the cycle should be broken down into four stages; EB germination, RB\namplification/maturation, IB production, and EB formation. Understanding these forms and their\ncontributions to the developmental cycle and pathogenesis has been obfuscated by the mixed cell environment\nof the chlamydial inclusion. Our data show that the chlamydial replication niche contains mixed phenotypic\ncells as early as after the first few rounds of replication. Therefore, two aims focusing on understanding the\nregulation of gene expression in these populations. In Aim 1, we will develop a CRISPRi knockdown screen\nto assess the role of essential genes on cell type regulation. For Aim 2, the spatial gene expression\npattern of cell type specific genes and the DNA elements that generate this expression pattern will be\ndetermined at the single cell level. Completion of these aims will lead to a more complete understanding of\nthe developmental cycle and allow for careful dissection of the effects of mutations, chemical agents, ectopic\nexpression of regulatory proteins, and therapeutic treatments on the different aspects of the developmental cycle.","project_type":"Grant","lead":"Scott Grieshaber","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Institutes of Health","award_number":"R21AI180738-01A1","date":"2024","end_year":"2026","status":"Active","subject":["chlamydia","developmental cycle","single-cell genomics","intracellular pathogens","gene expression","chlamydiales","pathogenesis"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/10888813","funder_agency":"National Institutes of Health","research_area":"Genomics & molecular biology"},{"objectid":"nih_grieshaber_cell_forms_that","title":"Understanding the cell forms that underlie the chlamydial developmental cycle (R21AI188237)","gist":"Research using CRISPRi screens to map gene regulation and type III secretion translocon expression across Chlamydia developmental cell forms.","description":"This project investigates the regulatory mechanisms governing the distinct cell forms—reticulate body, intermediate body, and elementary body—that drive the obligate intracellular developmental cycle of Chlamydiales bacteria. By employing a CRISPRi knockdown screen to assess essential genes and analyzing the cell-type specific expression of type III secretion system translocons, the research addresses the current lack of understanding regarding how these forms transition and contribute to pathogenesis. The work aims to dissect the effects of mutations and therapeutic treatments on the cycle, providing critical insights into the biology of pathogens responsible for trachoma, respiratory disease, and sexually transmitted infections.","abstract":"Project Summary/Abstract\nThe bacteria in the chlamydiales order are obligate intracellular parasites of eukaryotic cells. They are reliant\non a developmental cycle consisting of at least three phenotypically distinct cell forms termed the reticulate\nbody (RB), the intermediate body (IB) and the elementary body (EB). The EB is infectious but does not\nreplicate. The RB replicates in the host cell but is non-infectious, while the IB is an intermediate form that\ntransitions to the EB form. Completion of this developmental cycle is central to chlamydial pathogenesis. Within\nthis order, the genus Chlamydia contains the causative agents of a number of important pathogens of humans.\nC. psittaci causes zoonotic infections resulting in pneumonia, while C. pneumoniae is a human pathogen that\ncauses respiratory disease and is linked to atherosclerosis. Biovars of C. trachomatis are the causative agents\nof trachoma, the leading cause of preventable blindness worldwide, as well as sexually transmitted infections\nwith the potential to cause pelvic inflammatory disease and infertility. Irrespective of the resulting disease, all\nchlamydial species share the same obligate intracellular life cycle and developmental cell forms. The\nmechanisms that regulate the development of the distinct cell forms are currently poorly understood. Our\npreliminary and published data indicates the cycle should be broken down into four stages; EB germination,\nRB amplification/maturation, IB production, and EB formation. Understanding these forms and their\ncontributions to the developmental cycle and pathogenesis has been obfuscated by the mixed cell environment\nof the chlamydial inclusion which occurs as early as after the first few rounds of replication. Therefore, we will\npursue two aims focused on understanding the regulation of gene expression in these populations, and the\nimpact this regulation has on the infectious cycle. In Aim 1, we will develop a CRISPRi knockdown screen\nto assess the role of essential genes on cell type regulation. Cell type function is likely crucial in\nestablishing the developmental cycle, facilitating amplification and disseminating the infection. Chlamydia has\ntwo typeIII secretion system translocons that are expressed in distinct cell types. The translocon is involved in\ninteracting with target host cells to secrete effectors across the target cell membranes, thus facilitating\ncommunication between the bacteria and the host cell. In Aim 2, we will investigate the role of cell type\nspecific expression of the two typeIII secretion system translocons. Completion of these aims will lead to\na more complete understanding of the regulation underlying the developmental cycle, allowing for careful\ndissection of the effects of mutations, chemical agents, ectopic expression of regulatory proteins, and\ntherapeutic treatments on the different aspects of the cycle.","project_type":"Grant","lead":"Scott Grieshaber","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","funder":"National Institutes of Health","award_number":"R21AI188237","date":"2025","end_year":"2026","status":"Active","subject":["chlamydia","developmental cycle","reticulate body","elementary body","type iii secretion system","gene regulation","intracellular pathogens"],"confidence":"Medium","source_url":"https://reporter.nih.gov/project-details/11035665","project_url":"https://github.com/SGrasshopper/Single-Cell-FISH-quantification","funder_agency":"National Institutes of Health","research_area":"Genomics & molecular biology"},{"objectid":"usda_hohenlohe_genomic_consequences_introgress","title":"Understanding the genomic consequences of introgression and isolation on salmonid species to inform conservation and management","project_type":"Cooperative Agreement","lead":"Paul Hohenlohe","affiliation":"COS Biological Sciences","funder":"USDA Forest Service","date":"2023","status":"Active","subject":["salmonids","introgression","population genomics","conservation genetics","isolation","genomic consequences","fisheries management"],"confidence":"Medium","source_url":"https://hohenlohelab.github.io/","project_url":"https://hohenlohelab.github.io/","funder_agency":"USDA","research_area":"Genomics & molecular biology"},{"objectid":"ai4ui_universo","title":"UniVerso","description":"Conversational research discovery platform: users search and discover UI research through natural-language queries, powered by vector search (ChromaDB) and LLM-generated overviews. Surfaces researchers, projects, and outputs across the university to internal and external audiences. Uniquely uses a MongoDB + ChromaDB stack rather than the Postgres + UDM line shared by the AI4RA-aligned projects.","significance":"Lowers the barrier to discovering what UI researchers do — internally for cross-unit collaboration, externally for partners and prospective collaborators. Library-led complement to the ORED-led research-administration stack.","status":"Live","subject":["artificial intelligence"],"confidence":"High","source_url":"https://universo.insight.uidaho.edu","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"usda_ripley_usfs_north_lidar","title":"USFS North Idaho LiDAR Collaborative Demonstration Project","gist":"Geiger-mode LiDAR digital-forest demonstration on North Idaho national forests.","description":"A University of Idaho and USDA Forest Service collaboration, led by Bruce Ripley, building a prototype digital-forest data model from Geiger-mode LiDAR on the Nez Perce-Clearwater and Idaho Panhandle National Forests. Run through the College of Natural Resources, it demonstrates individual-tree forest measurement and analytics for site-specific national-forest management.","project_type":"Contract","lead":"Bruce Ripley","affiliation":"CNR Idaho Forest Innovations Lab-918 DO NOT USE See RCI 3979/918 FII","funder":"USDA Forest Service","date":"2025","status":"Active","subject":["lidar","forestry","forest inventory","canopy structure","remote sensing","north idaho"],"confidence":"Medium","funder_agency":"USDA","research_area":"Forestry"},{"objectid":"usda_kimsey_usfs_region_silviculture","title":"USFS Region 6 Silviculture Research","gist":"Site-specific stand-density and silviculture research with the USFS Pacific Northwest Region.","description":"A University of Idaho and USDA Forest Service (Pacific Northwest Region) cooperative effort, led by Mark Kimsey, on site-specific stand management. It advances density-management guidance that accounts for forest nutrition and stand resilience to drought, insects, disease, and fire, continuing a University of Idaho and Forest Service partnership on forest stand management that dates to 1981.","project_type":"Contract","lead":"Mark Kimsey","affiliation":"CNR Intermountain Forestry Coop-633 (IFTNC)","funder":"USDA Forest Service","date":"2025","status":"Active","subject":["silviculture","forest management","regeneration","thinning","stand density","timber harvesting","forest ecology"],"confidence":"Medium","funder_agency":"USDA","research_area":"Forestry"},{"objectid":"usgs_conway_usgs_phase_demography","title":"USGS Phase I Demography of Squirrel - FY23","gist":"Field experiment measuring how forest thinning and burning affect Northern Idaho Ground Squirrel habitat and population demographics.","description":"This project evaluates the effectiveness of forest restoration actions, such as thinning and burning, in restoring habitat and increasing the population size of the threatened Northern Idaho Ground Squirrel. By collecting post-treatment demographic data on experimental plots, the research addresses a primary need identified in the species' recovery plan to determine if specific treatments can provide essential habitat. The findings enable land management agencies to implement forest prescriptions that reduce fuel buildup and fire risk without harming the federally listed species, potentially facilitating its recovery and delisting.","abstract":"PROJECT TITLE   USGS PHASE I DEMOGRAPHY OF NORTHERN IDAHO GROUND SQUIRRELS INSERT PROJECT PERIOD JANUARY 25, 2023   JULY 31, 2026PROJECT OBJECTIVES  FIRE SUPPRESSION HAS CAUSED A BUILD UP OF FUELS IN CONIFEROUS FORESTS IN THE WESTERN U.S. LAND MANAGEMENT AGENCIES MUST ENSURE THAT TREATMENT PRESCRIPTIONS TO REDUCE FUEL BUILD UP AND REDUCE FIRE RISK WILL NOT ADVERSELY AFFECT THE SPECIES PRESENT. RECIPIENT HAS IMPLEMENTED A FIELD EXPERIMENT TO EVALUATE THE EFFECTIVENESS OF DIFFERENT FOREST RESTORATION ACTIONS REGARDING THEIR ABILITY TO RESTORE NORTHERN IDAHO GROUND SQUIRREL HABITAT AND INCREASE POPULATION SIZE OF THIS THREATENED GROUND SQUIRREL. THE PROJECT ADDRESSES A PRIMARY RESEARCH NEED IDENTIFIED IN THE GROUND SQUIRREL S RECOVERY PLAN AND WILL HELP DETERMINE WHETHER SPECIFIC FOREST RESTORATION TREATMENTS CAN BE IMPLEMENTED TO PROVIDE ESSENTIAL HABITAT FOR THIS RARE SPECIES. NUMEROUS AGENCIES AND ORGANIZATIONS HAVE WORKED TOGETHER FOR THE PAST 9 YEARS TO MEASURE DEMOGRAPHIC TRAITS OF NORTHERN IDAHO GROUND SQUIRRELS ON PLOTS PRIOR TO RESTORATION TREATMENT (PRE TREATMENT), AND RECIPIENT RECENTLY BEGAN THE POST TREATMENT PHASE OF THE PROJECT AT SOME SITES  THREE EXPERIMENTAL TREATMENTS WERE IMPLEMENTED IN 2018 2021, AND THE REMAINING TWO EXPERIMENTAL TREATMENTS ARE PLANNED SOON (IN 2022 2023). THE NEXT FEW YEARS WILL PROVIDE POST TREATMENT DATA THAT WILL ALLOW THE TEAM OF SCIENTISTS AND MANAGERS TO EVALUATE THE EFFECTS OF THE RESTORATION ACTIONS. THE RESULTS OF THIS PROJECT WILL ALLOW THE USFS AND OTHER LAND MANAGEMENT AGENCIES TO WRITE, PLAN, AND IMPLEMENT FOREST MANAGEMENT PRESCRIPTIONS WITHIN CONIFER FORESTS WITHOUT HARMING (AND POTENTIALLY HELPING) THE FEDERALLY LISTED NORTHERN IDAHO GROUND SQUIRREL. THE RESULTS WILL PROVIDE THE INFORMATION NECESSARY SO THAT FOREST MANAGEMENT CAN PROCEED WHILE STILL ADHERING TO ESA. NORTHERN IDAHO GROUND SQUIRREL ARE RANKED HIGH IN TERMS OF RECOVERY POTENTIAL (U.S. FISH AND WILDLIFE SERVICE 2003) BECAUSE RELATIVELY FEW CONSTRAINTS STAND IN THE WAY OF SPECIES RECOVERY AND HABITAT RESTORATION VIA FOREST TREATMENTS IS THOUGHT TO BE ALL THAT IS NEEDED. HENCE, THIS PROJECT MAY HELP IDENTIFY AN EFFECTIVE PRESCRIPTION THAT WILL SIMULTANEOUSLY REDUCE FUELS AND ALSO RECOVER AND DE LIST A FEDERALLY THREATENED SPECIES.ACTIVITIES TO BE PERFORMED TRAP AND MARK SQUIRRELS ON EXPERIMENTAL PLOTS.ATTACH RADIO TRANSMITTERS TO SUBSET OF SQUIRRELS AND FOLLOW TO IDENTIFY HIBERNACULA LOCATIONS.MAP PERIMETER OF SQUIRREL COLONIES AT EXPERIMENTAL PLOTS.MEASURE VEGETATION PARAMETERS ON EXPERIMENTAL PLOTS.DELIVERABLES AND EXPECTED OUTCOMES ANNUAL REPORT AND FINAL REPORT. EXPECTED OUTCOMES INCLUDE THE RELATIVE SUITABILITY OF FOREST RESTORATION PRACTICES FOR NORTHERN IDAHO GROUND SQUIRRELS (I.E., THE SUITABILITY OF THINNING AND BURNING AS A METHOD TO RECOVER POPULATIONS).INTENDED BENEFICIARIES) U.S. FOREST SERVICE, U.S. FISH AND WILDLIFE SERVICE, STATE WILDLIFE AGENCY (IDAHO DEPARTMENT OF FISH AND GAME).","project_type":"Cooperative Agreement","lead":"Courtney Conway","affiliation":"CNR Co-Op Fish & Wildlife Res Unit","funder":"US Geological Survey","date":"2023","status":"Active","subject":["northern idaho ground squirrel","demography","habitat restoration","forest thinning","prescribed fire","population dynamics","endangered species"],"confidence":"High","source_url":"https://www.usaspending.gov/award/ASST_NON_G23AC00122_014","project_url":"https://courtneyjconway.wixsite.com/conwaylab/species-declines","funder_agency":"U.S. Geological Survey","research_area":"Ecology & wildlife"},{"objectid":"dod_zhang_assisted_high_content","title":"USU-UI: AI-assisted, high-content identification of astrocyte signaling factors with therapeutic potential for chronic pain","gist":"AI-driven identification of astrocyte signaling factors for chronic pain therapeutics.","description":"This project applies artificial intelligence tools to analyze astrocyte signaling factors involved in chronic pain. By leveraging high-content identification methods, the research seeks to uncover specific therapeutic targets that could lead to new treatments. The work addresses the critical need for effective interventions in managing chronic pain conditions.","abstract":"$692,298 to apply artificial intelligence tools to better understand chronic pain and identify potential therapeutic targets, led by U of I researcher Boyu Zhang.","project_type":"Subaward","lead":"Boyu Zhang","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","partners":"Uniformed Services University of the Health Sciences","funder":"The Henry M. Jackson Foundation for The Advancement of Military Medicine, Inc.","date":"2025","status":"Active","subject":["chronic pain","astrocytes","artificial intelligence","high-content screening","therapeutic targets","neuroscience","signaling pathways"],"confidence":"High","source_url":"https://www.uidaho.edu/newsroom/biomedical-research-partnership","funder_agency":"Department of Defense","research_area":"Health & disease"},{"objectid":"dod_ytreberg_leveraging_protein_degradation","title":"USU-UI: Leveraging Protein Degradation to Combat Vector-Borne Diseases","gist":"Research led by Frederick \"Marty\" Ytreberg uses targeted protein degradation to disrupt disease transmission in mosquitoes.","description":"This project explores targeted protein degradation approaches to disrupt disease transmission in vectors such as mosquitoes. Led by Frederick \"Marty\" Ytreberg at the University of Idaho, the research is funded by the Uniformed Services University of the Health Sciences through The Henry M. Jackson Foundation for The Advancement of Military Medicine. The initiative seeks to utilize specific degradation mechanisms to combat vector-borne diseases.","abstract":"$1,493,290 to explore targeted protein degradation approaches to disrupt disease transmission in vectors such as mosquitoes, led by U of I researcher Frederick “Marty” Ytreberg.\n\n […] \n\n“Leveraging Protein Degradation to Combat Vector-borne Diseases” was funded to University of Idaho by Uniformed Services University of the Health Sciences under award HJFAward #68027. The total project funding is $429,643, of which 100% is the federal share.","project_type":"Subaward","lead":"Marty Ytreberg","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","partners":"Uniformed Services University of the Health Sciences","funder":"The Henry M. Jackson Foundation for The Advancement of Military Medicine, Inc.","date":"2025","status":"Active","subject":["protein degradation","vector-borne diseases","mosquitoes","targeted protein degradation","disease transmission","insect vectors"],"confidence":"High","source_url":"https://www.uidaho.edu/newsroom/biomedical-research-partnership","funder_agency":"Department of Defense","research_area":"Health & disease"},{"objectid":"dod_xu_machine_learning_models","title":"USU-UI: Machine learning models to improve diagnostic screening of PTSD","gist":"Machine learning models integrate wearable biosensor data to improve PTSD diagnostic accuracy and early detection.","description":"This project develops machine learning models to integrate data from smart wearable devices, biochemical markers, and biophysical signals for improved PTSD screening and diagnosis. Funded by a collaborative DoD grant, the initiative leverages multimodal biosensor data to identify biological signatures of the disorder. The work aims to enhance diagnostic accuracy and support early detection efforts for clinicians treating this complex multifaceted condition.","abstract":"The first award — a $4.2 million collaborative DoD-funded project, with $974,000 going to U of I — will examine how smart wearable devices, biochemical markers and biophysical signals can be integrated to improve PTSD screening and diagnosis.\n\nThis multi-institutional effort includes co-principal investigators Manish Bhomia from Uniformed Services University, Dr. Christina La Croix from Walter Reed National Military Medical Center, Sameer Sonkusale from Tufts University, Dr. Steven Cohen from Northwestern University, and CJ Brush from Auburn University. Xu’s team at U of I will develop the machine learning models to identify how biomarker and biophysical data collected from wearable technologies can be leveraged to improve diagnostic accuracy for PTSD.\n\n“PTSD is a complex multifaceted disorder,” Xu said. “By applying machine learning models to this multimodal biosensor data, we can better understand the biological signatures of PTSD and help clinicians improve diagnosis and early detection.”","project_type":"Subaward","lead":"Colin Xu","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","partners":"Uniformed Services University of the Health Sciences","funder":"The Henry M. Jackson Foundation for The Advancement of Military Medicine, Inc.","date":"2025","status":"Active","subject":["post-traumatic stress disorder","machine learning","wearable sensors","biomarkers","diagnostic screening","biosensors","multimodal data"],"confidence":"High","source_url":"https://www.uidaho.edu/newsroom/colin-xu-dod-grants","funder_agency":"Department of Defense","research_area":"Health & disease"},{"objectid":"dod_xu_predicting_psychiatric_risk","title":"USU-UI: Predicting psychiatric risk in servicemember families during deployment and reunion","gist":"Machine learning analysis of military family healthcare records to predict risks of violence, substance misuse, suicidality, and injury across deployment cycles.","description":"This project applies machine learning models to large-scale, longitudinal military family healthcare records to identify predictors of family violence, substance misuse, suicidality, and injury. By analyzing how these risk factors unfold across pre-deployment, deployment, and post-deployment phases, the research distinguishes subgroups of military families at elevated risk. The work provides clinicians with insights into the timing and interaction of specific risk factors to enable earlier and more targeted interventions for servicemember families navigating deployment-related stress.","abstract":"The second award — totaling $1.9 million, with $361,000 supporting U of I research — focuses on understanding how deployment-related stress affects military families and increases risk for harmful behaviors.\n\nXu’s team will partner with co-principal investigators Elizabeth Hisle-Gorman, Christin Ogle and Dr. Stephen Cozza at Uniformed Services University to identify predictors of family violence, substance misuse, suicidality and injury in military families.\n\nBy applying machine learning models to large-scale, longitudinal military family healthcare records, the project seeks to identify risk factors of harmful behaviors within military families and understand how these risk factors unfold across pre-deployment, deployment and post-deployment phases.\n\nXu’s machine learning models will help identify subgroups of military families at elevated risk — as well as the timing and interaction of risk factors — to support earlier and more targeted interventions.\n\n“Military families navigate unique stressors throughout the deployment cycle,” Xu said. “Our work aims to give clinicians better insight into who may be at elevated risk, and when, so that support can be provided proactively.”","project_type":"Subaward","lead":"Colin Xu","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","partners":"Uniformed Services University of the Health Sciences","funder":"The Henry M. Jackson Foundation for The Advancement of Military Medicine, Inc.","date":"2025","status":"Active","subject":["military families","psychiatric risk","family violence","substance misuse","suicidality","machine learning","deployment stress"],"confidence":"Medium","source_url":"https://www.uidaho.edu/newsroom/colin-xu-dod-grants","project_url":"https://colinxu5.github.io/","funder_agency":"Department of Defense","research_area":"Health & disease"},{"objectid":"dod_ridenhour_long_term_effect","title":"USU-UI: The Long-term Effect of HIV on Medical Readiness, Duty-Limiting Medical Conditions, and Service Retention","gist":"This study examines how long-term HIV infection affects military medical readiness, duty-limiting conditions, and service retention to support U.S. service members.","description":"Led by Benjamin Ridenhour, this project investigates the long-term health effects of HIV on medical readiness, duty-limiting conditions, and service retention within the U.S. military. Funded by the Department of Defense through a partnership between the University of Idaho and Uniformed Services University, the research aims to address real-world health challenges facing service members. The study seeks to understand how chronic HIV infection impacts a service member's ability to remain on duty and retain their position in the armed forces.","project_type":"Subaward","lead":"Benjamin Ridenhour","affiliation":"RCI Inst for Interdisc Data Sci- (IIDS) 897","partners":"Uniformed Services University of the Health Sciences","funder":"The Henry M. Jackson Foundation for The Advancement of Military Medicine, Inc.","date":"2025","status":"Active","subject":["hiv","military health","service retention","medical readiness","chronic disease","duty-limiting conditions","epidemiology"],"confidence":"Medium","source_url":"https://www.uidaho.edu/newsroom/biomedical-research-partnership","project_url":"https://www.uidaho.edu/newsroom/biomedical-research-partnership","funder_agency":"Department of Defense","research_area":"Health & disease"},{"objectid":"usda_murdoch_validation_characterization_loci","title":"Validation and characterization of loci associated with fetal loss in dairy cattle","gist":"Validating genomic regions and genes linked to fetal loss in Holstein cattle to reduce annual industry losses without compromising milk production.","description":"This project validates and characterizes genomic regions linked to fetal loss in Holstein dairy cattle by analyzing genetic data from 10,500 animals, including heifers and cows with spontaneous abortions or successful calvings. Researchers will identify specific genes, regulatory regions, and structural variations associated with abortion while assessing whether breeding for reduced fetal loss negatively impacts milk production. The work addresses a cause of over $1 billion in annual industry losses by clarifying the genetic mechanisms behind abortion to facilitate targeted reduction strategies.","abstract":"Fetal loss in cattle is estimated to result in losses of over $1 billion annually, yet little is known about the underlying causes of these abortions. The goal of this proposal is to identify genomic regions associated with abortion in Holstein dairy cattle and to determine if breeding for a decrease in abortions would negatively impact milking performance.The characterization of the genetic causes underlying abortion will enhance our understanding of the mechanisms of abortion and facilitate reducing the incidence of abortion in cattle.This proposal extends our preliminary study that identified genomic regions associated with fetal loss in cattle. The specific aims of this proposal are to: 1) identify and validate genomic regions associated with fetal loss in 500 Holstein heifers (cattle that are pregnant with their first calf)and 500 primiparous cows (cows pregnant with their second calf) experiencing a spontaneous abortion (cases) and 5000 heifers and 5000 cows that calve at term or after 260 days of gestation (controls); 2) characterize the genes, gene regulatory regions and duplications or deletions of the genomic regions; and 3) identify if selectingfor reducing fetal loss is unfavorably correlated with production traits.","project_type":"Grant","lead":"Brenda Murdoch","affiliation":"CALS Animal, Vet & Food Sciences","partners":"National Institute of Food and Agriculture/USDA","funder":"Washington State University","award_number":"2023-67015-39524","date":"2023","status":"Active","subject":["fetal loss","dairy cattle","genomic selection","holstein","reproductive traits","genetic correlation","abortion"],"confidence":"High","source_url":"https://web.archive.org/web/20250501025412/https://portal.nifa.usda.gov/web/crisprojectpages/1030213-validation-and-characterization-of-loci-associated-with-fetal-loss-in-dairy-cattle.html","funder_agency":"University partner","research_area":"Genomics & molecular biology"},{"objectid":"nasa_li_vandal_robotics_club","title":"Vandal Robotics Club","project_type":"Grant","lead":"Johnny Li","affiliation":"CALS Soils and Water Systems","partners":"National Aeronautic Space Ad.","funder":"NASA Idaho Space Grant Consortium","date":"2023","status":"Active","subject":["robotics","engineering","automation","mechanical design","electronics","programming","student organizations"],"confidence":"Medium","source_url":"https://web.archive.org/web/20220128031740/https://www.uidaho.edu/engr/services/student-services/clubs-and-organizations/robotics","project_url":"https://web.archive.org/web/20220128031740/https://www.uidaho.edu/engr/services/student-services/clubs-and-organizations/robotics","funder_agency":"NASA","research_area":"Other"},{"objectid":"ai4ui_vandalizer","title":"Vandalizer","description":"Open-source, self-hosted platform for AI-powered document review and data extraction, purpose-built for research administration. Structured LLM extraction, workflow engine, citation-backed RAG chat, multi-tenant workspaces. Developed under the AI4RA NSF GRANTED partnership and deployed at UI and Southern Utah University.","significance":"Staff time savings on document extraction. Higher extraction accuracy. Reusable extraction workflows. Citation-backed Q&A over RA document collections.","status":"Live","subject":["artificial intelligence"],"confidence":"High","source_url":"https://vandalizer.uidaho.edu","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_sidearm-pipeline","title":"Vandals Stats Pipeline","description":"Internal athletics data warehouse that ingests public Sidearm boxscores and season statistics, normalizes game and player history in PostgreSQL, preserves source provenance and coverage windows, and gives Sports Information Directors an evidence-backed workspace for record-book research, notable-achievement review, and downstream website-ready data. Release 1 is internal-SID-first; public website integration is deferred.","significance":"Turns fragmented public athletics statistics into a durable institutional record, reduces manual record-book research, and gives Athletics staff faster access to evidence they can confidently use in coverage and website publishing.","status":"Building","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"ai4ui_water-law-database","title":"Water Law Database","description":"Tiered repository of Idaho water law centered on the Snake River Basin Adjudication (SRBA): judicial decisions, historical records, and key settlements, ingested from the existing system and from paper documents via large-scale OCR on IIDS's on-prem GPU cluster. A web interface supports natural-language queries and visualizations such as diversion maps, giving legislators, water managers, and rights holders fast, verified answers instead of relitigating past disputes. Stakeholder feedback sessions are being scheduled to validate needs and priorities for the next phase.","significance":"Reduces water-law inquiry and search time from archival research to a verified lookup. Preserves institutional memory of settled disputes for the state's water stakeholders.","status":"Exploring","subject":["artificial intelligence"],"confidence":"High","research_area":"Data science & computing","parent_project":"ai4ui"},{"objectid":"nih_rowley_yevo_high_school","title":"yEvo: a high school lab for teaching evolution and genomics","gist":"yEvo enables high school students to use whole genome sequencing to experimentally observe yeast evolving antifungal resistance in an authentic research setting.","description":"The yEvo project establishes a high school laboratory where students utilize experimental evolution and whole genome sequencing to observe how baker's yeast develops resistance to antifungal medication. By engaging learners in authentic research that generates publishable data, the initiative addresses the difficulty of teaching evolution as an active, ongoing process rather than a historical concept. This work contextualizes modern public health crises like drug resistance while fostering student understanding of scientific inquiry and potential STEM career pathways through a scalable, collaborative model.","abstract":"Abstract\nEvolution is a core concept in understanding nearly all of the life sciences. Better public\nunderstanding of evolution can also better contextualize and even prevent modern public health\ncrises such as the emergence of antifungal and antibiotic resistance, and evolution of new viral\npathogens, as just a few examples. Despite the importance of evolution, it can be difficult to teach\nwell in secondary education. Many treatments focus on historical evolution and fail to convey that\nevolution is an active, ongoing process. These strategies also don't make it clear that the study of\nevolution is itself an innovative, multidisciplinary field, which encompasses not just powerful\ncomparisons of historical fossils and inferences from modern day extant organisms and genomes, but\nalso experimental investigations, where hypotheses can be tested and evolution can be observed in\naction in the lab and in the environment. We propose to develop yEvo, a teaching lab where students\nin high school classes use experimental evolution and whole genome sequencing to study how\nbakers yeast can become resistant to a low dose of an over-the-counter antifungal. The yEvo project\nis a close collaboration with university researchers, involving students in an authentic research project\ndesigned to generate publishable data. In the new project, we will build on a successful pilot\nimplementation to 1. professionalize our curriculum materials, 2. build tools that will allow high school\nstudents to analyze and visualize their own sequencing data, and share it among classrooms, 3.\nscale to more schools and scientists using a novel \"franchising\" model, and 4. build standalone kits\nthat capture the essence of the yEvo experience with lower resource and personnel requirements,\nallowing us to reach even more schools. We will accompany these new projects with evaluations that\nallow us to improve the teaching materials as we go, and also test them to ensure they are improving\nstudent understanding of evolution, scientific research, and their own potential to pursue STEM\ncareers.","project_type":"Grant","lead":"Paul Rowley","affiliation":"COS Biological Sciences","funder":"National Institutes of Health","award_number":"R25GM154336","date":"2024","end_year":"2029","status":"Active","subject":["experimental evolution","yeast","antifungal resistance","whole genome sequencing","science education","genomics","evolution"],"confidence":"High","source_url":"https://reporter.nih.gov/project-details/10887875","project_url":"https://yevo.org/","funder_agency":"National Institutes of Health","research_area":"Genomics & molecular biology"}]};
